          <span class="stakes-lbl">ADMIN BANKROLL:</span>
          <button class="stake-btn active" data-s="poor" onclick="App.setStake('poor')">Casual $1K</button>
          <button class="stake-btn" data-s="middle" onclick="App.setStake('middle')">High Roller $10K</button>
          <button class="stake-btn" data-s="whale" onclick="App.setStake('whale')">Whale $100K</button>
          <button class="stake-btn" data-s="millionaire" onclick="App.setStake('millionaire')">Millionaire $1M</button>
          <button class="stake-btn" data-s="billionaire" onclick="App.setStake('billionaire')">Billionaire $1B</button>
        </div>
