          <div class="cat-tab active" data-f="all" onclick="Nav.go('home','all')">All games</div>
          <div class="cat-tab" data-f="originals" onclick="Nav.go('home','originals')">Originals</div>
          <div class="cat-tab" data-f="slots" onclick="Nav.go('home','slots')">Slots</div>
          <div class="cat-tab" data-f="tables" onclick="Nav.go('home','tables')">Table games</div>
          <div class="cat-tab" data-f="specialty" onclick="Nav.go('home','specialty')">Specialty</div>
        </div>
