      <!-- SPORTS -->
      <div class="page" id="page-sports">
        <div class="sports-hero"><h2>SPORTSBOOK</h2><div class="hint">Singles &amp; accumulators · odds include a bookmaker margin · results are simulated with true probabilities</div></div>
        <div class="sport-tabs" id="sport-tabs"></div>
        <div class="sports-layout">
          <div class="sports-main" id="sports-main"></div>
          <div class="bet-slip">
            <h4>BET SLIP</h4>
            <div class="seg" id="slip-mode"><button class="on" data-m="single" onclick="Sports.setMode('single')">Singles</button><button data-m="acca" onclick="Sports.setMode('acca')">Accumulator</button></div>
            <div id="slip-items"><div class="slip-empty">Select odds to add picks</div></div>
            <div id="slip-footer" style="display:none;flex-direction:column;gap:8px">
              <div class="tot"><span>Total odds</span><b id="slip-odds">1.00</b></div>
              <div class="inp-wrap"><span class="cur">$</span><input id="slip-stake" type="number" value="10" min="1" oninput="Sports.updateSlip()"/></div>
              <div class="tot"><span>Total stake</span><b id="slip-total">$0.00</b></div>
              <div class="tot"><span>Potential return</span><b id="slip-pwin">$0.00</b></div>
              <button class="act gold" onclick="Sports.place()">PLACE BET</button>
            </div>
            <div class="lbl" style="margin-top:10px">My open bets</div>
            <div class="my-bets" id="my-bets"><div class="hint">No open bets.</div></div>
          </div>
        </div>
      </div>

      <!-- PROFILE -->
      <div class="page" id="page-profile"><div class="pad" id="prof-inner">
        <div id="prof-out" style="text-align:center;padding:60px 20px">
          <div style="font-size:54px;margin-bottom:10px">🔒</div>
          <div class="h-page">SIGN IN TO VIEW PROFILE</div>
          <div class="hint" style="margin-bottom:16px">Create a local account to keep separate balances and stats.</div>
          <button class="btn btn-primary" onclick="Auth.open('signup')">Create account</button>
        </div>
        <div id="prof-in" style="display:none">
          <div class="prof-hdr"><div class="prof-av" id="prof-av">?</div><div><h2 id="prof-name">Player</h2><div class="hint" id="prof-since"></div><div class="prof-level">VIP LEVEL <span id="prof-lvl">1</span></div><div class="vip-bar"><i id="vip-fill" style="width:0"></i></div><div class="hint" id="vip-txt" style="margin-top:3px"></div></div></div>
          <div class="stat-grid">
            <div class="stat-card"><div class="stat-val w" id="ps-wagered">$0</div><div class="stat-lbl">Wagered</div></div>
            <div class="stat-card"><div class="stat-val w" id="ps-won">$0</div><div class="stat-lbl">Returned</div></div>
            <div class="stat-card"><div class="stat-val" id="ps-pnl">$0</div><div class="stat-lbl">Net P&amp;L</div></div>
            <div class="stat-card"><div class="stat-val gold" id="ps-big">$0</div><div class="stat-lbl">Biggest win</div></div>
            <div class="stat-card"><div class="stat-val w" id="ps-bets">0</div><div class="stat-lbl">Total bets</div></div>
            <div class="stat-card"><div class="stat-val w" id="ps-wr">0%</div><div class="stat-lbl">Win rate</div></div>
          </div>
          <div class="panel"><h3>PROFIT CURVE</h3><canvas id="prof-chart" style="width:100%;height:150px;display:block"></canvas></div>
          <div class="panel"><h3>ACHIEVEMENTS</h3><div id="prof-ach"></div></div>
          <div class="panel"><h3>BY GAME</h3><div id="prof-games"></div></div>
          <div class="panel"><h3>RECENT BETS</h3><div id="hist-list"></div><button class="btn btn-primary" style="margin-top:10px" onclick="Prof.csv()">⬇ Export bets (CSV)</button></div>
        </div>
      </div></div>

