      <div class="page" id="page-promos"><div class="pad">
        <div class="h-page">PROMOTIONS</div>
        <div id="promo-list"></div>
        <div class="panel" style="margin-top:18px"><h3>REDEEM CODE</h3>
          <div class="promo-row"><input class="promo-in" id="promo-in" placeholder="Enter code..."/><button class="btn btn-primary" onclick="Promo.redeem()">Redeem</button></div>
          <div class="hint" id="promo-msg" style="margin-top:8px"></div></div>
      </div></div>

      <!-- SETTINGS -->
      <div class="page" id="page-settings"><div class="pad" style="max-width:760px">
        <div class="h-page">SETTINGS</div>
        <div class="panel"><h3>APPEARANCE</h3>
          <div class="settings-row"><span class="settings-lbl">Accent colour</span><div style="display:flex;gap:8px" id="theme-dots"></div></div>
          <div class="settings-row"><span class="settings-lbl">Reduce animations</span><label class="toggle"><input type="checkbox" id="set-noanim" onchange="Settings.set('noAnim',this.checked)"><span class="tk"></span></label></div>
          <div class="settings-row"><span class="settings-lbl">Compact game grid<div class="settings-sub">Smaller cards, more games on screen</div></span><label class="toggle"><input type="checkbox" id="set-compact" onchange="Settings.set('compact',this.checked)"><span class="tk"></span></label></div>
          <div class="settings-row"><span class="settings-lbl">Show live bets feed<div class="settings-sub">The simulated players panel</div></span><label class="toggle"><input type="checkbox" id="set-live" onchange="Settings.set('live',this.checked)"><span class="tk"></span></label></div>
          <div class="settings-row"><span class="settings-lbl">Win confetti<div class="settings-sub">Celebrate payouts of 20× or more</div></span><label class="toggle"><input type="checkbox" id="set-confetti" onchange="Settings.set('confetti',this.checked)"><span class="tk"></span></label></div>
          <div class="settings-row"><span class="settings-lbl">Hide balance</span><label class="toggle"><input type="checkbox" id="set-hidebal" onchange="Settings.set('hideBal',this.checked)"><span class="tk"></span></label></div>
        </div>
        <div class="panel"><h3>SOUND</h3>
          <div class="settings-row"><span class="settings-lbl">Sound effects</span><label class="toggle"><input type="checkbox" id="set-sound" onchange="Settings.set('sound',this.checked)"><span class="tk"></span></label></div>
          <div class="settings-row"><span class="settings-lbl">Test sound</span><button class="btn btn-outline" onclick="snd('win')">▶ Play</button></div>
          <div class="settings-row"><span class="settings-lbl">Volume</span><input type="range" id="set-vol" min="0" max="100" style="max-width:240px" oninput="Settings.set('vol',+this.value)"></div>
        </div>
        <div class="panel"><h3>GAMEPLAY</h3>
          <div class="settings-row"><span class="settings-lbl">Quick mode<div class="settings-sub">Skip long animations (slots, plinko, roulette)</div></span><label class="toggle"><input type="checkbox" id="set-quick" onchange="Settings.set('quick',this.checked)"><span class="tk"></span></label></div>
          <div class="settings-row"><span class="settings-lbl">Keyboard shortcuts<div class="settings-sub">Space = play · M = mute · / = search</div></span><label class="toggle"><input type="checkbox" id="set-keys" onchange="Settings.set('keys',this.checked)"><span class="tk"></span></label></div>
          <div class="settings-row"><span class="settings-lbl">Default bet<div class="settings-sub">Fixed starting bet in every game (blank = automatic)</div></span><input class="f-in" id="set-defbet" type="number" min="0" placeholder="auto" style="max-width:160px" onchange="Settings.num('defBet','set-defbet')"></div>
          <div class="settings-row"><span class="settings-lbl">Auto-bet: stop on win of<div class="settings-sub">Stops auto-bet when one round pays this multiple or more</div></span><input class="f-in" id="set-autowin" type="number" min="0" placeholder="off (×)" style="max-width:160px" onchange="Settings.num('autoWin','set-autowin')"></div>
          <div class="settings-row"><span class="settings-lbl">Auto-bet: stop after losing<div class="settings-sub">Stops auto-bet once this amount is lost in the run</div></span><input class="f-in" id="set-autoloss" type="number" min="0" placeholder="off" style="max-width:160px" onchange="Settings.num('autoLoss','set-autoloss')"></div>
          <div class="settings-row"><span class="settings-lbl">Confirm large bets</span><label class="toggle"><input type="checkbox" id="set-confirm" onchange="Settings.set('confirm',this.checked)"><span class="tk"></span></label></div>
          <div class="settings-row"><span class="settings-lbl">Confirm threshold</span><input class="f-in" id="set-thresh" type="number" style="max-width:160px" onchange="Settings.set('thresh',+this.value||10000)"></div>
          <div class="settings-row"><span class="settings-lbl">Currency symbol</span><select class="f-in" id="set-cur" onchange="Settings.set('cur',this.value)"><option value="$">USD ($)</option><option value="€">EUR (€)</option><option value="£">GBP (£)</option><option value="₿">BTC (₿)</option><option value="Ξ">ETH (Ξ)</option></select></div>
        </div>
        <div class="panel"><h3>RESPONSIBLE PLAY TOOLS</h3>
          <div class="settings-row"><span class="settings-lbl">Daily loss limit<div class="settings-sub">Blocks new bets once today's net loss reaches it</div></span><div style="display:flex;gap:8px"><input class="f-in" id="set-loss" type="number" placeholder="No limit" style="max-width:150px"><button class="btn btn-outline" onclick="Settings.setLoss()">Set</button></div></div>
          <div class="settings-row"><span class="settings-lbl">This session</span><b id="set-sessinfo" style="color:var(--acc)"></b></div>
          <div class="settings-row"><span class="settings-lbl">Session reminder</span><select class="f-in" id="set-sess" onchange="Settings.set('sess',+this.value);Settings.startSession()"><option value="0">Off</option><option value="15">15 minutes</option><option value="30">30 minutes</option><option value="60">1 hour</option></select></div>
        </div>
        <div class="panel"><h3>ACCOUNT &amp; DATA</h3>
          <div class="settings-row"><span class="settings-lbl">Change username</span><div style="display:flex;gap:8px"><input class="f-in" id="set-newname" placeholder="New username" style="max-width:170px"><button class="btn btn-outline" onclick="Auth.rename()">Change</button></div></div>
          <div class="settings-row"><span class="settings-lbl">Reset statistics</span><button class="btn btn-danger" onclick="App.resetStats()">Reset stats</button></div>
          <div class="settings-row admin-only"><span class="settings-lbl">Reset wallet to $1,000 (admin)</span><button class="btn btn-danger" onclick="Wallet.reset()">Reset wallet</button></div>
          <div class="settings-row"><span class="settings-lbl">Import data<div class="settings-sub">Restore a JSON export</div></span><input type="file" accept="application/json" onchange="App.importData(this)" style="max-width:200px;font-size:12px"></div>
          <div class="settings-row"><span class="settings-lbl">Clear favorites &amp; recents</span><button class="btn btn-outline" onclick="Fav.clear()">Clear</button></div>
          <div class="settings-row"><span class="settings-lbl">Reset settings to defaults</span><button class="btn btn-danger" onclick="Settings.reset()">Reset settings</button></div>
          <div class="settings-row"><span class="settings-lbl">Export data</span><button class="btn btn-outline" onclick="App.exportData()">Export JSON</button></div>
          <div class="hint" style="margin-top:10px">Cup Casino · sandbox build 4.0 · all data is stored only in this browser.</div>
        </div>
      </div></div>

    </main>
  </div>
</div>

