<div class="modal-wrap" id="auth-modal" onclick="if(event.target===this)Auth.close()">
  <div class="modal sm"><div class="pad-m">
    <div class="auth-tabs"><div class="auth-tab active" id="tab-login" onclick="Auth.tab('login')">LOG IN</div><div class="auth-tab" id="tab-signup" onclick="Auth.tab('signup')">SIGN UP</div></div>
    <div id="auth-login"><div class="auth-form"><input class="f-in" id="li-user" placeholder="Username"/><input class="f-in" id="li-pass" placeholder="Password" type="password" onkeydown="if(event.key==='Enter')Auth.login()"/><button class="act gold" onclick="Auth.login()">LOG IN</button></div></div>
    <div id="auth-signup" style="display:none"><div class="auth-form"><input class="f-in" id="su-user" placeholder="Username (min 3 chars)"/><input class="f-in" id="su-pass" placeholder="Password (min 3 chars)" type="password" onkeydown="if(event.key==='Enter')Auth.signup()"/><button class="act gold" onclick="Auth.signup()">CREATE ACCOUNT</button></div></div>
    <div class="hint" style="margin-top:10px">Local-only account, stored in this browser. Do not reuse a real password.</div>
