      <div id="w-admin" style="display:none;flex-direction:column;gap:12px">
        <div class="lbl">Add play money</div>
        <div class="chips" id="w-add"></div>
        <div class="lbl">Set exact balance</div>
        <div class="promo-row"><input class="f-in" id="w-set" type="number" placeholder="Amount"/><button class="btn btn-primary" onclick="Wallet.setTo()">Set</button></div>
