<div class="adm-wrap" id="adm-panel" style="display:none">
  <div class="adm-tab" onclick="this.parentNode.classList.toggle('open')">🛠 ADMIN</div>
  <div class="adm-body">
    <div class="adm-h">Balance</div>
    <input class="f-in" id="adm-amt" type="number" placeholder="Amount">
    <div class="row3"><button class="btn btn-primary" onclick="Admin.setBal()">Set</button><button class="btn btn-outline" onclick="Admin.addBal(1)">+ Add</button><button class="btn btn-outline" onclick="Admin.addBal(-1)">− Take</button></div>
    <div class="row3"><button class="btn btn-outline" onclick="Admin.quick(1e3)">+1K</button><button class="btn btn-outline" onclick="Admin.quick(1e6)">+1M</button><button class="btn btn-outline" onclick="Admin.quick(1e9)">+1B</button></div>
    <div class="adm-h">Outcomes</div>
    <label class="toggle"><input type="checkbox" id="adm-reveal" onchange="Admin.opt('reveal',this.checked)"><span class="tk"></span>Show next result</label>
    <button class="btn btn-outline" onclick="Admin.refresh();toast('Next result re-rolled')">🎲 Re-roll next result</button>
    <select class="f-in" id="adm-force" onchange="Admin.opt('force',this.value)"><option value="">Natural outcomes</option><option value="win">Force WIN (where possible)</option><option value="lose">Force LOSE (where possible)</option></select>
    <div class="adm-h">Perks</div>
    <label class="toggle"><input type="checkbox" id="adm-noloss" onchange="Admin.opt('noLoss',this.checked)"><span class="tk"></span>Risk-free (losses refunded)</label>
    <label class="toggle"><input type="checkbox" id="adm-auto" onchange="Admin.opt('auto',this.checked)"><span class="tk"></span>Autopilot cash-out (Aviator/Crash)</label>
    <select class="f-in" id="adm-boost" onchange="Admin.opt('boost',+this.value)"><option value="1">Win profit ×1</option><option value="2">Win profit ×2</option><option value="5">Win profit ×5</option><option value="10">Win profit ×10</option><option value="100">Win profit ×100</option></select>
    <div class="hint" style="font-size:10px">Admin also bypasses the loss limit and lets promo codes be claimed again.</div>
    <div class="adm-h">Tools</div>
    <div class="row3"><button class="btn btn-outline" onclick="Admin.resetPromos()">Reset promos</button><button class="btn btn-outline" onclick="App.resetStats()">Reset stats</button></div>
    <button class="btn btn-danger" onclick="Admin.set(false)">Exit admin mode</button>
  </div>
</div>
<div class="toast" id="toast"></div>

<script>
/* =====================================================================
   CUP CASINO — math engine (pure, no DOM).  Runs in browser and Node.
   Everything that decides an outcome or a payout lives here so it can be
   simulated.  UI code only calls these functions.
   ===================================================================== */
var CM = (function () {
  const CM = {};

  /* ---------- RNG ---------- */
  let nodeCrypto = null;
  if (typeof require !== 'undefined') { try { nodeCrypto = require('crypto'); } catch (e) {} }
  CM.rnd = function () {
    const a = new Uint32Array(2);
    if (typeof crypto !== 'undefined' && crypto.getRandomValues) crypto.getRandomValues(a);
    else if (nodeCrypto) nodeCrypto.randomFillSync(a);
    else { a[0] = Math.random() * 4294967296; a[1] = Math.random() * 4294967296; }
    return (a[0] * 2097152 + (a[1] >>> 11)) / 9007199254740992;
  };
  // fast PRNG for simulations (xorshift128+) — only used by Node tests
  CM.useFastRng = function (seed) {
    let s0 = (seed || 123456789) >>> 0, s1 = 362436069, s2 = 521288629, s3 = 88675123;
    CM.rnd = function () {
      let t = s0 ^ (s0 << 11); s0 = s1; s1 = s2; s2 = s3;
      s3 = (s3 ^ (s3 >>> 19)) ^ (t ^ (t >>> 8));
      const hi = (s3 >>> 0), lo = ((s2 ^ (s1 << 7)) >>> 0);
      return (hi * 2097152 + (lo >>> 11)) / 9007199254740992;
    };
  };
  CM.rint = n => Math.floor(CM.rnd() * n);
  CM.pick = a => a[CM.rint(a.length)];
  CM.shuffle = function (a) { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = CM.rint(i + 1); [a[i], a[j]] = [a[j], a[i]]; } return a; };
  CM.weighted = function (items, weights) {
    let tot = 0; for (const w of weights) tot += w;
    let r = CM.rnd() * tot;
    for (let i = 0; i < items.length; i++) { r -= weights[i]; if (r < 0) return items[i]; }
    return items[items.length - 1];
  };
  const _C = {};
  CM.C = function (n, k) {
    if (k < 0 || k > n) return 0; if (k === 0 || k === n) return 1;
    const key = n + ',' + k; if (_C[key] !== undefined) return _C[key];
    let r = 1; k = Math.min(k, n - k);
    for (let i = 1; i <= k; i++) r = r * (n - k + i) / i;
    return (_C[key] = r);
  };
  CM.EDGE = 0.01;                         // house edge on Cup Originals (1%)

  /* ---------- DIFFICULTY TIERS (7 per game) ----------
     0 easy · 1 normal · 2 difficult · 3 hard · 4 extreme · 5 insane · 6 transcendent
     Generic rule (games without a native table): tier f pays f× but only lands 1 in f times, so RTP is unchanged.
     Transcendent = insane (f = 25) with 100× the multipliers on a 1-in-100 chance on top → f = 2500.
     Easy blends half of every result with a cushion, halving variance at the same RTP. */
  CM.TIER_KEYS = ['easy', 'normal', 'difficult', 'hard', 'extreme', 'insane', 'transcendent'];
  CM.TIER_NAMES = ['Easy', 'Normal', 'Difficult', 'Hard', 'Extreme', 'Insane', 'Transcendent'];
  CM.TIER_F = [0.5, 1, 2, 4, 10, 25, 2500];
  CM.easyPay = (stake, base, rtp) => 0.5 * base + 0.5 * rtp * stake;
  CM.gateF = function (f, base, u) { if (f <= 1) return { pay: base, ok: true, f: 1 }; const ok = u < 1 / f; return { pay: ok ? base * f : 0, ok, f }; };
  // native-table games (plinko, keno, mines, towers): tier 6 = insane table, 100× pay on a 1-in-100 gate
  CM.nat = t => Math.min(t, 5);
  CM.natGate = (tier, base, u) => tier < 6 ? { pay: base, ok: true, f: 1 } : CM.gateF(100, base, u);
  // crash-style games: flight is shot down at once unless it is the 1-in-f flight that is f× longer
  CM.crashTier = function (tier, edge) {
    const f = CM.TIER_F[tier]; if (f <= 1) return CM.crashPoint(edge);
    if (CM.rnd() < 1 / f) return Math.max(1, Math.floor(f * CM.crashPoint(edge) * 100) / 100);
    return 1;
  };

  /* ---------- CRASH / LIMBO ---------- */
  // P(point >= m) = 0.99 / m   →  RTP 99% at any cash-out target
  CM.crashPoint = function (edge) {
    const r = CM.rnd();
    const x = (1 - (edge == null ? CM.EDGE : edge)) / (1 - r);
    return Math.max(1, Math.floor(x * 100) / 100);
  };

  /* ---------- DICE ---------- */
  CM.diceRoll = () => Math.floor(CM.rnd() * 10000) / 100;      // 0.00 – 99.99
  CM.diceChance = (target, over) => over ? (9999 - Math.round(target * 100)) / 10000 : Math.round(target * 100) / 10000;
  CM.diceMult = (target, over) => { const c = CM.diceChance(target, over); return c > 0 ? (1 - CM.EDGE) / c : 0; };
  CM.diceWin = (roll, target, over) => over ? roll > target : roll < target;

  /* ---------- MINES ---------- */
  CM.minesMult = function (mines, picks) {            // 25-tile board
    if (picks <= 0) return 1;
    return (1 - CM.EDGE) * CM.C(25, picks) / CM.C(25 - mines, picks);
  };
  CM.MINES_BY_TIER = [1, 3, 6, 10, 17, 24, 24];
  CM.minesLayout = function (mines) {
    const idx = CM.shuffle(Array.from({ length: 25 }, (_, i) => i)).slice(0, mines);
    const set = new Set(idx); return Array.from({ length: 25 }, (_, i) => set.has(i));
  };

  /* ---------- PLINKO ---------- */
  const PL_FLOOR = { easy: 0.8, normal: 0.5, difficult: 0.3, hard: 0.2, extreme: 0.1, insane: 0 };
  const PL_ALIAS = { low: 'normal', med: 'difficult', high: 'hard' };
  const plMax = r => (1 - CM.EDGE) * Math.pow(2, r - 1);      // all RTP on the two edge slots
  const PL_EDGE = {                                   // target maximum (edge-slot) multiplier
    easy:      { 8: 2.2, 9: 2.4, 10: 2.6, 11: 2.8, 12: 3, 13: 3.2, 14: 3.4, 15: 3.6, 16: 3.8 },
    normal:    { 8: 5.6, 9: 5.6, 10: 8.9, 11: 8.4, 12: 10, 13: 8.1, 14: 7.1, 15: 15, 16: 16 },
    difficult: { 8: 13, 9: 18, 10: 22, 11: 24, 12: 33, 13: 43, 14: 58, 15: 88, 16: 110 },
    hard:      { 8: 29, 9: 43, 10: 76, 11: 120, 12: 170, 13: 260, 14: 420, 15: 620, 16: 1000 },
    extreme:   {}, insane: {}
  };
  for (let r = 8; r <= 16; r++) { PL_EDGE.extreme[r] = Math.round(plMax(r) * Math.min(0.5, PL_EDGE.hard[r] / plMax(r) * 3.5)); PL_EDGE.insane[r] = Math.round(plMax(r) * 0.7); }
  const _plc = {};
  CM.plinkoProbs = rows => Array.from({ length: rows + 1 }, (_, k) => CM.C(rows, k) / Math.pow(2, rows));
  CM.plinkoTable = function (rows, risk) {
    risk = PL_ALIAS[risk] || risk; const key = rows + risk; if (_plc[key]) return _plc[key];
    const p = CM.plinkoProbs(rows), floor = PL_FLOOR[risk], target = PL_EDGE[risk][rows];
    const d = k => Math.abs(k - rows / 2) / (rows / 2);
    const build = beta => {
      const g = p.map((_, k) => Math.exp(beta * d(k)) - 1);
      let s = 0; for (let k = 0; k <= rows; k++) s += p[k] * g[k];
      const c = ((1 - CM.EDGE) - floor) / s;
      return p.map((_, k) => floor + c * g[k]);
    };
    let lo = 0.01, hi = 60;
    for (let i = 0; i < 120; i++) { const mid = (lo + hi) / 2; const t = build(mid); if (t[0] < target) lo = mid; else hi = mid; }
    const raw = build((lo + hi) / 2);
    const out = raw.map(v => v >= 100 ? Math.round(v) : v >= 10 ? Math.round(v * 10) / 10 : Math.round(v * 100) / 100);
    return (_plc[key] = out);
  };
  CM.plinkoRtp = (rows, risk) => { const p = CM.plinkoProbs(rows), t = CM.plinkoTable(rows, risk); return p.reduce((a, x, k) => a + x * t[k], 0); };
  CM.plinkoPath = function (rows) { const path = []; let r = 0; for (let i = 0; i < rows; i++) { const b = CM.rnd() < 0.5 ? 0 : 1; path.push(b); r += b; } return { path, slot: r }; };

  /* ---------- KENO (40 numbers, 10 drawn) ---------- */
  CM.kenoProb = (n, k) => CM.C(n, k) * CM.C(40 - n, 10 - k) / CM.C(40, 10);
  const KENO_ALIAS = { low: 'easy', classic: 'normal', med: 'difficult', high: 'hard' };
  const KENO_KMIN = {
    easy:      [0, 1, 1, 2, 2, 2, 3, 3, 3, 4, 4],
    normal:    [0, 1, 2, 2, 2, 3, 3, 3, 4, 4, 4],
    difficult: [0, 1, 2, 3, 3, 4, 4, 5, 5, 6, 6],
    hard:      [0, 1, 2, 3, 4, 4, 5, 5, 6, 6, 7],
    extreme:   [0, 1, 2, 3, 4, 5, 5, 6, 6, 7, 7],
    insane:    [0, 1, 2, 3, 4, 5, 6, 6, 7, 8, 8]
  };
  const KENO_ALPHA = { easy: 0.55, normal: 0.78, difficult: 0.88, hard: 0.97, extreme: 1.1, insane: 1.35 };   // m_k ∝ p_k^-alpha
  const KENO_CAP = { easy: 500, normal: 1000, difficult: 1000, hard: 10000, extreme: 100000, insane: 10000000 };
  const _kc = {};
  CM.kenoTable = function (n, risk) {
    risk = KENO_ALIAS[risk] || risk; const key = n + risk; if (_kc[key]) return _kc[key];
    const kmin = Math.min(KENO_KMIN[risk][n], n), al = KENO_ALPHA[risk], cap = KENO_CAP[risk];
    const ks = []; for (let k = kmin; k <= n; k++) ks.push(k);
    const p = ks.map(k => CM.kenoProb(n, k)), raw = p.map(x => Math.pow(x, -al));
    const rtp = s => ks.reduce((a, k, i) => a + p[i] * Math.min(cap, s * raw[i]), 0);
    let lo = 0, hi = 1e9; const target = 1 - CM.EDGE;
    for (let i = 0; i < 300; i++) { const mid = (lo + hi) / 2; if (rtp(mid) < target) lo = mid; else hi = mid; }
    const s = (lo + hi) / 2;
    const t = new Array(n + 1).fill(0);
    ks.forEach((k, i) => { const m = Math.min(cap, s * raw[i]); t[k] = m >= 100 ? Math.round(m) : m >= 10 ? Math.round(m * 10) / 10 : Math.round(m * 100) / 100; });
    return (_kc[key] = t);
  };
  CM.kenoRtp = (n, risk) => { const t = CM.kenoTable(n, risk); let r = 0; for (let k = 0; k <= n; k++) r += CM.kenoProb(n, k) * t[k]; return r; };
  CM.kenoDraw = () => CM.shuffle(Array.from({ length: 40 }, (_, i) => i + 1)).slice(0, 10);

  /* ---------- WHEEL ---------- */
  CM.WHEEL_F = [1, 1, 1, 1, 3, 10, 1000];              // hard table + 1-in-f gate paying f× for extreme/insane/transcendent
  const WHEEL_BASE = {
    easy: [1.5, 1.3, 1.2, 1.2, 1.1, 1, 1, 0.9, 0.4, 0.3],
    normal: [1.5, 1.2, 1.2, 1.2, 1.2, 1.2, 1.2, 1.2, 0, 0],
    difficult: [3.4, 2, 1.5, 1.5, 1.5, 0, 0, 0, 0, 0]
  };
  CM.wheelSegments = function (risk, n) {            // n in 10,20,30,40,50
    risk = { low: 'normal', med: 'difficult', high: 'hard', extreme: 'hard', insane: 'hard', transcendent: 'hard' }[risk] || risk;
    const base = WHEEL_BASE[risk] || null;
    let segs = [];
    if (base) { const k = n / 10; for (const v of base) for (let i = 0; i < k; i++) segs.push(v); }
    else { segs = new Array(n).fill(0); segs[0] = Math.round((1 - CM.EDGE) * n * 100) / 100; }
    // interleave deterministically so colours/values alternate nicely
    const out = new Array(n); const step = 7 % n === 0 ? 3 : 7;
    let pos = 0; const used = new Set();
    for (let i = 0; i < n; i++) { while (used.has(pos % n)) pos++; out[pos % n] = segs[i]; used.add(pos % n); pos += step; }
    return out;
  };
  CM.wheelRtp = segs => segs.reduce((a, b) => a + b, 0) / segs.length;

  /* ---------- HILO (infinite deck, A low) ---------- */
  CM.hiloProb = (rank, dir) => dir === 'hi' ? (14 - rank) / 13 : rank / 13;
  CM.hiloMult = (rank, dir) => (1 - CM.EDGE) / CM.hiloProb(rank, dir);

  /* ---------- TOWERS ---------- */
  CM.TOWER_MODES = { easy: { cols: 5, bombs: 1 }, normal: { cols: 4, bombs: 1 }, difficult: { cols: 3, bombs: 1 }, hard: { cols: 2, bombs: 1 }, extreme: { cols: 3, bombs: 2 }, insane: { cols: 4, bombs: 3 }, medium: { cols: 3, bombs: 1 }, expert: { cols: 3, bombs: 2 }, master: { cols: 4, bombs: 3 } };
  CM.TOWER_ROWS = 9;
  CM.towersMult = (mode, level) => { const m = CM.TOWER_MODES[mode]; return level <= 0 ? 1 : (1 - CM.EDGE) / Math.pow((m.cols - m.bombs) / m.cols, level); };

  /* ---------- FLIP ---------- */
  CM.flipMult = streak => streak <= 0 ? 1 : (1 - CM.EDGE) * Math.pow(2, streak);

  /* ---------- DIAMONDS ---------- */
  CM.DIAMOND_PAY = { 'Five of a kind': 50, 'Four of a kind': 5, 'Full house': 4, 'Three of a kind': 3, 'Two pair': 2, 'Pair': 0.1, 'No match': 0 };
  CM.diamondsEval = function (g) {
    const c = {}; g.forEach(x => c[x] = (c[x] || 0) + 1);
    const v = Object.values(c).sort((a, b) => b - a);
    if (v[0] === 5) return 'Five of a kind'; if (v[0] === 4) return 'Four of a kind';
    if (v[0] === 3 && v[1] === 2) return 'Full house'; if (v[0] === 3) return 'Three of a kind';
    if (v[0] === 2 && v[1] === 2) return 'Two pair'; if (v[0] === 2) return 'Pair'; return 'No match';
  };
  CM.diamondsRtp = function () {
    let tot = 0; const N = 7;
    for (let a = 0; a < N; a++) for (let b = 0; b < N; b++) for (let c = 0; c < N; c++) for (let d = 0; d < N; d++) for (let e = 0; e < N; e++)
      tot += CM.DIAMOND_PAY[CM.diamondsEval([a, b, c, d, e])];
    return tot / Math.pow(N, 5);
  };

  /* ---------- HOT & COLD (1-20) ---------- */
  CM.HC = { hot: 1.9, cold: 1.9, exact: 19 };           // 50% × 1.9 = 95%, 5% × 19 = 95%

  /* ---------- SCRATCH ---------- */
  CM.SCRATCH_TIERS = [{ m: 1, w: 12 }, { m: 2, w: 7 }, { m: 3, w: 4 }, { m: 5, w: 3 }, { m: 10, w: 1.5 }, { m: 25, w: 0.5 }, { m: 100, w: 0.06 }, { m: 1000, w: 0.004 }];
  CM.scratchTable = function (rtp) {
    rtp = rtp || 0.95; const T = CM.SCRATCH_TIERS; const raw = T.reduce((a, t) => a + t.w * t.m, 0);
    const f = rtp / raw; return T.map(t => ({ m: t.m, p: t.w * f }));
  };
  CM.scratchDraw = function () {
    const tb = CM.scratchTable(); let r = CM.rnd();
    for (const t of tb) { r -= t.p; if (r < 0) return t.m; } return 0;
  };

  /* ================= CARDS ================= */
  CM.SUITS = ['♠', '♥', '♦', '♣'];
  CM.RANKSTR = { 11: 'J', 12: 'Q', 13: 'K', 14: 'A' };
  CM.rankStr = r => CM.RANKSTR[r] || String(r);
  CM.isRed = c => c.s === 1 || c.s === 2;
  CM.newDeck = function (decks) { const d = []; for (let k = 0; k < (decks || 1); k++) for (let s = 0; s < 4; s++) for (let r = 2; r <= 14; r++) d.push({ r, s }); return d; };
  CM.Shoe = function (decks, cutAt) {
    const sh = { decks, cards: [], cutAt: cutAt == null ? 0.25 : cutAt };
    sh.shuffle = function () { sh.cards = CM.shuffle(CM.newDeck(decks)); };
    sh.draw = function () { if (sh.cards.length < 20) sh.shuffle(); return sh.cards.pop(); };
    sh.needsShuffle = () => sh.cards.length < decks * 52 * sh.cutAt;
    sh.shuffle(); return sh;
  };
  CM.drawFresh = () => ({ r: 2 + CM.rint(13), s: CM.rint(4) });

  /* ---------- 5-card & 7-card poker evaluation ---------- */
  // returns [category, ...tiebreakers]  category: 8 SF, 7 quads, 6 FH, 5 flush, 4 straight, 3 trips, 2 two pair, 1 pair, 0 high
  CM.HAND_NAMES = ['High Card', 'Pair', 'Two Pair', 'Three of a Kind', 'Straight', 'Flush', 'Full House', 'Four of a Kind', 'Straight Flush'];
  CM.eval5 = function (cs) {
    const rs = cs.map(c => c.r).sort((a, b) => b - a);
    const flush = cs.every(c => c.s === cs[0].s);
    let straightHigh = 0; const u = Array.from(new Set(rs));
    if (u.length === 5) { if (rs[0] - rs[4] === 4) straightHigh = rs[0]; else if (rs[0] === 14 && rs[1] === 5 && rs[4] === 2) straightHigh = 5; }
    const cnt = {}; rs.forEach(r => cnt[r] = (cnt[r] || 0) + 1);
    const groups = Object.keys(cnt).map(Number).sort((a, b) => cnt[b] - cnt[a] || b - a);
    const gc = groups.map(g => cnt[g]);
    if (straightHigh && flush) return [8, straightHigh];
    if (gc[0] === 4) return [7, groups[0], groups[1]];
    if (gc[0] === 3 && gc[1] === 2) return [6, groups[0], groups[1]];
    if (flush) return [5, ...rs];
    if (straightHigh) return [4, straightHigh];
    if (gc[0] === 3) return [3, groups[0], groups[1], groups[2]];
    if (gc[0] === 2 && gc[1] === 2) return [2, groups[0], groups[1], groups[2]];
    if (gc[0] === 2) return [1, groups[0], groups[1], groups[2], groups[3]];
    return [0, ...rs];
  };
  CM.cmpHand = function (a, b) { for (let i = 0; i < Math.max(a.length, b.length); i++) { const d = (a[i] || 0) - (b[i] || 0); if (d) return d > 0 ? 1 : -1; } return 0; };
  CM.best7 = function (cards) {
    let best = null; const n = cards.length;
    for (let i = 0; i < n - 4; i++) for (let j = i + 1; j < n - 3; j++) for (let k = j + 1; k < n - 2; k++) for (let l = k + 1; l < n - 1; l++) for (let m = l + 1; m < n; m++) {
      const h = CM.eval5([cards[i], cards[j], cards[k], cards[l], cards[m]]);
      if (!best || CM.cmpHand(h, best) > 0) best = h;
    }
    return best;
  };

  /* ---------- 3-card poker ---------- */
  // [category, ...tiebreak]  category: 5 SF, 4 trips, 3 straight, 2 flush, 1 pair, 0 high
  CM.TC_NAMES = ['High Card', 'Pair', 'Flush', 'Straight', 'Three of a Kind', 'Straight Flush'];
  CM.eval3 = function (cs) {
    const rs = cs.map(c => c.r).sort((a, b) => b - a);
    const flush = cs.every(c => c.s === cs[0].s);
    let st = 0;
    if (new Set(rs).size === 3) { if (rs[0] - rs[2] === 2) st = rs[0]; else if (rs[0] === 14 && rs[1] === 3 && rs[2] === 2) st = 3; }
    if (st && flush) return [5, st];
    if (rs[0] === rs[2]) return [4, rs[0]];
    if (st) return [3, st];
    if (flush) return [2, ...rs];
    if (rs[0] === rs[1]) return [1, rs[0], rs[2]];
    if (rs[1] === rs[2]) return [1, rs[1], rs[0]];
    return [0, ...rs];
  };
  CM.TC_PAIRPLUS = { 5: 40, 4: 30, 3: 6, 2: 4, 1: 1, 0: 0 };
  CM.TC_ANTEBONUS = { 5: 5, 4: 4, 3: 1 };
  // dealer qualifies with Queen-high or better
  CM.tcQualifies = h => h[0] > 0 || h[1] >= 12;

  /* ---------- Video poker (Jacks or Better 8/5) ---------- */
  CM.VP_PAY = { 'Royal Flush': 800, 'Straight Flush': 50, 'Four of a Kind': 25, 'Full House': 8, 'Flush': 5, 'Straight': 4, 'Three of a Kind': 3, 'Two Pair': 2, 'Jacks or Better': 1 };
  CM.vpEval = function (cs) {
    const h = CM.eval5(cs);
    if (h[0] === 8) return h[1] === 14 ? 'Royal Flush' : 'Straight Flush';
    if (h[0] === 7) return 'Four of a Kind'; if (h[0] === 6) return 'Full House'; if (h[0] === 5) return 'Flush'; if (h[0] === 4) return 'Straight';
    if (h[0] === 3) return 'Three of a Kind'; if (h[0] === 2) return 'Two Pair';
    if (h[0] === 1 && h[1] >= 11) return 'Jacks or Better'; return null;
  };

  /* ---------- Blackjack ---------- */
  CM.bjVal = r => r >= 11 && r <= 13 ? 10 : r === 14 ? 11 : r;
  CM.bjTotal = function (cs) {
