    cash: { id: '🐟', w: 6.5, wFree: 12, vals: [2, 3, 4, 5, 10, 15, 20, 25, 50, 100], vw: [34, 24, 16, 10, 7, 4, 3, 1.5, 0.4, 0.1] }, scale: 9.898 };

  S.rtpSim = function (key, n) {
    const cfg = S.GAMES[key]; let ret = 0, hit = 0, big = 0, fsTrig = 0;
    for (let i = 0; i < n; i++) {
      const r = cfg.engine === 'tumble' ? S.tumbleRound(cfg) : S.linesRound(cfg);
      ret += r.total; if (r.total > 0) hit++; if (r.total >= 100) big++;
      if (r.free && r.free.length) fsTrig++;
    }
    return { rtp: ret / n, hit: hit / n, big100: big / n, fsFreq: fsTrig / n };
  };

  if (typeof module !== 'undefined' && module.exports) module.exports = S;
  else window.CMS = S;
})();

/* =====================================================================
   CORE — settings, wallet, accounts, navigation, game registry & modal,
   shared UI helpers (bet box, auto-bet, cards).  No game logic here.
   ===================================================================== */
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => Array.from(r.querySelectorAll(s));
const rd = x => Math.round(x * 100) / 100;
const sleep = ms => new Promise(r => setTimeout(r, ms));
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
function safe(fn) { try { return fn(); } catch (e) { return null; } }
const store = {
  get(k, d) { try { const v = localStorage.getItem(k); return v == null ? d : JSON.parse(v); } catch (e) { return d; } },
  set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} },
  del(k) { try { localStorage.removeItem(k); } catch (e) {} }
};

/* ---------- number formatting ---------- */
function fmt(n) {
  const s = Settings.v.cur, a = Math.abs(n), sign = n < 0 ? '-' : '';
  for (const [u, l] of [[1e15, 'Q'], [1e12, 'T'], [1e9, 'B'], [1e6, 'M']]) if (a / u >= 0.999995) return sign + s + (a / u).toFixed(2) + l;
  return sign + s + a.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
const fx = (m, d = 2) => (m >= 1000 ? m.toFixed(0) : m.toFixed(d)) + '×';

/* ---------- settings ---------- */
const THEMES = { orange: ['#ff7a1a', '#ff5a00'], blue: ['#2f8bff', '#1a63d6'], white: ['#eef3ff', '#b9c8e8'], violet: ['#a66bff', '#7c3aed'], emerald: ['#2ee59d', '#12b981'], crimson: ['#ff4d6d', '#e11d48'], gold: ['#ffc233', '#f59e0b'] };
const Settings = {
  DEF: { theme: 'orange', noAnim: false, hideBal: false, sound: true, vol: 60, quick: false, confirm: false, thresh: 10000, cur: '$', loss: 0, sess: 0, compact: false, live: true, confetti: true, keys: true, defBet: 0, autoWin: 0, autoLoss: 0 },
  v: null,
  set(k, val) { this.v[k] = val; store.set('cc_cfg', this.v); this.apply(); App.updateBal(); },
  apply() {
    const v = this.v, t = THEMES[v.theme] || THEMES.orange, r = document.documentElement.style;
    r.setProperty('--acc', t[0]); r.setProperty('--acc2', t[1]);
    document.body.classList.toggle('no-anim', !!v.noAnim); document.body.classList.toggle('compact', !!v.compact); document.body.classList.toggle('no-live', !v.live);
    const b = $('#bal-disp'); if (b) b.style.filter = v.hideBal ? 'blur(6px)' : 'none';
  },
  setTheme(k) { this.set('theme', k); this.syncUI(); },
  setLoss() { const n = parseFloat($('#set-loss').value); this.set('loss', n > 0 ? n : 0); toast(n > 0 ? 'Daily loss limit: ' + fmt(n) : 'Loss limit removed'); },
  syncUI() {
    const v = this.v;
    $('#theme-dots').innerHTML = Object.keys(THEMES).map(k => `<div class="theme-dot ${k === v.theme ? 'on' : ''}" style="background:${THEMES[k][0]}" onclick="Settings.setTheme('${k}')" title="${k}"></div>`).join('');
    $('#set-noanim').checked = v.noAnim; $('#set-hidebal').checked = v.hideBal; $('#set-sound').checked = v.sound; $('#set-vol').value = v.vol;
    $('#set-quick').checked = v.quick; $('#set-confirm').checked = v.confirm; $('#set-thresh').value = v.thresh; $('#set-cur').value = v.cur;
    $('#set-loss').value = v.loss || ''; $('#set-sess').value = v.sess;
    $('#set-compact').checked = v.compact; $('#set-live').checked = v.live; $('#set-confetti').checked = v.confetti; $('#set-keys').checked = v.keys; $('#set-defbet').value = v.defBet || ''; $('#set-autowin').value = v.autoWin || ''; $('#set-autoloss').value = v.autoLoss || '';
  },
  reset() { if (!confirm('Reset all settings to defaults?')) return; this.v = Object.assign({}, this.DEF); store.set('cc_cfg', this.v); this.apply(); this.syncUI(); App.updateBal(); toast('Settings reset'); },
  num(k, id, min = 0) { const n = parseFloat($('#' + id).value); this.set(k, n > min ? n : 0); toast(n > min ? 'Saved' : 'Cleared'); },
  sessInfo() { const e = $('#set-sessinfo'); if (!e) return; const mins = Math.max(0, Math.round((Date.now() - this._sessStart) / 60000)), bets = App.S.bets - (this._bets0 || 0); e.textContent = mins + ' min · ' + Math.max(0, bets) + ' bets this session'; },
  _sessT: null, _sessStart: Date.now(), _bets0: 0,
  startSession() { clearInterval(this._sessT); this._sessStart = Date.now(); this._bets0 = App.S.bets; if (this.v.sess > 0) this._sessT = setInterval(() => toast('⏱ You have been playing for ' + Math.round((Date.now() - this._sessStart) / 60000) + ' min — time for a break?'), this.v.sess * 60000); }
};

Settings.v = Object.assign({}, Settings.DEF, store.get('cc_cfg', {}));

/* ---------- sound ---------- */
let _ac = null;
function snd(kind) {
  if (!Settings.v.sound) return;
  try {
    _ac = _ac || new (window.AudioContext || window.webkitAudioContext)();
    const vol = (Settings.v.vol / 100) * 0.15; const t0 = _ac.currentTime;
    const seq = { click: [[520, .04]], win: [[660, .09], [880, .09], [1100, .14]], big: [[660, .08], [880, .08], [1100, .08], [1320, .08], [1760, .25]], lose: [[300, .12], [200, .18]], tick: [[900, .02]], boom: [[120, .25]] }[kind] || [];
    let t = t0; seq.forEach(([f, d]) => { const o = _ac.createOscillator(), g = _ac.createGain(); o.type = kind === 'boom' ? 'sawtooth' : 'triangle'; o.frequency.value = f; g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + d); o.connect(g); g.connect(_ac.destination); o.start(t); o.stop(t + d); t += d * .9; });
  } catch (e) {}
}

/* ---------- toast ---------- */
function toast(msg, lose) { const t = $('#toast'); t.textContent = msg; t.className = 'toast' + (lose ? ' lose' : ''); void t.offsetWidth; t.className = 'toast' + (lose ? ' lose' : '') + ' show'; }

/* ---------- app state / wallet ---------- */
const STAKES = { poor: 1000, middle: 10000, whale: 100000, millionaire: 1000000, billionaire: 1000000000 };
const STAKE_NAMES = { poor: 'Casual', middle: 'High Roller', whale: 'Whale', millionaire: 'Millionaire', billionaire: 'Billionaire' };
const blank = () => ({ balance: 1000, wagered: 0, won: 0, bets: 0, wins: 0, biggest: 0, history: [], byGame: {}, bestMult: 0, promos: {}, daily: { d: '', net: 0 }, since: Date.now() });
const App = {
  S: blank(), user: null, accounts: {}, stake: 'poor',
  defBet() { const f = Settings.v.defBet; if (f > 0) return Math.max(1, Math.min(f, Math.floor(this.S.balance))); const d = STAKES[this.stake] / 100; return Math.min(d, Math.max(1, Math.floor(this.S.balance))) ; },
  load() {
    this.accounts = store.get('cc_acc', {});
    const sess = store.get('cc_sess', null);
    if (sess && this.accounts[sess.u]) { this.user = sess.u; this.S = Object.assign(blank(), this.accounts[sess.u]); }
    else this.S = Object.assign(blank(), store.get('cc_guest', {}));
    this.stake = store.get('cc_stake', 'poor');
  },
  save() { if (this.user) { this.accounts[this.user] = this.S; store.set('cc_acc', this.accounts); } else store.set('cc_guest', this.S); },
  today() { return new Date().toISOString().slice(0, 10); },
  dailyNet() { const d = this.S.daily; if (d.d !== this.today()) { d.d = this.today(); d.net = 0; } return d.net; },
  updateBal() {
    const S = this.S, pnl = S.won - S.wagered;
    $('#bal-disp').textContent = fmt(S.balance); $('#m-bal').textContent = fmt(S.balance);
    $('#tot-wagered').textContent = fmt(S.wagered); $('#tot-won').textContent = fmt(S.won);
    const e = $('#net-pnl'); e.textContent = fmt(pnl); e.className = 'hstat-val' + (pnl < 0 ? ' red' : '');
    if (this.user) $('#sb-bal').textContent = fmt(S.balance);
    const w = $('#w-bal'); if (w) w.textContent = fmt(S.balance);
    this.save();
  },
  // reserve a stake. returns true if allowed.
  take(amt) {
    amt = rd(amt);
    if (!(amt > 0)) { toast('Enter a bet amount', true); return false; }
    if (amt > this.S.balance + 1e-9) { toast('Not enough balance', true); return false; }
    const lim = Settings.v.loss; if (lim > 0 && !Admin.on && -this.dailyNet() >= lim) { toast('Daily loss limit reached', true); return false; }
    if (Settings.v.confirm && amt >= Settings.v.thresh && !confirm('Place a bet of ' + fmt(amt) + '?')) return false;
    this.S.balance = rd(this.S.balance - amt); this.S.wagered = rd(this.S.wagered + amt);
    this.dailyNet(); this.updateBal(); snd('click'); return true;
  },
  // settle a round. stake = total staked in the round, payout = total returned (0 on loss)
  pay(game, stake, payout) {
    stake = rd(stake); payout = rd(payout); const S = this.S;
    if (Admin.on) { if (Admin.noLoss && payout < stake) payout = stake; if (Admin.boost > 1 && payout > stake) payout = rd(stake + (payout - stake) * Admin.boost); }
    S.balance = rd(S.balance + payout); S.won = rd(S.won + payout); S.bets++;
    if (payout > stake + 1e-9) { S.wins++; const prof = payout - stake; if (prof > S.biggest) S.biggest = prof; if (stake > 0 && payout / stake > (S.bestMult || 0)) S.bestMult = payout / stake; }
    S.byGame = S.byGame || {}; const bg = S.byGame[game] || (S.byGame[game] = { n: 0, w: 0, r: 0 }); bg.n++; bg.w = rd(bg.w + stake); bg.r = rd(bg.r + payout);
    this.dailyNet(); S.daily.net = rd(S.daily.net + payout - stake);
    S.history.push({ g: game, s: stake, p: payout, t: new Date().toLocaleTimeString() }); if (S.history.length > 300) S.history.shift();
    this.last = { s: stake, p: payout }; Rewards.track(game, stake, payout); this.updateBal(); Live.mine(game, stake, payout); if (payout >= stake * 20 && Settings.v.confetti && !Settings.v.noAnim) Fx.confetti();
    snd(payout > stake * 10 ? 'big' : payout > stake + 1e-9 ? 'win' : payout < stake ? 'lose' : 'click');
  },
  setStake(k) { if (!Admin.need()) return; this.stake = k; store.set('cc_stake', k); $$('.stake-btn').forEach(b => b.classList.toggle('active', b.dataset.s === k)); if (this.S.balance < STAKES[k]) { this.S.balance = STAKES[k]; toast(STAKE_NAMES[k] + ' bankroll: wallet topped up to ' + fmt(STAKES[k])); } else toast(STAKE_NAMES[k] + ' stakes — default bet ' + fmt(STAKES[k] / 100)); this.updateBal(); },
  resetStats() { if (!confirm('Reset all statistics? Balance stays.')) return; Object.assign(this.S, { wagered: 0, won: 0, bets: 0, wins: 0, biggest: 0, history: [], byGame: {}, bestMult: 0, rbW: 0 }); this.updateBal(); this.renderProfile(); toast('Stats reset'); },
  importData(inp) { const f = inp.files && inp.files[0]; if (!f) return; const r = new FileReader(); r.onload = () => { try { const d = JSON.parse(r.result); if (typeof d.balance !== 'number') throw 0; if (!confirm('Replace the current account data with this file?')) return; delete d.user; delete d.pw; Object.assign(this.S, blank(), d); this.updateBal(); this.renderProfile(); toast('Data imported'); } catch (e) { toast('Not a valid Cup Casino export', true); } inp.value = ''; }; r.readAsText(f); },
  exportData() { const b = new Blob([JSON.stringify({ user: this.user, ...this.S }, null, 2)], { type: 'application/json' }); const a = document.createElement('a'); a.href = URL.createObjectURL(b); a.download = 'cup_casino_data.json'; a.click(); },
  renderProfile() {
    const S = this.S; $('#prof-out').style.display = this.user ? 'none' : ''; $('#prof-in').style.display = this.user ? '' : 'none'; if (!this.user) return;
    const pnl = S.won - S.wagered; $('#prof-av').textContent = this.user.slice(0, 2).toUpperCase(); $('#prof-name').textContent = this.user;
    $('#prof-since').textContent = 'Member since ' + new Date(S.since).toLocaleDateString();
    const lvl = Math.floor(S.wagered / 5000) + 1, prog = (S.wagered % 5000) / 5000;
    $('#prof-lvl').textContent = lvl; $('#vip-fill').style.width = (prog * 100) + '%'; $('#vip-txt').textContent = fmt(5000 - (S.wagered % 5000)) + ' wagered to next level';
    $('#ps-wagered').textContent = fmt(S.wagered); $('#ps-won').textContent = fmt(S.won); const pe = $('#ps-pnl'); pe.textContent = fmt(pnl); pe.className = 'stat-val' + (pnl < 0 ? ' red' : '');
    $('#ps-big').textContent = fmt(S.biggest); $('#ps-bets').textContent = S.bets; $('#ps-wr').textContent = S.bets ? Math.round(S.wins / S.bets * 100) + '%' : '0%';
    Prof.extra();
    const hl = $('#hist-list');
    hl.innerHTML = S.history.length ? S.history.slice(-25).reverse().map(h => { const net = h.p - h.s; return `<div class="hist-row"><div><div class="hist-game">${esc(h.g)}</div><div class="hist-time">${h.t} · stake ${fmt(h.s)}</div></div><div class="hist-amt ${net >= 0 ? 'win' : 'lose'}">${net >= 0 ? '+' : '-'}${fmt(Math.abs(net))}</div></div>`; }).join('') : '<div class="hint">No bets yet</div>';
  }
};


/* ---------- rewards: daily missions, rakeback, weekly race ---------- */
const Rewards = {
  rng(seed) { let a = seed >>> 0; return () => { a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; },
  hash(str) { let h = 2166136261; for (const c of str) h = Math.imul(h ^ c.charCodeAt(0), 16777619); return h >>> 0; },
  TPL: [
    { id: 'bets', ico: '🎲', t: n => `Place ${n} bets`, tg: [15, 30, 60], rw: [600, 1500, 3500], v: m => m.bets },
    { id: 'wins', ico: '🏅', t: n => `Win ${n} rounds`, tg: [5, 12, 25], rw: [700, 1800, 4000], v: m => m.wins },
    { id: 'wager', ico: '💰', t: n => `Wager ${fk(n)} in total`, tg: [2000, 8000, 30000], rw: [800, 2200, 5500], v: m => m.wager },
    { id: 'games', ico: '🧭', t: n => `Play ${n} different games`, tg: [3, 5, 8], rw: [700, 1600, 3600], v: m => Object.keys(m.games).length },
    { id: 'mult', ico: '🚀', t: n => `Hit a ${n}× payout`, tg: [3, 8, 20], rw: [800, 2000, 5000], v: m => m.best },
    { id: 'slots', ico: '🎰', t: n => `Spin the slots ${n} times`, tg: [10, 25, 50], rw: [600, 1500, 3500], v: m => m.slots }
  ],
  mis() { const S = App.S, d = App.today(); if (!S.mis || S.mis.d !== d) S.mis = { d, bets: 0, wins: 0, wager: 0, games: {}, best: 0, slots: 0, claimed: {} }; return S.mis; },
  today() { const r = this.rng(this.hash('missions' + App.today() + (App.user || 'guest'))), pool = this.TPL.slice(), out = []; for (let i = 0; i < 3; i++) { const t = pool.splice(Math.floor(r() * pool.length), 1)[0], lv = Math.floor(r() * 3); out.push({ ...t, n: t.tg[lv], reward: t.rw[lv], lv }); } return out; },
  week() { return Math.floor((Date.now() - 4 * 86400000) / 604800000); }, // weeks start Monday (epoch was a Thursday)
  wk() { const S = App.S, k = this.week(); if (!S.wk || S.wk.k !== k) { if (S.wk && S.wk.v > 0) S.prevWk = { k: S.wk.k, v: S.wk.v, claimed: false }; S.wk = { k, v: 0 }; } return S.wk; },
  PRIZES: [50000, 25000, 10000, 5000, 5000, 2500, 2500, 2500, 2500, 2500],
  track(game, stake, payout) {
    const m = this.mis(); m.bets++; m.wager = rd(m.wager + stake); if (payout > stake + 1e-9) { m.wins++; if (stake > 0) m.best = Math.max(m.best, payout / stake); } m.games[game] = 1; if (/^Slots/.test(game)) m.slots++;
    const w = this.wk(); w.v = rd(w.v + stake);
  },
  claim(i) { const m = this.mis(), M = this.today()[i]; if (!M || m.claimed[M.id] || M.v(m) < M.n) return; m.claimed[M.id] = 1; App.S.balance = rd(App.S.balance + M.reward); App.updateBal(); snd('win'); toast('Mission complete +' + fmt(M.reward)); this.render(); },
  rate() { const lvl = Math.floor(App.S.wagered / 5000) + 1; return Math.min(0.03, 0.005 + 0.001 * (lvl - 1)); },
  rake() { const S = App.S; return rd(Math.max(0, S.wagered - (S.rbW || 0)) * this.rate()); },
  claimRake() { const r = this.rake(); if (r < 1) return toast('Nothing to claim yet — keep playing', true); App.S.rbW = App.S.wagered; App.S.balance = rd(App.S.balance + r); App.updateBal(); snd('win'); toast('Rakeback +' + fmt(r)); this.render(); },
  BOTS: ['luckyfox', 'nova88', 'BigMike', 'aceofspades', 'zeta_x', 'chipmunk', 'ReelDeal', 'hodlr', 'jade.k', 'StakeSam', 'milo7', 'queenbee', 'ghost404', 'dr_odds', 'rocketRay', 'sigma'],
  board(k0, f0, mine) {
    const k = k0 == null ? this.week() : k0, r = this.rng(this.hash('race' + k)), frac = f0 != null ? f0 : Math.min(1, Math.max(0.02, ((Date.now() - 4 * 86400000) % 604800000) / 604800000));
    const rows = this.BOTS.map(n => { const base = 20000 + r() * 900000, grow = 0.15 + r() * 0.5; return { n, v: Math.round(base * (grow + (1 - grow) * frac) * (0.6 + 0.4 * Math.min(1, frac * 2))), bot: 1 }; });
    rows.push({ n: App.user || 'You', v: mine != null ? mine : this.wk().v, me: 1 }); rows.sort((a, b) => b.v - a.v); return rows;
  },
  prevRank() { const P = App.S.prevWk; if (!P) return 0; return this.board(P.k, 1, P.v).findIndex(x => x.me) + 1; },
  claimPrize() { const P = App.S.prevWk; if (!P || P.claimed) return; const r = this.prevRank(), pr = r >= 1 && r <= 10 ? this.PRIZES[r - 1] : 0; P.claimed = true; if (pr) { App.S.balance = rd(App.S.balance + pr); App.updateBal(); snd('win'); if (Settings.v.confetti && !Settings.v.noAnim) Fx.confetti(); toast('Race prize +' + fmt(pr)); } else toast('No prize last week — top 10 win'); this.render(); },
  render() {
    const e = $('#rew-inner'); if (!e) return; this.wk(); const m = this.mis(), ms = this.today(), S = App.S;
    const lvl = Math.floor(S.wagered / 5000) + 1, rk = this.rake(), rows = this.board(), rank = rows.findIndex(x => x.me) + 1, medal = i => ['🥇', '🥈', '🥉'][i] || (i + 1);
    const left = 7 - ((Date.now() - 4 * 86400000) % 604800000) / 86400000;
    e.innerHTML = `
      <div class="panel"><h3>DAILY MISSIONS</h3><div class="hint" style="margin-bottom:10px">Fresh missions every day. Progress counts bets you make today.</div>
        ${ms.map((M, i) => { const v = Math.min(M.n, M.v(m)), done = m.claimed[M.id], ok = !done && v >= M.n; return `<div class="mis${done ? ' done' : ''}"><div class="mis-ico">${M.ico}</div><div class="mis-body"><div class="mis-t">${M.t(M.n)}</div><div class="vip-bar"><i style="width:${Math.min(100, v / M.n * 100)}%"></i></div><div class="hint">${fk(v)} / ${fk(M.n)}</div></div><button class="btn ${ok ? 'btn-primary' : 'btn-outline'}" ${ok ? '' : 'disabled'} onclick="Rewards.claim(${i})">${done ? '✓ Claimed' : ok ? 'Claim ' + fmt(M.reward) : fmt(M.reward)}</button></div>`; }).join('')}
      </div>
      <div class="panel"><h3>RAKEBACK</h3><div class="hint" style="margin-bottom:10px">Get ${(this.rate() * 100).toFixed(1)}% of everything you wager back (VIP level ${lvl}; +0.1% per level, up to 3%).</div>
        <div class="settings-row"><span class="settings-lbl">Available now</span><b style="color:var(--g);font-size:20px">${fmt(rk)}</b></div>
        <button class="btn btn-primary" style="margin-top:8px" onclick="Rewards.claimRake()">Claim rakeback</button></div>
      ${S.prevWk && !S.prevWk.claimed ? (() => { const r = this.prevRank(), pr = r >= 1 && r <= 10 ? this.PRIZES[r - 1] : 0; return `<div class="panel" style="border-color:var(--acc)"><h3>LAST WEEK'S RACE</h3><div class="settings-row"><span class="settings-lbl">You finished <b>#${r}</b> with ${fk(S.prevWk.v)} wagered</span><b style="color:var(--g);font-size:18px">${pr ? fmt(pr) : 'no prize'}</b></div><button class="btn btn-primary" style="margin-top:8px" onclick="Rewards.claimPrize()">${pr ? 'Claim prize' : 'Dismiss'}</button></div>`; })() : ''}
      <div class="panel"><h3>WEEKLY RACE</h3><div class="hint" style="margin-bottom:10px">Most wagered this week · resets Monday · ${left.toFixed(1)} days left · you are <b>#${rank}</b> of ${rows.length}</div>
        ${rows.slice(0, 10).map((x, i) => `<div class="gt-row race${x.me ? ' me' : ''}"><span>${medal(i)}</span><span>${esc(x.n)}</span><span>${fk(x.v)}</span></div>`).join('')}
        ${rank > 10 ? `<div class="gt-row race me"><span>${rank}</span><span>${esc(App.user || 'You')}</span><span>${fk(this.wk().v)}</span></div>` : ''}
        <div class="hint" style="margin-top:8px">Prizes at week end: 🥇 ${fk(this.PRIZES[0])} · 🥈 ${fk(this.PRIZES[1])} · 🥉 ${fk(this.PRIZES[2])} · 4–5th ${fk(this.PRIZES[3])} · 6–10th ${fk(this.PRIZES[5])}. Rivals are simulated.</div></div>`;
  }
};

/* ---------- effects ---------- */
const Fx = {
  confetti() {
    const cv = document.createElement('canvas'); cv.style.cssText = 'position:fixed;inset:0;width:100%;height:100%;pointer-events:none;z-index:9999'; cv.width = innerWidth; cv.height = innerHeight; document.body.appendChild(cv); const c = cv.getContext('2d');
    const cols = ['#ff7a1a', '#2f8bff', '#ffffff', '#ffc233', '#2ee59d'], P = Array.from({ length: 110 }, () => ({ x: cv.width / 2 + (Math.random() - .5) * 200, y: cv.height * .62, vx: (Math.random() - .5) * 15, vy: -8 - Math.random() * 12, r: Math.random() * 6, w: 5 + Math.random() * 6, c: cols[(Math.random() * cols.length) | 0] })); const t0 = performance.now();
    const f = now => { const k = (now - t0) / 1900; c.clearRect(0, 0, cv.width, cv.height); P.forEach(p => { p.vy += .45; p.x += p.vx; p.y += p.vy; p.r += .2; c.save(); c.translate(p.x, p.y); c.rotate(p.r); c.globalAlpha = Math.max(0, 1 - k); c.fillStyle = p.c; c.fillRect(-p.w / 2, -2, p.w, 4); c.restore(); }); if (k < 1) requestAnimationFrame(f); else cv.remove(); };
    requestAnimationFrame(f);
  }
};

/* ---------- favorites / recents ---------- */
