  toggle(id) { const a = this.ids(), i = a.indexOf(id); if (i >= 0) a.splice(i, 1); else a.push(id); store.set('cc_fav', a); this.refresh(); toast(i >= 0 ? 'Removed from favorites' : '★ Added to favorites'); },
  clear() { store.set('cc_fav', []); store.set('cc_recent', []); this.refresh(); toast('Favorites & recents cleared'); },
  recent() { return store.get('cc_recent', []); },
  touch(id) { const a = this.recent().filter(x => x !== id); a.unshift(id); store.set('cc_recent', a.slice(0, 8)); },
  star(id) { const on = this.has(id); return `<button class="fav${on ? ' on' : ''}" title="${on ? 'Unfavorite' : 'Favorite'}" onclick="event.stopPropagation();Fav.toggle('${id}')">${on ? '★' : '☆'}</button>`; },
  refresh() { Games.render(); Nav.applyFilter(); const q = $('#search'); if (q && q.value) Nav.search(q.value); }
};

/* ---------- profile extras: chart, achievements, per-game stats, CSV ---------- */
const Prof = {
  ACH: [['🎯', 'First Bet', 'Place a bet', S => S.bets >= 1], ['🎲', 'Getting Going', '100 bets', S => S.bets >= 100], ['🔥', 'Grinder', '1,000 bets', S => S.bets >= 1000],
    ['🏆', 'Winner', 'Win 1,000+ profit in one round', S => S.biggest >= 1000], ['🍀', 'Lucky', 'Hit a 50× payout', S => (S.bestMult || 0) >= 50], ['🚀', 'Moonshot', 'Hit a 1,000× payout', S => (S.bestMult || 0) >= 1000],
    ['💎', 'High Roller', 'Wager 100K total', S => S.wagered >= 1e5], ['🐋', 'Whale', 'Wager 10M total', S => S.wagered >= 1e7], ['🧭', 'Explorer', 'Play 10 different games', S => Object.keys(S.byGame || {}).length >= 10],
    ['🌟', 'Completionist', 'Play 25 different games', S => Object.keys(S.byGame || {}).length >= 25], ['👑', 'Level 10', 'Reach VIP level 10', S => Math.floor(S.wagered / 5000) + 1 >= 10]],
  extra() {
    const S = App.S; this.chart(S); const A = this.ACH, got = A.filter(a => a[3](S)).length;
    $('#prof-ach').innerHTML = `<div class="hint" style="margin-bottom:8px">${got} / ${A.length} unlocked</div><div class="ach-grid">${A.map(a => `<div class="ach${a[3](S) ? ' on' : ''}" title="${esc(a[2])}"><span>${a[0]}</span><b>${a[1]}</b><small>${a[2]}</small></div>`).join('')}</div>`;
    const rows = Object.entries(S.byGame || {}).sort((a, b) => b[1].w - a[1].w).slice(0, 12);
    $('#prof-games').innerHTML = rows.length ? `<div class="gt-row gt-h"><span>Game</span><span>Bets</span><span>Wagered</span><span>Net</span></div>` + rows.map(([g, v]) => { const net = v.r - v.w; return `<div class="gt-row"><span>${esc(g)}</span><span>${v.n}</span><span>${fk(v.w)}</span><span class="${net >= 0 ? 'win' : 'lose'}">${net >= 0 ? '+' : '-'}${fk(Math.abs(net))}</span></div>`; }).join('') : '<div class="hint">Play some games to see per-game stats.</div>';
  },
  chart(S) {
    const cv = $('#prof-chart'); if (!cv) return; const w = cv.clientWidth || 600, h = 150; cv.width = w; cv.height = h; const c = cv.getContext('2d'); c.clearRect(0, 0, w, h);
    const pts = [0]; S.history.forEach(x => pts.push(pts[pts.length - 1] + x.p - x.s)); if (pts.length < 2) { c.fillStyle = '#7f8aa8'; c.font = '13px Inter,sans-serif'; c.textAlign = 'center'; c.fillText('Your profit curve appears after your first bets', w / 2, h / 2); return; }
    const mn = Math.min(...pts), mx = Math.max(...pts), pad = 14, rng = (mx - mn) || 1, X = i => pad + i / (pts.length - 1) * (w - 2 * pad), Y = v => h - pad - (v - mn) / rng * (h - 2 * pad);
    c.strokeStyle = '#ffffff22'; c.setLineDash([4, 4]); c.beginPath(); c.moveTo(pad, Y(0)); c.lineTo(w - pad, Y(0)); c.stroke(); c.setLineDash([]);
    const up = pts[pts.length - 1] >= 0, col = up ? '#3ddc84' : '#ff5a5a'; c.beginPath(); pts.forEach((v, i) => i ? c.lineTo(X(i), Y(v)) : c.moveTo(X(i), Y(v))); c.strokeStyle = col; c.lineWidth = 2.5; c.lineJoin = 'round'; c.stroke();
    c.lineTo(X(pts.length - 1), h - pad); c.lineTo(X(0), h - pad); c.closePath(); const g = c.createLinearGradient(0, 0, 0, h); g.addColorStop(0, col + '40'); g.addColorStop(1, col + '00'); c.fillStyle = g; c.fill();
    c.fillStyle = '#9aa6c7'; c.font = '11px Inter,sans-serif'; c.textAlign = 'left'; c.fillText('Last ' + (pts.length - 1) + ' bets · now ' + (up ? '+' : '-') + fk(Math.abs(pts[pts.length - 1])), pad, 12);
  },
  csv() { const S = App.S; if (!S.history.length) return toast('No bets yet', true); const rows = ['game,time,stake,payout,net'].concat(S.history.map(h => [JSON.stringify(h.g), JSON.stringify(h.t), h.s, h.p, rd(h.p - h.s)].join(','))); const b = new Blob([rows.join('\n')], { type: 'text/csv' }), a = document.createElement('a'); a.href = URL.createObjectURL(b); a.download = 'cup_casino_bets.csv'; a.click(); }
};

/* ---------- accounts ---------- */
