    DAILY: { amt: 1000, per: 'day', icon: '☀️', t: 'Daily Top-Up', d: '$1,000 free every day.' },
    VIPWEEK: { amt: 10000, per: 'week', icon: '👑', t: 'VIP Weekly Reload', d: '$10,000 every week.', gold: 1 },
    LUCKY7: { amt: 7777, per: 'once', icon: '🍀', t: 'Lucky Sevens', d: '$7,777. One per account.' },
    CUPFINAL: { amt: 25000, per: 'once', icon: '🏆', t: 'Cup Final', d: '$25,000 for the big match. One per account.' },
    CASHBACK: { per: 'day', icon: '🛟', t: 'Cashback', d: '10% of your lifetime net losses (max $50,000), once a day.', fn: () => Math.min(50000, Math.round(Math.max(0, App.S.wagered - App.S.won) * 0.1)) },
    HIGHROLL: { amt: 100000, per: 'once', icon: '💎', t: 'High Roller', d: '$100,000. Needs VIP level 5 (wager 20,000).', minWag: 20000 }
  },
  key(c) { const d = this.CODES[c]; return d.per === 'once' ? c : d.per === 'day' ? c + App.today() : c + Math.floor(Date.now() / 604800000); },
