  render() {
    const e = $('#promo-list'); if (!e) return;
    e.innerHTML = Object.keys(this.CODES).map(c => { const d = this.CODES[c], st = this.status(c); return `<div class="promo-card${st ? ' done' : ''}"><div class="promo-icon">${d.icon}</div><div class="promo-info"><div class="promo-title"${d.gold ? ' style="color:var(--gold)"' : ''}>${d.t}</div><div class="promo-desc">${d.d}${st ? ' <b>· ' + st + '</b>' : ''}</div></div><div class="promo-code" onclick="Promo.fill('${c}');Promo.redeem()">${st ? c : 'CLAIM ' + c}</div></div>`; }).join('');
