    const bad = t => { m.textContent = t; m.style.color = 'var(--red)'; };
    if (c === 'ADMIN123') { Admin.toggle(); m.textContent = Admin.on ? 'Admin mode ON — open the ADMIN tab (bottom-left).' : 'Admin mode OFF.'; m.style.color = 'var(--g)'; $('#promo-in').value = ''; return; }
    const d = this.CODES[c]; if (!d) return bad('Invalid code.');
    const st = this.status(c); if (st) return bad(st + '.');
    const amt = d.fn ? d.fn() : d.amt; P[this.key(c)] = 1; App.S.balance = rd(App.S.balance + amt); App.updateBal(); snd('win'); if (amt >= 10000 && Settings.v.confetti && !Settings.v.noAnim) Fx.confetti();
    m.textContent = d.t + ' +' + fmt(amt); m.style.color = 'var(--g)'; $('#promo-in').value = ''; this.render();
