/* ---------- admin mode: outcome preview + the only way to change money ---------- */
const Admin = {
  on: !!store.get('cc_admin', false), q: {},
  cfg: Object.assign({ reveal: true, force: '', noLoss: false, boost: 1, auto: false }, store.get('cc_adm', {})),
  get reveal() { return this.cfg.reveal; }, get force() { return this.cfg.force; }, get noLoss() { return this.cfg.noLoss; }, get boost() { return this.cfg.boost; }, get auto() { return this.cfg.auto; },
  active() { return this.on && this.cfg.reveal; },
  save() { store.set('cc_adm', this.cfg); },
  refresh() { this.q = {}; if (Games.peekFn) safe(Games.peekFn); if (typeof Sports !== 'undefined' && Sports.render) safe(() => Sports.render()); },
  set(v) { this.on = !!v; store.set('cc_admin', this.on); this.ui(); this.refresh(); toast(this.on ? 'Admin mode on' : 'Admin mode off'); },
  toggle() { this.set(!this.on); },
  opt(k, v) { this.cfg[k] = v; this.save(); this.ui(); if (k === 'reveal' || k === 'force') this.refresh(); },
  need() { if (this.on) return true; toast('Admin mode required — enter the admin code in Promotions', true); return false; },
  // pre-rolled outcomes: the game consumes exactly what the preview showed. isWin lets "force win/lose" re-roll.
  pend(key, gen, isWin) {
    if (key in this.q) return this.q[key];
    let v = gen();
    if (this.on && this.cfg.force && isWin) { const want = this.cfg.force === 'win'; for (let i = 0; i < 600 && !!isWin(v) !== want; i++) v = gen(); }
    return (this.q[key] = v);
  },
  take(key, gen, isWin) { if (key in this.q) { const v = this.q[key]; delete this.q[key]; return v; } if (this.on && this.cfg.force && isWin) return this.pendTake(gen, isWin); return gen(); },
  pendTake(gen, isWin) { let v = gen(); const want = this.cfg.force === 'win'; for (let i = 0; i < 600 && !!isWin(v) !== want; i++) v = gen(); return v; },
  show(html) { const e = $('#admin-peek'); if (!e) return; if (!this.active()) { e.style.display = 'none'; return; } e.innerHTML = '<span class="ap-tag">ADMIN · NEXT RESULT</span> ' + html; e.style.display = 'block'; },
  clear() { const e = $('#admin-peek'); if (e) e.style.display = 'none'; },
  peek(key, gen, desc, isWin) { if (!this.active()) { this.clear(); return null; } const v = this.pend(key, gen, isWin); this.show(desc(v)); return v; },
  amt() { const v = parseFloat($('#adm-amt').value); return v; },
  addBal(sign) { const v = this.amt(); if (!(v > 0)) return toast('Enter an amount', true); App.S.balance = rd(Math.max(0, App.S.balance + sign * v)); App.updateBal(); toast((sign > 0 ? '+' : '-') + fmt(v)); },
  setBal() { const v = this.amt(); if (!(v >= 0)) return toast('Enter an amount', true); App.S.balance = rd(v); App.updateBal(); toast('Balance set to ' + fmt(v)); },
  quick(v) { App.S.balance = rd(App.S.balance + v); App.updateBal(); toast('+' + fmt(v)); },
  resetPromos() { App.S.promos = {}; App.updateBal(); toast('Promo claims cleared'); },
  ui() {
    document.body.classList.toggle('admin', this.on);
    const p = $('#adm-panel'); if (p) { p.style.display = this.on ? 'block' : 'none'; $('#adm-reveal').checked = this.cfg.reveal; $('#adm-force').value = this.cfg.force; $('#adm-noloss').checked = this.cfg.noLoss; $('#adm-boost').value = this.cfg.boost; $('#adm-auto').checked = this.cfg.auto; }
    const w = $('#w-add'); if (w) w.innerHTML = this.on ? [['1K', 1e3], ['10K', 1e4], ['100K', 1e5], ['1M', 1e6], ['100M', 1e8], ['1B', 1e9]].map(([l, v]) => `<span class="chip" onclick="Wallet.add(${v})">+${Settings.v.cur}${l}</span>`).join('') : '';
    const lock = $('#w-lock'); if (lock) lock.style.display = this.on ? 'none' : 'block';
    const wa = $('#w-admin'); if (wa) wa.style.display = this.on ? '' : 'none';
  }
};
const cstr = c => CM.rankStr(c.r) + CM.SUITS[c.s];
const fk = n => n >= 1e6 ? (n / 1e6).toFixed(n >= 1e7 ? 0 : 1).replace(/\.0$/, '') + 'M' : n >= 1e4 ? (n / 1e3).toFixed(n >= 1e5 ? 0 : 1).replace(/\.0$/, '') + 'K' : n >= 100 ? String(Math.round(n)) : n >= 10 ? n.toFixed(1).replace(/\.0$/, '') : String(n);

/* ---------- difficulty tiers: easy · normal · difficult · hard · extreme · insane · transcendent ---------- */
const Tier = {
  get(id) { const v = store.get('cc_tier', {})[id]; return v == null ? 1 : v; },
  set(id, t) { const o = store.get('cc_tier', {}); o[id] = t; store.set('cc_tier', o); },
  html(id) { return `<div class="lbl"><span>Difficulty</span><b id="tier-name"></b></div><select class="f-in tier-sel" id="tier-sel">${CM.TIER_NAMES.map((n, i) => `<option value="${i}"${i === this.get(id) ? ' selected' : ''}>${n}</option>`).join('')}</select><div class="hint" id="tier-hint"></div>`; },
  // kind: 'gate' (generic 1-in-f), 'crash' (shot down unless long flight), or a function(tier) for native-table games
  hint(kind, t) {
    if (typeof kind === 'function') return kind(t);
    const f = CM.TIER_F[t];
    if (t === 0) return 'Easy: a loss hands back 49.5% of your stake, wins pay half the profit. Same RTP, calmer swings.';
    if (t === 1) return 'Normal: the standard odds.';
    if (kind === 'crash') return `${CM.TIER_NAMES[t]}: only 1 flight in ${fk(f)} flies — and it flies ${fk(f)}× further. The rest are shot down at once.${t === 6 ? ' Insane × 100.' : ''}`;
    return `${CM.TIER_NAMES[t]}: wins pay ${fk(f)}× but land only 1 time in ${fk(f)}.${t === 6 ? ' Insane × 100 — practically unwinnable.' : ''}`;
  },
  bind(root, id, kind, cb) {
    const sel = $('#tier-sel', root); if (!sel) return this.get(id); const apply = () => { const t = +sel.value; this.set(id, t); $('#tier-name', root).textContent = CM.TIER_NAMES[t]; $('#tier-hint', root).textContent = this.hint(kind, t); sel.classList.toggle('hot', t >= 5); if (cb) cb(t); };
    sel.addEventListener('change', apply); apply(); return +sel.value;
  },
  u(id) { return Admin.take('gate' + id, () => CM.rnd()); },
  gateTxt(id, t, extraF) { const f = extraF || CM.TIER_F[t]; if (t <= 1 && !extraF) return ''; if (t === 0) return ''; const u = Admin.pend('gate' + id, () => CM.rnd()); return ' · gate <b>' + (u < 1 / f ? 'PASS' : 'FAIL') + '</b> (1 in ' + fk(f) + ')'; },
  gateOf(u, t) { if (t < 2) return ''; const f = CM.TIER_F[t]; return ' · gate <b>' + (u < 1 / f ? 'PASS' : 'FAIL') + '</b> (1 in ' + fk(f) + ')'; },
  F(t) { return t >= 2 ? CM.TIER_F[t] : 1; },
  settle(tier, stake, base, rtp, u) {
    if (tier === 0) return { pay: rd(CM.easyPay(stake, base, rtp)), note: ' · easy cushion' };
    if (tier === 1) return { pay: base, note: '' };
    const g = CM.gateF(CM.TIER_F[tier], base, u);
    return { pay: rd(g.pay), ok: g.ok, note: base > 0 ? (g.ok ? ` · gate passed ×${fk(g.f)}` : ` · gate failed (1 in ${fk(g.f)})`) : '' };
  },
  settleNat(tier, base, u) { const g = CM.natGate(tier, base, u); return { pay: rd(g.pay), ok: g.ok, note: tier < 6 || base <= 0 ? '' : (g.ok ? ' · gate passed ×100' : ' · gate failed (1 in 100)') }; }
};

/* ---------- navigation ---------- */
const Nav = {
  page: 'home', filter: 'all',
  go(page, arg) {
    this.page = page; $$('.page').forEach(p => p.classList.remove('active')); $('#page-' + page).classList.add('active');
    if (page === 'home') { this.filter = arg || 'all'; this.applyFilter(); $('#search').value = ''; this.search(''); }
    if (page === 'sports') Sports.setSport(arg || Sports.cur);
    if (page === 'profile') App.renderProfile(); if (page === 'promos') Promo.render(); if (page === 'rewards') Rewards.render(); if (page === 'settings') Settings.sessInfo();
    $$('.hn').forEach(h => h.classList.toggle('active', h.dataset.page === page && (page !== 'home' || h.dataset.filter === this.filter)));
    $$('.sb-item[data-sb]').forEach(i => { const [p, a] = i.dataset.sb.split(':'); i.classList.toggle('active', p === page && (a === undefined || (page === 'home' ? a === this.filter : a === Sports.cur))); });
    $$('.cat-tab').forEach(t => t.classList.toggle('active', t.dataset.f === this.filter));
  },
  applyFilter() { $$('#feed .sec').forEach(s => { s.style.display = (this.filter === 'all' || s.dataset.cat === this.filter) ? '' : 'none'; }); ['popular', 'favs', 'recent'].forEach(k => { const e = $('#feed .sec[data-cat="' + k + '"]'); if (e) e.style.display = this.filter === 'all' ? '' : 'none'; }); },
  search(q) {
    q = q.trim().toLowerCase();
    if (q && this.page !== 'home') this.go('home', 'all');
    $$('#feed .sec').forEach(s => { let any = false; $$('.game-card', s).forEach(c => { const m = !q || c.dataset.name.includes(q); c.style.display = m ? '' : 'none'; if (m) any = true; });
      if (q) s.style.display = any && !['popular', 'favs', 'recent'].includes(s.dataset.cat) ? '' : 'none'; });
    if (!q) this.applyFilter();
  }
};

/* ---------- game registry + modal ---------- */
const Games = {
  list: [], map: {}, cleanups: [], active: null, peekFn: null,
  reg(d) { this.list.push(d); this.map[d.id] = d; },
  open(id) {
    const d = this.map[id]; if (!d) return; Fav.touch(id);
    if (d.overlay) { d.overlay(); return; }
    this.close(true); this.active = d; this.peekFn = null; Admin.clear();
    $('#m-title').textContent = d.name.toUpperCase(); $('#m-info').textContent = d.sub || '';
    const old = $('#m-body'); const body = old.cloneNode(false); old.replaceWith(body); // fresh node = no leaked listeners
    $('#m-foot').innerHTML = `<span><b>RTP</b> ${d.rtp || '—'}</span><span><b>RNG</b> cryptographic, server-free</span>` + (d.rules ? `<span>${d.rules}</span>` : '');
    $('#modal-wrap').classList.add('open'); App.updateBal();
    const ctx = { onClose: fn => this.cleanups.push(fn), root: body, peek: fn => { this.peekFn = fn; body.addEventListener('click', () => setTimeout(fn, 40)); body.addEventListener('input', () => setTimeout(fn, 40)); safe(fn); } };
    try { d.mount(body, ctx); } catch (e) { console.error(e); body.innerHTML = '<div class="pad-m">This game failed to load: ' + esc(e.message) + '</div>'; }
  },
  close(silent) { this.cleanups.forEach(f => safe(f)); this.cleanups = []; this.active = null; this.peekFn = null; Admin.clear(); $('#modal-wrap').classList.remove('open'); if (!silent) { const o = $('#m-body'); const n = o.cloneNode(false); o.replaceWith(n); Fav.refresh(); } },
  PAL: [['#0f4fb8', '#050b1c'], ['#b24a00', '#120904'], ['#1a6cff', '#070d22'], ['#d65f00', '#1a0c03'], ['#0b3a8f', '#04080f'], ['#8a3a00', '#0a0a10']],
  grad(d) { let h = 0; for (const c of d.id) h = (h * 31 + c.charCodeAt(0)) >>> 0; return this.PAL[h % this.PAL.length]; },
  card(d) {
    const badge = d.badge ? `<span class="game-badge badge-${d.badge === 'LIVE' ? 'live' : d.badge === 'NEW' ? 'new' : 'hot'}">${d.badge}</span>` : '';
    return `<div class="game-card" data-id="${d.id}" data-name="${esc(d.name.toLowerCase())}" onclick="Games.open('${d.id}')"><div class="game-thumb" style="background:linear-gradient(135deg,${this.grad(d)[0]},${this.grad(d)[1]})">${badge}${Fav.star(d.id)}<span class="ic">${d.icon}</span><span class="rtp">RTP ${d.rtp || ''}</span></div><div class="game-info"><div class="game-name">${esc(d.name)}</div><div class="game-sub">${esc(d.sub || '')}</div></div></div>`;
  },
  render() {
    const secs = [['favs', '★ FAVORITES', () => 1], ['recent', 'RECENTLY PLAYED', () => 1], ['popular', 'POPULAR NOW', g => g.badge === 'HOT'], ['originals', 'CUP ORIGINALS', g => g.cat === 'originals'], ['slots', 'SLOTS', g => g.cat === 'slots'], ['tables', 'TABLE GAMES', g => g.cat === 'tables'], ['specialty', 'SPECIALTY', g => g.cat === 'specialty']];
    const fv = Fav.ids().map(i => this.map[i]).filter(Boolean), rc = Fav.recent().map(i => this.map[i]).filter(Boolean);
    $('#feed').innerHTML = secs.map(([k, t, f]) => { const gs = k === 'favs' ? fv : k === 'recent' ? rc : this.list.filter(f); if (!gs.length) return ''; return `<div class="sec" data-cat="${k}"><div class="sec-hdr"><h3>${t}</h3>${!['popular', 'favs', 'recent'].includes(k) ? `<span class="see-all" onclick="Nav.go('home','${k}')">See all</span>` : ''}</div><div class="games-grid">${gs.map(g => this.card(g)).join('')}</div></div>`; }).join('');
  }
};

/* ---------- shared game UI helpers ---------- */
const UI = {
  bet(id = 'bet', label = 'Bet amount') {
    return `<div class="lbl"><span>${label}</span></div><div class="inp-wrap"><span class="cur">${esc(Settings.v.cur)}</span><input id="${id}" type="number" min="0" step="any" value="${App.defBet()}" inputmode="decimal"><button type="button" data-ba="half" data-for="${id}">½</button><button type="button" data-ba="dbl" data-for="${id}">2×</button><button type="button" data-ba="max" data-for="${id}">Max</button></div>`;
  },
  val(root, id = 'bet') { const el = $('#' + id, root); const v = parseFloat(el && el.value); return v > 0 ? rd(v) : 0; },
  lock(root, on) { $$('input,select,button.act,.seg button,.inp-wrap button,.chip', root).forEach(e => { if (e.dataset.keep === undefined) e.disabled = !!on; }); },
  seg(id, items, sel) { return `<div class="seg" id="${id}">${items.map(([v, l]) => `<button type="button" data-v="${v}" class="${v == sel ? 'on' : ''}">${l}</button>`).join('')}</div>`; },
  bindSeg(root, id, cb) { const s = $('#' + id, root); if (!s) return; s.addEventListener('click', e => { const b = e.target.closest('button'); if (!b || b.disabled) return; $$('button', s).forEach(x => x.classList.toggle('on', x === b)); snd('tick'); cb(b.dataset.v); }); },
  segVal(root, id) { const b = $('#' + id + ' button.on', root); return b ? b.dataset.v : null; },
  res(root, kind, text) { const r = $('.res', root); if (!r) return; r.className = 'res show ' + kind; r.innerHTML = text; },
  resClear(root) { const r = $('.res', root); if (r) r.className = 'res'; },
  card(c, o = {}) { if (o.back) return '<div class="pc back' + (o.sm ? ' sm' : '') + '"></div>'; return `<div class="pc ${CM.isRed(c) ? 'r' : 'b'}${o.sm ? ' sm' : ''}${o.cls ? ' ' + o.cls : ''}"${o.id ? ` data-i="${o.id}"` : ''}>${CM.rankStr(c.r)}<small>${CM.SUITS[c.s]}</small></div>`; },
  stat(k, v, id, cls = '') { return `<div class="stat-box"><div class="k">${k}</div><div class="v ${cls}" ${id ? `id="${id}"` : ''}>${v}</div></div>`; },
  wait(ms) { return sleep(Settings.v.quick ? Math.min(ms * 0.2, 80) : ms); },
  // auto-bet widget
  auto(label = 'Auto bet') { return `<div class="lbl"><span>${label}</span><b>0 = ∞</b></div><div class="row2"><input class="f-in" data-auto-n type="number" min="0" value="10" style="min-width:0"><button type="button" class="act ghost" data-auto-btn data-keep style="padding:9px;font-size:14px">START</button></div>`; },
  bindAuto(root, runOnce) {
    const btn = $('[data-auto-btn]', root), nIn = $('[data-auto-n]', root); if (!btn) return;
    let running = false;
    const stop = () => { running = false; btn.textContent = 'START'; btn.classList.remove('red'); btn.classList.add('ghost'); };
    btn.addEventListener('click', async () => {
      if (running) { stop(); return; }
      running = true; btn.textContent = 'STOP'; btn.classList.remove('ghost'); btn.classList.add('red');
      let n = parseInt(nIn.value) || 0; let i = 0; const bal0 = App.S.balance;
      while (running && (n === 0 || i < n)) { const ok = await runOnce(); if (ok === false) break; i++; { const lp = App.last, V = Settings.v; if (V.autoWin > 0 && lp && lp.s > 0 && lp.p / lp.s >= V.autoWin) { toast('Auto-bet stopped: ' + (lp.p / lp.s).toFixed(1) + '× win'); break; } if (V.autoLoss > 0 && bal0 - App.S.balance >= V.autoLoss) { toast('Auto-bet stopped: loss limit reached'); break; } } if (n > 0) nIn.value = n - i; await sleep(Settings.v.quick ? 60 : 280); }
      stop(); if (n > 0) nIn.value = n;
    });
    Games.cleanups.push(() => { running = false; });
  },
  histPills(arr, max = 14) { return arr.slice(-max).reverse().map(p => `<span class="pill ${p.c}">${p.t}</span>`).join(''); }
};
document.addEventListener('click', e => {
  const b = e.target.closest('[data-ba]'); if (!b) return; const i = document.getElementById(b.dataset.for); if (!i) return;
  const v = parseFloat(i.value) || 0; i.value = b.dataset.ba === 'half' ? rd(Math.max(0.01, v / 2)) : b.dataset.ba === 'dbl' ? rd(v * 2) : rd(App.S.balance); snd('tick');
});
document.addEventListener('keydown', e => { if (e.key === 'Escape') { Games.close(); Auth.close(); Wallet.close(); if (typeof Aviator !== 'undefined') Aviator.close(); } });

/* ---------- live feed (decorative bots) ---------- */
const Live = {
  names: ['luckyfox', 'nova88', 'BigMike', 'aceofspades', 'zeta_x', 'chipmunk', 'ReelDeal', 'hodlr', 'jade.k', 'StakeSam', 'milo7', 'queenbee', 'ghost404', 'dr_odds', 'rocketRay', 'sigma', 'vegasVic', 'lilac', 'orion', 'tank'],
  add(user, game, amt, win) {
    const f = $('#live-feed'); if (!f) return; const d = document.createElement('div'); d.className = 'bet-row';
    d.innerHTML = `<div class="bet-av">${esc(user.slice(0, 2).toUpperCase())}</div><div class="bet-info"><div class="bet-user">${esc(user)}</div><div class="bet-game">${esc(game)}</div></div><div class="bet-amt ${win ? 'g' : 'r'}">${win ? '+' : '-'}${fmt(amt)}</div>`;
    f.insertBefore(d, f.firstChild); while (f.children.length > 14) f.removeChild(f.lastChild);
  },
  mine(game, stake, payout) { this.add(App.user || 'You', game, Math.abs(payout - stake) || stake, payout >= stake); },
  tick() {
    const g = CM.pick(Games.list), win = CM.rnd() < 0.42, amt = Math.round(Math.exp(CM.rnd() * 7) * 5) / 1;
    this.add(CM.pick(this.names), g ? g.name : 'Crash', win ? amt * (1 + CM.rnd() * 3) : amt, win);
  }
};

/* ---------- banner ---------- */
const Banner = {
  i: 0, t: null,
  init() {
    const sl = $$('#banner .slide'); $('#dots').innerHTML = sl.map((_, i) => `<i class="${i ? '' : 'on'}" data-i="${i}"></i>`).join('');
    $('#dots').addEventListener('click', e => { const i = e.target.dataset.i; if (i !== undefined) this.show(+i); });
    this.t = setInterval(() => this.show((this.i + 1) % sl.length), 5500);
  },
  show(i) { this.i = i; $$('#banner .slide').forEach((s, k) => s.classList.toggle('on', k === i)); $$('#dots i').forEach((d, k) => d.classList.toggle('on', k === i)); }
};

/* =====================================================================
   ORIGINALS 1 — Crash, Aviator, Dice, Limbo, Mines
   ===================================================================== */
const GM = (ctrl, stage, top) => `<div class="gm"><div class="gm-ctrl">${ctrl}</div><div class="gm-stage${top ? ' top' : ''}">${stage}<div class="res"></div></div></div>`;
const multColor = m => m < 2 ? 'var(--g)' : m < 5 ? 'var(--gold)' : m < 10 ? 'var(--orange)' : 'var(--red)';
const pillFor = m => ({ c: m < 2 ? 'l' : m < 10 ? 'w' : 'm', t: m.toFixed(2) + '×' });

/* ------------------------------------------------------------------ CRASH */
Games.reg({
  id: 'crash', name: 'Crash', cat: 'originals', sub: 'Cup Original', badge: 'HOT', icon: '🚀', grad: ['#3a0f2b', '#14101f'], rtp: '99%',
  rules: 'Cash out before the rocket crashes. P(crash ≥ x) = 99 / x.',
  mount(root, ctx) {
    root.innerHTML = GM(
      UI.bet() + Tier.html('crash') + `<div class="lbl"><span>Auto cash-out at</span><b>0 = off</b></div><div class="inp-wrap"><input id="cr-auto" type="number" min="0" step="0.01" value="2.00"><span class="cur" style="padding-right:10px">×</span></div>
      <button class="act" id="cr-go">BET</button><div class="hint" id="cr-hint">Place a bet to launch the rocket.</div>${UI.stat('Profit on win', fmt(0), 'cr-profit', 'g')}`,
      `<div class="hist-pills" id="cr-hist"></div><div style="position:relative;width:100%;max-width:640px"><canvas class="fit" id="cr-cv" width="640" height="340"></canvas><div class="av-mid"><div class="big-num" id="cr-mult" style="color:var(--g)">1.00×</div><div id="cr-sub" class="hint" style="font-size:13px;margin-top:6px"></div></div></div>`);
    const cv = $('#cr-cv', root), go = $('#cr-go', root), hist = []; let st = null, raf = 0;
    let tier = 1; const genCr = () => CM.crashTier(tier);
    const pk = () => Admin.peek('crash' + tier, genCr, v => 'Next crash point <b>' + v.toFixed(2) + '×</b>' + (v <= 1 ? ' — instant bust' : ' — cash out before it'), v => v >= (parseFloat($('#cr-auto', root).value) || 2));
    const draw = (t, m, crashed) => {
      const c = cv.getContext('2d'), W = cv.width, H = cv.height, P = 28; c.clearRect(0, 0, W, H);
      c.fillStyle = '#0a1226'; c.fillRect(0, 0, W, H); c.strokeStyle = '#17264a'; c.lineWidth = 1;
      for (let i = 0; i <= 6; i++) { c.beginPath(); c.moveTo(P, P + i * (H - 2 * P) / 6); c.lineTo(W - P, P + i * (H - 2 * P) / 6); c.stroke(); }
      const maxT = Math.max(8, t * 1.1), maxM = Math.max(2, m * 1.18); const X = tt => P + tt / maxT * (W - 2 * P), Y = mm => H - P - (mm - 1) / (maxM - 1) * (H - 2 * P);
      c.beginPath(); c.moveTo(X(0), Y(1)); const N = 60; for (let i = 1; i <= N; i++) { const tt = t * i / N; c.lineTo(X(tt), Y(Math.exp(tt * (st ? st.rate : 0.07)))); }
      c.lineWidth = 4; c.strokeStyle = crashed ? '#ff5a36' : '#47b8ff'; c.shadowColor = c.strokeStyle; c.shadowBlur = 12; c.stroke(); c.shadowBlur = 0;
      c.lineTo(X(t), Y(1)); c.closePath(); c.fillStyle = crashed ? '#ff5a3618' : '#47b8ff18'; c.fill();
      c.font = '26px serif'; c.fillText(crashed ? '💥' : '🚀', X(t) - 12, Y(m) + 6);
      c.fillStyle = '#4f6590'; c.font = '10px Orbitron'; [2, 5, 10, 25, 100].filter(v => v < maxM).forEach(v => c.fillText(v + '×', 4, Y(v) + 3));
    };
    const showMult = (m, crashed) => { const e = $('#cr-mult', root); e.textContent = m.toFixed(2) + '×'; e.style.color = crashed ? 'var(--red)' : multColor(m); };
    const finish = (crashed, payout) => {
      cancelAnimationFrame(raf); const s = st; st = null; go.className = 'act'; go.textContent = 'BET'; UI.lock(root, false);
      if (crashed) { showMult(s.cp, true); draw(s.t, s.cp, true); $('#cr-sub', root).textContent = 'CRASHED'; UI.res(root, 'lose', `Crashed at ${s.cp.toFixed(2)}× — lost ${fmt(s.bet)}`); snd('boom'); }
      if (s.tier === 0) { payout = rd(CM.easyPay(s.bet, payout, 0.99)); if (crashed) UI.res(root, 'lose', `Crashed at ${s.cp.toFixed(2)}× — easy cushion returned ${fmt(payout)}`); } App.pay('Crash', s.bet, payout); hist.push(pillFor(s.cp)); $('#cr-hist', root).innerHTML = UI.histPills(hist); pk();
    };
    const cash = at => { const s = st; const m = at || s.m; const pay = rd(s.bet * m); s.cashed = true; showMult(m, false); UI.res(root, 'win', `Cashed out at ${m.toFixed(2)}× — won ${fmt(pay)}`); finish(false, pay); };
    const loop = now => {
      if (!st) return; const t = (now - st.t0) / 1000 * (Settings.v.quick ? 3 : 1); st.t = t; const m = Math.exp(t * st.rate); st.m = m;
      const auto = parseFloat($('#cr-auto', root).value) || 0;
      if (Admin.on && Admin.auto && st.cp > 1.02 && m >= st.cp - 0.015) return cash(Math.max(1.01, st.cp - 0.01));
      if (auto > 1 && auto <= st.cp && m >= auto) return cash(auto);
      if (m >= st.cp) return finish(true, 0);
      showMult(m, false); draw(t, m, false); $('#cr-go', root).textContent = 'CASH OUT ' + fmt(st.bet * m); raf = requestAnimationFrame(loop);
    };
    go.onclick = () => {
      if (st) return cash();
      const bet = UI.val(root); if (!App.take(bet)) return;
      UI.resClear(root); UI.lock(root, true); go.disabled = false;
      st = { bet, tier, cp: Admin.take('crash' + tier, genCr, v => v >= (parseFloat($('#cr-auto', root).value) || 2)), t0: performance.now(), rate: 0.1, t: 0, m: 1 }; $('#cr-sub', root).textContent = ''; go.className = 'act gold';
      if (st.cp <= 1.0) return finish(true, 0);
      raf = requestAnimationFrame(loop);
    };
    const upd = () => { const b = UI.val(root), a = parseFloat($('#cr-auto', root).value) || 0; $('#cr-profit', root).textContent = a > 1 ? fmt(b * (a - 1)) : '—'; };
    root.addEventListener('input', upd); upd();
    st = { rate: .1 }; draw(0, 1, false); st = null; tier = Tier.bind(root, 'crash', 'crash', t => { tier = t; pk(); }); ctx.peek(pk);
    ctx.onClose(() => { cancelAnimationFrame(raf); if (st) { const s = st; st = null; App.pay('Crash', s.bet, 0); } });
  }
});

/* ------------------------------------------------------------------ DICE */
Games.reg({
  id: 'dice', name: 'Dice', cat: 'originals', sub: 'Cup Original', icon: '🎲', grad: ['#143a6b', '#0b1a33'], rtp: '99%',
  rules: 'Roll 0.00–99.99. Win if the roll is over/under your target.',
  mount(root, ctx) {
    root.innerHTML = GM(
      UI.bet() + Tier.html('dice') + `<div class="lbl"><span>Mode</span></div>` + UI.seg('dc-mode', [['under', 'Roll Under'], ['over', 'Roll Over']], 'over') +
      `<div class="row2">${UI.stat('Multiplier', '2.0000×', 'dc-mult')}${UI.stat('Win chance', '49.50%', 'dc-chance')}</div>` +
      `<button class="act" id="dc-go">ROLL DICE</button>` + UI.auto(),
      `<div class="hist-pills" id="dc-hist"></div><div class="big-num" id="dc-roll" style="color:#fff">—</div><div class="dice-track" id="dc-track"><div class="win" id="dc-win"></div><div class="mark" id="dc-mark" style="left:50%">50</div></div>
       <input type="range" class="dice-slider" id="dc-t" min="2" max="98" step="0.01" value="50.5"><div class="dice-scale"><span>0</span><span>25</span><span>50</span><span>75</span><span>100</span></div><div class="hint" id="dc-tl" style="margin-top:8px;font-size:13px"></div>`);
    let over = true; const t = $('#dc-t', root), hist = [];
    const tv = () => parseFloat(t.value);
    let tier = 1;
    const pk = () => Admin.peek('dice', CM.diceRoll, v => { const T = tv(), w = CM.diceWin(v, T, over); return 'Next roll <b>' + v.toFixed(2) + '</b> → <b>' + (w ? 'WIN' : 'LOSE') + '</b> (' + (over ? 'over ' : 'under ') + T.toFixed(2) + ')' + Tier.gateTxt('dice', tier); }, v => CM.diceWin(v, tv(), over));
    const upd = () => {
      const T = tv(); if (over && CM.diceChance(T, true) < .02) t.value = 97.98; if (!over && CM.diceChance(T, false) < .02) t.value = 2;
      const T2 = tv(), ch = CM.diceChance(T2, over), mu = CM.diceMult(T2, over);
      $('#dc-mult', root).textContent = mu.toFixed(4) + '×'; $('#dc-chance', root).textContent = (ch * 100).toFixed(2) + '%';
      $('#dc-tl', root).textContent = (over ? 'Roll over ' : 'Roll under ') + T2.toFixed(2);
      const w = $('#dc-win', root); if (over) { w.style.left = T2 + '%'; w.style.right = '0'; w.style.width = 'auto'; } else { w.style.left = '0'; w.style.right = 'auto'; w.style.width = T2 + '%'; }
      $('#dc-track', root).style.background = 'var(--red)';
    };
    UI.bindSeg(root, 'dc-mode', v => { over = v === 'over'; upd(); }); t.addEventListener('input', upd); upd();
    const run = async () => {
      const bet = UI.val(root); if (!App.take(bet)) return false; const T = tv(), roll = Admin.take('dice', CM.diceRoll, v => CM.diceWin(v, tv(), over)), win0 = CM.diceWin(roll, T, over), mu = CM.diceMult(T, over), u = Tier.u('dice'), st = Tier.settle(tier, bet, win0 ? bet * mu : 0, 0.99, u), win = st.pay > bet;
      const mk = $('#dc-mark', root); mk.style.left = Math.min(98, Math.max(2, roll)) + '%'; mk.textContent = roll.toFixed(2);
      const rEl = $('#dc-roll', root); const t0 = performance.now(); const dur = Settings.v.quick ? 60 : 420;
      await new Promise(r => { const f = n => { const k = Math.min(1, (n - t0) / dur); rEl.textContent = k < 1 ? (CM.rnd() * 100).toFixed(2) : roll.toFixed(2); if (k < 1) requestAnimationFrame(f); else r(); }; requestAnimationFrame(f); });
      rEl.style.color = win ? 'var(--g)' : 'var(--red)'; const pay = st.pay; App.pay('Dice', bet, pay);
      hist.push({ c: win0 ? 'w' : 'l', t: roll.toFixed(2) }); $('#dc-hist', root).innerHTML = UI.histPills(hist, 10);
      UI.res(root, win ? 'win' : pay === bet ? 'push' : 'lose', (win ? `Rolled ${roll.toFixed(2)} — won ${fmt(pay)} (${(pay / bet).toFixed(2)}×)` : pay > 0 ? `Rolled ${roll.toFixed(2)} — returned ${fmt(pay)}` : `Rolled ${roll.toFixed(2)} — lost ${fmt(bet)}`) + st.note); pk(); return true;
    };
    $('#dc-go', root).onclick = run; UI.bindAuto(root, run); tier = Tier.bind(root, 'dice', 'gate', t => { tier = t; pk(); }); ctx.peek(pk);
  }
});

/* ----------------------------------------------------------------- LIMBO */
Games.reg({
  id: 'limbo', name: 'Limbo', cat: 'originals', sub: 'Cup Original', badge: 'HOT', icon: '🎯', grad: ['#3b1c6b', '#120b25'], rtp: '99%',
  rules: 'Win if the result reaches your target. Chance = 99 / target.',
  mount(root, ctx) {
    root.innerHTML = GM(
      UI.bet() + Tier.html('limbo') + `<div class="lbl"><span>Target multiplier</span></div><div class="inp-wrap"><input id="lb-t" type="number" min="1.01" max="1000000" step="0.01" value="2.00"><span class="cur" style="padding-right:10px">×</span></div>
      <div class="chips">${[1.5, 2, 3, 5, 10, 25, 100, 1000].map(v => `<span class="chip" data-t="${v}">${v}×</span>`).join('')}</div>
      <div class="row2">${UI.stat('Win chance', '49.50%', 'lb-ch')}${UI.stat('Profit on win', fmt(0), 'lb-pr', 'g')}</div><button class="act" id="lb-go">LAUNCH</button>` + UI.auto(),
      `<div class="hist-pills" id="lb-hist"></div><div class="big-num" id="lb-num" style="color:#fff;font-size:min(110px,16vw)">1.00×</div><div class="hint" style="margin-top:6px">Win if result ≥ target</div>`);
    const hist = [];
    let tier = 1; const genLb = () => CM.crashTier(tier);
    const pk = () => Admin.peek('limbo' + tier, genLb, v => { const T = tgt(); return 'Next result <b>' + v.toFixed(2) + '×</b> → <b>' + (v >= T ? 'WIN' : 'LOSE') + '</b> at target ' + T + '×'; }, v => v >= tgt());
    const tgt = () => Math.max(1.01, Math.min(1e6, parseFloat($('#lb-t', root).value) || 2));
    const upd = () => { const T = tgt(); $('#lb-ch', root).textContent = Math.min(98, (99 / T)).toFixed(T > 1000 ? 4 : 2) + '%'; $('#lb-pr', root).textContent = fmt(UI.val(root) * (T - 1)); };
    root.addEventListener('input', upd); root.addEventListener('click', e => { const c = e.target.closest('[data-t]'); if (c) { $('#lb-t', root).value = c.dataset.t; upd(); } }); upd();
    const run = async () => {
      const bet = UI.val(root), T = tgt(); if (!App.take(bet)) return false; const r = Admin.take('limbo' + tier, genLb, v => v >= tgt()), win0 = r >= T, el = $('#lb-num', root);
      el.style.color = '#fff'; const dur = Settings.v.quick ? 50 : 520, t0 = performance.now();
      await new Promise(res => { const f = n => { const k = Math.min(1, (n - t0) / dur); const v = 1 + (r - 1) * Math.pow(k, 3); el.textContent = v.toFixed(2) + '×'; if (k < 1) requestAnimationFrame(f); else res(); }; requestAnimationFrame(f); });
      let pay = win0 ? rd(bet * T) : 0; if (tier === 0) pay = rd(CM.easyPay(bet, pay, 0.99)); const win = win0; el.textContent = r.toFixed(2) + '×'; el.style.color = win ? 'var(--g)' : 'var(--red)'; App.pay('Limbo', bet, pay);
      hist.push({ c: win ? 'w' : 'l', t: r.toFixed(2) + '×' }); $('#lb-hist', root).innerHTML = UI.histPills(hist, 10);
      UI.res(root, win ? 'win' : 'lose', win ? `${r.toFixed(2)}× ≥ ${T}× — won ${fmt(pay)}` : `${r.toFixed(2)}× < ${T}× — ${tier === 0 ? 'easy cushion returned ' + fmt(pay) : 'lost ' + fmt(bet)}`); pk(); return true;
    };
    $('#lb-go', root).onclick = run; UI.bindAuto(root, run); tier = Tier.bind(root, 'limbo', 'crash', t => { tier = t; pk(); }); ctx.peek(pk);
  }
});

/* ----------------------------------------------------------------- MINES */
Games.reg({
  id: 'mines', name: 'Mines', cat: 'originals', sub: 'Cup Original', badge: 'HOT', icon: '💣', grad: ['#4a1530', '#140b18'], rtp: '99%',
  rules: 'Reveal gems, avoid mines. Multiplier = 99% × C(25,k)/C(25−m,k).',
  mount(root, ctx) {
    root.innerHTML = GM(
      UI.bet() + Tier.html('mines') + `<div class="lbl"><span>Mines on the board</span><b id="mn-cnt">3</b></div>
      <button class="act" id="mn-go">BET</button><button class="act ghost" id="mn-rand" style="padding:9px;font-size:14px" disabled>PICK RANDOM TILE</button>
      <div class="row2">${UI.stat('Next tile', '—', 'mn-next')}${UI.stat('Total profit', fmt(0), 'mn-prof', 'g')}</div>`,
      `<div class="mines-grid" id="mn-grid">${Array.from({ length: 25 }, (_, i) => `<button class="mcell" data-i="${i}" disabled></button>`).join('')}</div>`);
    let g = null; const cells = $$('.mcell', root), go = $('#mn-go', root), rb = $('#mn-rand', root);
    let tier = 1; const mc = () => CM.MINES_BY_TIER[tier];
    const pk = () => {
      if (!Admin.active()) { Admin.clear(); cells.forEach(c => c.classList.remove('adm')); return; }
      const lay = g ? g.layout : Admin.pend('mines' + mc(), () => CM.minesLayout(mc()));
      Admin.show('Mines on tiles <b>' + lay.map((x, i) => x ? i + 1 : 0).filter(Boolean).join(', ') + '</b> (marked on the board)' + (tier === 6 ? (() => { const u = g ? g.u : Admin.pend('gatemines', () => CM.rnd()); return ' · gate <b>' + (u < 0.01 ? 'PASS' : 'FAIL') + '</b> (1 in 100)'; })() : ''));
      cells.forEach((c, i) => c.classList.toggle('adm', !!lay[i]));
    };
    const info = () => { if (!g) { $('#mn-next', root).textContent = '—'; return; } const cur = CM.minesMult(g.mines, g.picks), nxt = CM.minesMult(g.mines, g.picks + 1); $('#mn-next', root).textContent = g.picks === 25 - g.mines ? '—' : nxt.toFixed(2) + '×'; $('#mn-prof', root).textContent = fmt(g.bet * cur - g.bet); go.textContent = g.picks ? 'CASH OUT ' + fmt(g.bet * cur) : 'PLAY — PICK A TILE'; go.disabled = g.picks === 0; };
    const end = (win, payout) => {  // payout is the base (pre-gate) return
      const s = g; g = null; cells.forEach((c, i) => { c.disabled = true; if (!c.classList.contains('open')) { c.classList.add('open', 'dim'); c.textContent = s.layout[i] ? '💣' : '💎'; c.classList.add(s.layout[i] ? 'bomb' : 'gem'); } });
      go.textContent = 'BET'; go.disabled = false; go.className = 'act'; rb.disabled = true; UI.lock(root, false); rb.disabled = true;
      const st = Tier.settleNat(s.tier, payout, s.u); payout = st.pay; App.pay('Mines', s.bet, payout); pk(); UI.res(root, win && payout > 0 ? 'win' : 'lose', (win ? (payout > 0 ? `Cashed out ${CM.minesMult(s.mines, s.picks).toFixed(2)}× — won ${fmt(payout)}` : `Cashed out ${CM.minesMult(s.mines, s.picks).toFixed(2)}× — but the gate held. Lost ${fmt(s.bet)}`) : `Boom! Lost ${fmt(s.bet)}`) + st.note); if (!win) snd('boom');
    };
    const pick = i => {
      if (!g || cells[i].classList.contains('open')) return; const c = cells[i]; c.classList.add('open');
      if (g.layout[i]) { c.textContent = '💣'; c.classList.add('bomb'); c.classList.remove('dim'); return end(false, 0); }
      c.textContent = '💎'; c.classList.add('gem'); g.picks++; snd('tick'); info();
      if (g.picks === 25 - g.mines) end(true, rd(g.bet * CM.minesMult(g.mines, g.picks)));
    };
    cells.forEach((c, i) => c.addEventListener('click', () => pick(i)));
    rb.onclick = () => { if (!g) return; const free = cells.map((c, i) => i).filter(i => !cells[i].classList.contains('open')); pick(CM.pick(free)); };
    go.onclick = () => {
      if (g) { if (g.picks) end(true, rd(g.bet * CM.minesMult(g.mines, g.picks))); return; }
      const bet = UI.val(root); if (!App.take(bet)) return; UI.resClear(root);
      g = { bet, tier, u: Tier.u('mines'), mines: mc(), picks: 0, layout: Admin.take('mines' + mc(), () => CM.minesLayout(mc())) }; cells.forEach(c => { c.className = 'mcell'; c.textContent = ''; c.disabled = false; });
      UI.lock(root, true); go.disabled = true; go.className = 'act gold'; rb.disabled = false; info();
    };
    tier = Tier.bind(root, 'mines', t => (t === 6 ? 'Transcendent: Insane (24 mines) with 100× the multipliers — but only a 1-in-100 chance that a cash-out pays at all.' : `${CM.TIER_NAMES[t]}: ${CM.MINES_BY_TIER[t]} mine${CM.MINES_BY_TIER[t] > 1 ? 's' : ''} on the 25-tile board.`), t => { tier = t; $('#mn-cnt', root).textContent = mc(); pk(); });
    ctx.peek(pk);
    ctx.onClose(() => { if (g) { const s = g; g = null; App.pay('Mines', s.bet, s.picks ? Tier.settleNat(s.tier, rd(s.bet * CM.minesMult(s.mines, s.picks)), s.u).pay : 0); } });
  }
});

/* =====================================================================
   AVIATOR — single-bet crash game. A jet launches off a carrier, dodges
   missiles and collects multiplier tokens; the crash missile hits at the
   exact crash point. Cash out and it lands on a carrier. 97% RTP, 7 tiers.
   ===================================================================== */
const Aviator = {
  el: null, raf: 0, stop: false, hist: null,
  EDGE: 0.03, RATE: 0.07,
  cur() { return ({ '$': 'USD', '€': 'EUR', '£': 'GBP', '₿': 'BTC', 'Ξ': 'ETH' })[Settings.v.cur] || 'USD'; },
  num(n) { return n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); },
  close() {
    if (!this.el) return; this.stop = true; cancelAnimationFrame(this.raf);
    const B = this.B; if (B) { if (B.amt > 0 && !B.live) { App.S.balance = rd(App.S.balance + B.amt); App.S.wagered = rd(App.S.wagered - B.amt); } else if (B.live && !B.cashed) App.pay('Aviator', B.amt, 0); }
    this.B = null; App.updateBal(); this.el.remove(); this.el = null; Admin.clear(); Fav.refresh();
  },
  open() {
    if (this.el) return; this.stop = false; const me = this;
    const el = this.el = document.createElement('div'); el.className = 'avx';
    el.innerHTML = `
      <div class="avx-head"><div class="avx-logo">Aviator</div><div class="avx-peek" id="avx-peek" style="display:none"></div><div class="avx-bal"><b id="avx-bal">0.00</b> <small>${this.cur()}</small></div><button class="avx-x" title="Close" onclick="Aviator.close()">✕</button></div>
      <div class="avx-hist" id="avx-hist"></div>
      <div class="avx-body">
        <aside class="avx-side">
          <div class="avx-tabs" id="avx-tabs"><button data-t="all" class="on">All Bets</button><button data-t="prev">Previous</button><button data-t="top">Top</button></div>
          <div class="avx-sum"><span><b id="avx-n">0</b> bets</span><span id="avx-tot">0.00 ${this.cur()}</span></div>
          <div class="avx-thead"><span>Player</span><span>Bet</span><span>X</span><span>Win</span></div>
          <div class="avx-rows" id="avx-rows"></div>
        </aside>
        <section class="avx-main">
          <div class="avx-stage"><canvas id="avx-cv"></canvas><div class="avx-center" id="avx-center"></div></div>
          <div class="avx-pnl">
            <div class="avx-tierrow"><label>Difficulty</label><select id="avx-tier" class="f-in tier-sel">${CM.TIER_NAMES.map((n, i) => `<option value="${i}"${i === Tier.get('aviator') ? ' selected' : ''}>${n}</option>`).join('')}</select><small id="avx-th"></small></div>
            <div class="avx-ptabs" id="avx-ptabs"><button data-m="bet" class="on">Bet</button><button data-m="auto">Auto</button></div>
            <div class="avx-pbody">
              <div class="avx-amt">
                <div class="avx-step"><button id="avx-minus" type="button">−</button><input id="avx-in" type="number" min="0" step="any" value="${App.defBet()}" inputmode="decimal"><button id="avx-plus" type="button">+</button></div>
                <div class="avx-quick">${[10, 50, 100, 500].map(v => `<button type="button" data-q="${v}">${v}</button>`).join('')}</div>
              </div>
              <button class="avx-go" id="avx-go" type="button"><span class="l1">BET</span><span class="l2"></span></button>
            </div>
            <div class="avx-autorow" id="avx-autorow" style="display:none">
              <label class="avx-sw"><input type="checkbox" id="avx-ap"><i></i><span>Auto Play</span></label>
              <label class="avx-sw"><input type="checkbox" id="avx-ac"><i></i><span>Auto Cash Out</span></label>
              <div class="avx-acv"><input id="avx-av" type="number" min="1.01" step="0.01" value="2.00"><span>x</span></div>
            </div>
          </div>
        </section>
      </div>`;
    document.body.appendChild(el);
    const $a = id => $('#' + id, el), cv = $a('avx-cv'), center = $a('avx-center'), go = $a('avx-go'), inp = $a('avx-in');
    /* ---------- state ---------- */
    const B = this.B = { amt: 0, live: false, cashed: false, at: 0, tier: 1 };
    const payOf = (tr, amt, base) => tr === 0 ? rd(CM.easyPay(amt, base, 0.97)) : base;
    let tier = Tier.get('aviator'), ph = 'wait', tWait = performance.now() + 5000, t0 = 0, cp = 1, m = 1, t = 0, tCrash = 0, tab = 'all', lastRows = 0, rot = 0, lastNow = performance.now();
    if (!this.hist) this.hist = Array.from({ length: 22 }, () => CM.crashPoint(this.EDGE));
    const hist = this.hist;
    const pcls = v => v < 2 ? 'a' : v < 10 ? 'b' : 'c';
    const drawHist = () => { $a('avx-hist').innerHTML = hist.slice(-24).reverse().map(v => `<span class="avx-pill ${pcls(v)}">${v.toFixed(2)}x</span>`).join(''); };
    /* ---------- fake players ---------- */
    const L = 'abcdefghijklmnopqrstuvwxyz', mask = () => { const c = CM.pick(L.split('')), e = CM.pick((L + '0123456789').split('')); return c + '***' + e; };
    const COLS = ['#c017b4', '#913ef8', '#34b4ff', '#28a909', '#d07206', '#e50539', '#00b3a4'];
    const target = () => { const r = CM.rnd(); return r < .5 ? 1.1 + CM.rnd() * 1.6 : r < .82 ? 2.5 + CM.rnd() * 4 : r < .95 ? 6 + CM.rnd() * 20 : 25 + CM.rnd() * 150; };
    const mkBots = () => Array.from({ length: 30 }, () => ({ name: mask(), col: CM.pick(COLS), bet: Math.max(1, Math.round(Math.exp(CM.rnd() * 6.2))), tgt: Math.round(target() * 100) / 100, done: 0 }));
    let bots = mkBots(), prevRows = [], top = [], playersN = 1500 + CM.rint(1500);
    const rowHtml = (name, col, bet, x, win, me) => `<div class="avx-row${win ? ' won' : ''}${me ? ' me' : ''}"><span class="p"><i style="background:${col}"></i>${esc(name)}</span><span>${this.num(bet)}</span><span class="x">${x ? x.toFixed(2) + 'x' : ''}</span><span class="w">${win ? this.num(win) : ''}</span></div>`;
    const botRows = () => bots.map(b => rowHtml(b.name, b.col, b.bet, b.done, b.done ? b.bet * b.done : 0, false)).join('');
    const meRow = () => B.amt > 0 ? rowHtml('You', '#ff7a1a', B.amt, B.cashed ? B.at : 0, B.cashed ? B.amt * B.at : 0, true) : '';
    const drawRows = () => {
      const rows = $a('avx-rows');
      if (tab === 'all') { rows.innerHTML = meRow() + botRows(); $a('avx-n').textContent = (playersN + (B.amt > 0 ? 1 : 0)).toLocaleString(); $a('avx-tot').textContent = this.num(bots.reduce((a, b) => a + b.bet, 0) * 41 + (B.amt || 0)) + ' ' + this.cur(); }
      else if (tab === 'prev') rows.innerHTML = prevRows.join('') || '<div class="avx-empty">No previous round yet</div>';
      else rows.innerHTML = top.slice(0, 20).map(r => rowHtml(r.name, r.col, r.bet, r.x, r.bet * r.x, false)).join('') || '<div class="avx-empty">Nothing yet</div>';
    };
    /* ---------- bet button ---------- */
    const step = v => v < 10 ? 1 : v < 100 ? 10 : v < 1000 ? 100 : Math.pow(10, Math.floor(Math.log10(v)));
    const render = () => {
      const l1 = go.querySelector('.l1'), l2 = go.querySelector('.l2'); let cls = 'avx-go', a, b;
      if (ph === 'fly' && B.live && !B.cashed) { cls += ' cash'; a = 'CASH OUT'; b = this.num(B.amt * m) + ' ' + this.cur(); }
      else if (B.amt > 0 && !B.live && !B.cashed) { cls += ' cancel'; a = 'CANCEL'; b = ph === 'wait' ? 'Bet placed' : 'Waiting for next round'; }
      else { a = 'BET'; b = this.num(parseFloat(inp.value) || 0) + ' ' + this.cur(); }
      go.className = cls; l1.textContent = a; l2.textContent = b; const lock = B.amt > 0 && !B.cashed; inp.disabled = $a('avx-minus').disabled = $a('avx-plus').disabled = $a('avx-tier').disabled = lock;
    };
    const place = () => {
      const v = rd(parseFloat(inp.value)); if (!(v > 0)) return toast('Enter a bet', true); if (!App.take(v)) { $a('avx-ap').checked = false; return false; }
      B.amt = v; B.tier = tier; B.live = false; B.cashed = false; B.at = 0; drawRows(); render(); return true;
    };
    const cashOut = at => { if (!(B.live && !B.cashed)) return; const pay = payOf(B.tier, B.amt, rd(B.amt * at)); B.cashed = true; B.at = at; land = { tc: Math.min(t, S.tEnd), at, init: false }; App.pay('Aviator', B.amt, pay); toast('Cashed out ' + fmt(pay) + ' @ ' + at.toFixed(2) + 'x'); snd('win'); drawRows(); render(); };
    go.addEventListener('click', () => {
      if (ph === 'fly' && B.live && !B.cashed) return cashOut(m);
      if (B.amt > 0 && !B.live && !B.cashed) { App.S.balance = rd(App.S.balance + B.amt); App.S.wagered = rd(App.S.wagered - B.amt); B.amt = 0; App.updateBal(); drawRows(); return render(); }
      place();
    });
    $a('avx-minus').onclick = () => { const v = parseFloat(inp.value) || 0; inp.value = Math.max(1, rd(v - step(v))); render(); };
    $a('avx-plus').onclick = () => { const v = parseFloat(inp.value) || 0; inp.value = rd(v + step(v)); render(); };
    inp.addEventListener('input', render);
    const tierHint = () => { $a('avx-th').textContent = tier === 0 ? 'Easy: a bust hands back about half your stake, wins pay half the profit. Same 97% RTP.' : tier === 1 ? 'Normal: standard 97% RTP flights.' : Tier.hint('crash', tier); $a('avx-tier').classList.toggle('hot', tier >= 5); };
    $a('avx-tier').addEventListener('change', () => { tier = +$a('avx-tier').value; Tier.set('aviator', tier); tierHint(); if (ph === 'wait' && !(B.amt > 0)) { cp = nextCp(); S = buildScene(); } });
    $a('avx-ptabs').addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return; $$('#avx-ptabs button', el).forEach(x => x.classList.toggle('on', x === b)); $a('avx-autorow').style.display = b.dataset.m === 'auto' ? 'flex' : 'none'; });
    el.querySelector('.avx-quick').addEventListener('click', e => { const b = e.target.closest('button'); if (!b || inp.disabled) return; inp.value = b.dataset.q; render(); snd('tick'); });
    $a('avx-tabs').addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return; tab = b.dataset.t; $$('#avx-tabs button', el).forEach(x => x.classList.toggle('on', x === b)); drawRows(); });
    /* ---------- scene: carrier takeoff, missiles, tokens, landing ---------- */
    const RATE = this.RATE, EDGE = this.EDGE;
    const Dw = t => 180 * t + 5 * Math.pow(Math.min(t, 40), 2) + (t > 40 ? (t - 40) * 580 : 0);
    const geo = (w, h) => {
      const s = Math.max(.55, Math.min(1.1, w / 900)), seaY = h * .86, deckTop = seaY - 26 * s, y0 = deckTop - 16 * s, yHigh = h * .27, Lc = Math.min(w * .5, 430 * s), x0 = w * .17, x1 = w * .5;
      return { s, seaY, deckTop, y0, Lc, x0,
        px: t => x0 + (x1 - x0) * (1 - Math.exp(-t / 4)),
        py: t => { let y = y0 - (y0 - yHigh) * (1 - Math.exp(-t / 3.2)); if (t > 4) y += Math.sin(t * .8) * h * .05 * Math.min(1, (t - 4) / 3); return y; } };
    };
    const MS = [1.5, 2, 3, 5, 10, 20, 50, 100, 200, 500, 1000, 5000, 1e4, 1e5, 1e6, 1e7];
    const buildScene = () => {
      const tm = cp > 1 ? Math.log(cp) / RATE : 0, tEnd = Math.max(tm, 0.9), tokens = [], dec = []; let last = -9;
      MS.forEach(M => { const tt = Math.log(M) / RATE; if (M < cp * .97 && tt >= 1.2 && tt - last >= 1 && tt < tEnd - .4) { tokens.push({ M, t: tt }); last = tt; } });
      for (let tt = 2.6; tt < tEnd - 1.8 && dec.length < 400; tt += 2.6 + CM.rnd() * 3.2) dec.push({ tp: tt, dy: (CM.rnd() < .5 ? -1 : 1) * (50 + CM.rnd() * 50) });
      return { tEnd, tm, tokens, dec };
    };
    const nextCp = () => Admin.take('av' + tier, () => CM.crashTier(tier, EDGE), v => { const av = parseFloat($a('avx-av').value) || 0; return v >= ($a('avx-ac').checked && av > 1 ? av : 2); });
    cp = nextCp(); let S = buildScene(), land = null;
    const jet = (c, x, y, ang, tt, s, alpha, flame) => {
      c.save(); c.globalAlpha = alpha; c.translate(x, y); c.rotate(ang); c.scale(s, s);
      if (flame) { const L = 22 + 8 * Math.sin(tt * 60); const fg = c.createLinearGradient(-52, 0, -52 - L, 0); fg.addColorStop(0, '#fff'); fg.addColorStop(.4, '#ffb347'); fg.addColorStop(1, '#ff5a0000'); c.fillStyle = fg; c.beginPath(); c.moveTo(-50, -4); c.lineTo(-52 - L, 0); c.lineTo(-50, 4); c.fill(); }
      c.fillStyle = '#ff7a1a'; c.beginPath(); c.moveTo(-50, -6); c.lineTo(-62, -28); c.lineTo(-40, -28); c.lineTo(-22, -8); c.closePath(); c.fill();
      c.fillStyle = '#1f6fb8'; c.beginPath(); c.moveTo(-4, 3); c.lineTo(-26, 20); c.lineTo(-10, 20); c.lineTo(20, 4); c.closePath(); c.fill();
      const g = c.createLinearGradient(0, -9, 0, 9); g.addColorStop(0, '#ffffff'); g.addColorStop(1, '#c4d0e8'); c.fillStyle = g;
      c.beginPath(); c.moveTo(-52, -6); c.lineTo(20, -9); c.quadraticCurveTo(52, -6, 66, 2); c.quadraticCurveTo(40, 9, 10, 9); c.lineTo(-52, 6); c.closePath(); c.fill();
      c.fillStyle = '#ff7a1a'; c.fillRect(-34, -1, 54, 3);
      c.fillStyle = '#5bc0ff'; c.beginPath(); c.ellipse(26, -6, 13, 5, -.1, 0, 7); c.fill();
      c.fillStyle = '#2f8bff'; c.beginPath(); c.moveTo(0, 0); c.lineTo(-30, 22); c.lineTo(-12, 22); c.lineTo(26, 3); c.closePath(); c.fill();
      c.restore();
    };
    const missile = (c, x, y, s, tt) => {
      for (let i = 1; i <= 11; i++) { c.fillStyle = 'rgba(203,213,232,' + (.38 * (1 - i / 12)) + ')'; c.beginPath(); c.arc(x + 22 * s + i * 10 * s, y + Math.sin(tt * 18 + i) * 2, (3 + i * .8) * s, 0, 7); c.fill(); }
      c.save(); c.translate(x, y); c.scale(-s, s);
      const fl = 8 + 5 * Math.sin(tt * 70); c.fillStyle = '#ffb347'; c.beginPath(); c.moveTo(-26, -3); c.lineTo(-26 - fl, 0); c.lineTo(-26, 3); c.fill();
      c.fillStyle = '#2f8bff'; c.beginPath(); c.moveTo(-26, -4); c.lineTo(-36, -11); c.lineTo(-18, -4); c.fill(); c.beginPath(); c.moveTo(-26, 4); c.lineTo(-36, 11); c.lineTo(-18, 4); c.fill();
      c.fillStyle = '#f1f4fb'; c.fillRect(-26, -4, 44, 8); c.fillStyle = '#ff5a00'; c.beginPath(); c.moveTo(18, -4); c.lineTo(34, 0); c.lineTo(18, 4); c.fill(); c.fillStyle = '#ff7a1a'; c.fillRect(-4, -4, 5, 8);
      c.restore();
    };
