      `<div class="hist-pills" id="kn-sum" style="font-family:var(--fd);font-size:12px;color:var(--txt3)">Pick 1–10 numbers</div><div class="keno-grid" id="kn-grid">${Array.from({ length: 40 }, (_, i) => `<button class="kcell" data-n="${i + 1}">${i + 1}</button>`).join('')}</div><div class="paytable" id="kn-pt"></div>`);
    let picks = new Set(), tier = 1, busy = false; const kt = (n, t) => { const a = CM.kenoTable(n, CM.TIER_KEYS[CM.nat(t)]); return t === 6 ? a.map(v => v * 100) : a; }; const cells = $$('.kcell', root);
    const pt = (hits) => { const n = picks.size; if (!n) { $('#kn-pt', root).innerHTML = ''; return; } const t = kt(n, tier); $('#kn-pt', root).innerHTML = t.map((m, k) => `<div class="pt ${hits === k ? 'lit' : ''}"><div class="h">${k} hit${k === 1 ? '' : 's'}</div><div class="m">${m ? (m >= 1000 ? fk(m) + '×' : fx(m)) : '0×'}</div></div>`).join(''); $('#kn-sum', root).textContent = n + ' picked · RTP ' + (CM.kenoRtp(n, CM.TIER_KEYS[CM.nat(tier)]) * 100).toFixed(1) + '%'; };
