      const bet = UI.val(root); if (!App.take(bet)) return false; busy = true; clearMarks(); const draw = Admin.take('keno', CM.kenoDraw, d => { const h = d.filter(x => picks.has(x)).length, n = picks.size; return n > 0 && (CM.kenoTable(n, CM.TIER_KEYS[CM.nat(tier)])[h] || 0) >= 1; }), n = picks.size, tbl = CM.kenoTable(n, CM.TIER_KEYS[CM.nat(tier)]), u = Tier.u('keno'); let hits = 0;
      for (const d of draw) { await sleep(Settings.v.quick ? 12 : 95); const c = cells[d - 1]; if (picks.has(d)) { hits++; c.className = 'kcell hit'; snd('tick'); } else c.className = 'kcell drawn'; pt(hits); }
