    tier = Tier.bind(root, 'wof', t => (t >= 4 ? `${CM.TIER_NAMES[t]}: one winning segment paying ${fk(CM.WHEEL_F[t])}× its value, and the whole spin only pays 1 time in ${fk(CM.WHEEL_F[t])}.${t === 6 ? ' Insane × 100.' : ''}` : Tier.hint('gate', t)), t => { if (!busy) { tier = t; setup(); pk(); } }); ctx.peek(pk);
  }
