      `<div class="cards" id="hl-cur" style="min-height:110px"><div class="pc back" style="width:78px;height:110px"></div></div><div class="hint">Previous cards</div><div class="cards" id="hl-trail" style="min-height:70px"></div>`);
    let g = null, tier = 1; const go = $('#hl-go', root), hi = $('#hl-hi', root), lo = $('#hl-lo', root), sk = $('#hl-skip', root);
    const rank = c => c.r === 14 ? 1 : c.r;
    const pk = () => Admin.peek('hilo', CM.drawFresh, v => { if (!g) return 'Next starting card <b>' + cstr(v) + '</b>' + Tier.gateTxt('hilo', tier); const r0 = rank(g.card), r1 = rank(v); return 'Next card <b>' + cstr(v) + '</b> → ' + (r1 > r0 ? '<b>HIGHER</b> wins' : r1 < r0 ? '<b>LOWER</b> wins' : '<b>HIGHER and LOWER</b> both win (same rank)') + Tier.gateOf(g.u, g.tier); });
    const show = () => {
      $('#hl-cur', root).innerHTML = g ? UI.card(g.card).replace('class="pc', 'style="width:78px;height:110px;font-size:28px" class="pc') : '<div class="pc back" style="width:78px;height:110px"></div>';
      $('#hl-trail', root).innerHTML = g ? g.trail.map(c => UI.card(c, { sm: true })).join('') : '';
      if (g) { const r = rank(g.card); hi.textContent = `HIGHER ${fx(CM.hiloMult(r, 'hi'))}`; lo.textContent = `LOWER ${fx(CM.hiloMult(r, 'lo'))}`; $('#hl-m', root).textContent = g.mult.toFixed(2) + '×'; $('#hl-p', root).textContent = fmt(g.bet * g.mult * Tier.F(g.tier) - g.bet); go.textContent = g.rounds ? 'CASH OUT ' + fmt(g.bet * g.mult * Tier.F(g.tier)) + (g.tier >= 2 ? ' (gated)' : '') : 'PLAY — GUESS BELOW'; go.disabled = !g.rounds; }
    };
    const setBtns = on => { hi.disabled = lo.disabled = sk.disabled = !on; };
    const end = (win, pay) => { const s = g; g = null; setBtns(false); go.textContent = 'BET'; go.disabled = false; go.className = 'act'; UI.lock(root, false); const st = Tier.settle(s.tier, s.bet, pay, 0.99, s.u); pay = st.pay; App.pay('Hi-Lo', s.bet, pay); UI.res(root, pay > s.bet ? 'win' : pay > 0 ? 'push' : 'lose', win ? (pay > 0 ? `Cashed out ${(s.mult * Tier.F(s.tier)).toFixed(2)}× — won ${fmt(pay)}${st.note}` : `Cashed out, gate held — lost ${fmt(s.bet)}`) : (pay > 0 ? `Wrong guess — returned ${fmt(pay)}${st.note}` : `Wrong guess — lost ${fmt(s.bet)}`)); if (!win) snd('lose'); };
    const guess = dir => {
      const prev = g.card, r0 = rank(prev), next = Admin.take('hilo', CM.drawFresh), r1 = rank(next); const ok = dir === 'hi' ? r1 >= r0 : r1 <= r0;
      g.trail.push(prev); g.card = next; if (g.trail.length > 8) g.trail.shift();
