    sk.onclick = () => { g.trail.push(g.card); g.card = Admin.take('hilo', CM.drawFresh); if (g.trail.length > 8) g.trail.shift(); show(); pk(); };
    go.onclick = () => { if (g) { if (g.rounds) end(true, rd(g.bet * g.mult)); return; } const bet = UI.val(root); if (!App.take(bet)) return; UI.resClear(root); UI.lock(root, true); g = { bet, tier, u: Tier.u('hilo'), card: Admin.take('hilo', CM.drawFresh), trail: [], mult: 1, rounds: 0 }; go.className = 'act gold'; setBtns(true); show(); pk(); };
