    ctx.peek(pk);
    ctx.onClose(() => { if (g) { const s = g; g = null; App.pay('Hi-Lo', s.bet, Tier.settle(s.tier, s.bet, rd(s.bet * s.mult), 0.99, s.u).pay); } });
  }
