    const end = (win, pay) => { const s = g; g = null; $$('.tcell', root).forEach(b => { b.disabled = true; const r = +b.dataset.r, c = +b.dataset.c; if (r < s.layout.length && !b.classList.contains('gem') && !b.classList.contains('bomb')) { if (s.layout[r].includes(c)) { b.classList.add('bomb', 'dim'); b.textContent = '💣'; } else if (r <= s.level) { b.classList.add('dim'); } } }); go.textContent = 'BET'; go.disabled = false; go.className = 'act'; UI.lock(root, false); $$('.trow', root).forEach(r => r.classList.remove('cur')); const st = win ? Tier.settleNat(s.tier, pay, s.u) : { pay: 0, note: '' }; pay = st.pay; App.pay('Towers', s.bet, pay); pk(); UI.res(root, win && pay > 0 ? 'win' : 'lose', win ? (pay > 0 ? `Cashed out ${fk(CM.towersMult(mode, s.level) * (s.tier === 6 ? 100 : 1))}× — won ${fmt(pay)}${st.note}` : `Cashed out but the gate held — lost ${fmt(s.bet)}`) : `Bomb! Lost ${fmt(s.bet)}`); if (!win) snd('boom'); };
