/* ---------------------------------------------------------------- CUP CROSS */
Games.reg({
  id: 'roadcross', name: 'Cup Cross', cat: 'originals', sub: 'Cup Original', badge: 'NEW', icon: '🐔', grad: ['#0f4a3a', '#08150f'], rtp: '99%',
  rules: 'Hop lane by lane. Every hop survives with the odds shown; cash out any time. Multiplier = 99% ÷ (survival odds)^lanes.',
  mount(root, ctx) {
    const LANES = 14, PS = [0.92, 0.85, 0.75, 0.62, 0.45, 0.28];
    root.innerHTML = GM(UI.bet() + Tier.html('roadcross') + `<button class="act" id="rc-go">BET</button><button class="act gold" id="rc-cash" disabled data-keep>CASH OUT</button><div class="row2">${UI.stat('Next hop', '—', 'rc-n')}${UI.stat('Profit', fmt(0), 'rc-p', 'g')}</div>`,
      `<div class="rc-road" id="rc-road"></div><div class="hint" id="rc-desc" style="text-align:center;margin-top:8px"></div>`);
    let tier = 1, g = null, pos = 0; const go = $('#rc-go', root), cash = $('#rc-cash', root), road = $('#rc-road', root);
    const p = () => PS[CM.nat(tier)], K = () => tier === 6 ? 100 : 1, base = n => n <= 0 ? 1 : (1 - CM.EDGE) / Math.pow(p(), n), mult = n => base(n) * K();
    const lab = n => { const v = mult(n); return (v >= 1000 ? fk(v) : v >= 100 ? v.toFixed(0) : v.toFixed(2)) + '×'; };
    const build = () => {
      road.innerHTML = `<div class="rc-lane rc-start" data-i="0"><span class="rc-m">START</span><span class="rc-ch">🐔</span><span class="rc-car"></span></div>` + Array.from({ length: LANES }, (_, i) => `<div class="rc-lane" data-i="${i + 1}"><span class="rc-m">${lab(i + 1)}</span><span class="rc-ch"></span><span class="rc-car"></span></div>`).join('');
      $('#rc-desc', root).textContent = `${(p() * 100).toFixed(0)}% to survive each hop${tier === 6 ? ' · cash-out gated 1 in 100, pays ×100' : ''} · ${LANES} lanes`; paint();
    };
    const paint = () => { $$('.rc-lane', road).forEach(l => { const i = +l.dataset.i; l.classList.toggle('done', i < pos && i > 0); l.classList.toggle('here', i === pos); l.classList.toggle('next', !!g && i === pos + 1); const ch = $('.rc-ch', l); if (i === pos && !(g && g.dead)) ch.textContent = '🐔'; else if (i === 0 || i !== pos) { if (!(i === g?.deadAt && g.dead)) ch.textContent = ''; } }); const h = $('.rc-lane.here', road); if (h && h.scrollIntoView) h.scrollIntoView({ inline: 'center', block: 'nearest', behavior: Settings.v.quick ? 'auto' : 'smooth' }); };
    const gen = () => { let k = 0; const q = p(); while (k < LANES && CM.rnd() < q) k++; return k; };
    const pk = () => Admin.peek('rc' + tier, gen, v => { const d = g ? g.die : v; return (d >= LANES ? 'You can cross <b>all ' + LANES + ' lanes</b> safely' : 'You can safely hop <b>' + d + '</b> lane' + (d === 1 ? '' : 's') + ' — the car hits on lane <b>' + (d + 1) + '</b> (best cash-out ' + (d ? lab(d) : 'none') + ')') + (tier === 6 ? (g ? Tier.gateOf(g.u, 6).replace(/\(1 in [^)]*\)/, '(1 in 100)') : Tier.gateTxt('roadcross', 6, 100)) : ''); }, v => v >= 3);
    const upd = () => { if (!g) return; const m = mult(pos); $('#rc-n', root).textContent = pos < LANES ? lab(pos + 1) : '—'; $('#rc-p', root).textContent = fmt(g.bet * m - g.bet); cash.disabled = pos === 0; cash.textContent = pos ? 'CASH OUT ' + fmt(g.bet * m) + (tier === 6 ? ' (gated)' : '') : 'CASH OUT'; go.textContent = pos === 0 ? 'HOP ▶' : 'HOP AGAIN ▶'; };
    const end = win => {
      const s = g; g = null; UI.lock(root, false); cash.disabled = true; go.disabled = false; go.textContent = 'BET'; go.className = 'act';
      let pay = 0, note = ''; if (win) { const st = Tier.settleNat(s.tier, rd(s.bet * base(s.n)), s.u); pay = st.pay; note = st.note; }
      App.pay('Cup Cross', s.bet, pay); pos = win ? pos : pos; paint();
      UI.res(root, pay > s.bet ? 'win' : 'lose', win ? (pay > 0 ? `Crossed ${s.n} lane${s.n === 1 ? '' : 's'} — ${lab(s.n)} · won ${fmt(pay)}${note}` : `Cashed out but the gate held — lost ${fmt(s.bet)}`) : `Splat! A car got you on lane ${s.n + 1} — lost ${fmt(s.bet)}`); if (!win) snd('boom'); pk();
    };
    go.onclick = () => {
      if (!g) { const bet = UI.val(root); if (!App.take(bet)) return; UI.resClear(root); pos = 0; build(); g = { bet, tier, n: 0, die: Admin.take('rc' + tier, gen, v => v >= 3), u: Tier.u('roadcross'), dead: false }; UI.lock(root, true); go.className = 'act gold'; go.disabled = false; upd(); paint(); pk(); return; }
      if (g.dead) return;
      if (g.n >= g.die && g.n < LANES) { g.dead = true; g.deadAt = pos + 1; const l = $(`.rc-lane[data-i="${pos + 1}"]`, road); l.classList.add('hit'); $('.rc-car', l).textContent = '🚗💥'; $('.rc-ch', $(`.rc-lane[data-i="${pos}"]`, road)).textContent = ''; setTimeout(() => end(false), Settings.v.quick ? 50 : 500); g.n = pos; return; }
      pos++; g.n = pos; snd('tick'); const l = $(`.rc-lane[data-i="${pos}"]`, road); $('.rc-car', l).textContent = '🚗'; setTimeout(() => { if ($('.rc-car', l)) $('.rc-car', l).textContent = ''; }, 350);
      if (pos >= LANES) { return end(true); } upd(); paint(); pk();
    };
    cash.onclick = () => { if (g && g.n > 0 && !g.dead) end(true); };
    tier = Tier.bind(root, 'roadcross', t => (t === 6 ? 'Transcendent: Insane odds (28% per hop) ×100, cash-out gated 1 in 100.' : `${CM.TIER_NAMES[t]}: ${(PS[CM.nat(t)] * 100).toFixed(0)}% to survive each hop.`), t => { if (!g) { tier = t; pos = 0; build(); pk(); } else $('#tier-sel', root).value = tier; });
    build(); ctx.peek(pk);
    ctx.onClose(() => { if (g) { const s = g; g = null; App.pay('Cup Cross', s.bet, (s.n > 0 && !s.dead) ? Tier.settleNat(s.tier, rd(s.bet * base(s.n)), s.u).pay : 0); } });
  }
});

/* -------------------------------------------------------------- CUP SHUFFLE */
Games.reg({
  id: 'cupshuffle', name: 'Cup Shuffle', cat: 'originals', sub: 'Cup Original', badge: 'NEW', icon: '🥤', grad: ['#7a3a10', '#1a0c03'], rtp: '99%',
