      `<div class="cs-table" id="cs-table"></div><div class="hint" id="cs-hint" style="text-align:center;margin-top:8px">Place a bet and the cups will shuffle.</div>`);
    const slotOf = []; let n = 3, tier = 1, st = null; const go = $('#cs-go', root), tbl = $('#cs-table', root);
    const W = () => Math.min(92, Math.floor((tbl.clientWidth || 360) / n) - 8), pay = () => (1 - CM.EDGE) * n;
    const build = () => { if (slotOf.length !== n) { slotOf.length = 0; for (let i = 0; i < n; i++) slotOf.push(i); } tbl.style.height = '150px'; tbl.innerHTML = Array.from({ length: n }, (_, c) => `<button class="cs-cup" data-c="${c}" disabled><span class="cs-top">🥤</span><span class="cs-ball"></span></button>`).join(''); place(); $('#cs-hint', root).textContent = `Pick 1 of ${n} cups · wins pay ${pay().toFixed(2)}×${tier >= 2 ? ' × ' + fk(CM.TIER_F[tier]) + ' on a 1-in-' + fk(CM.TIER_F[tier]) + ' gate' : ''}`; };
    const place = () => { const w = W(), gap = ((tbl.clientWidth || 360) - w * n) / (n + 1); $$('.cs-cup', tbl).forEach((el, c) => { el.style.width = w + 'px'; el.style.left = (gap + slotOf[c] * (w + gap)) + 'px'; }); };
    const reset = () => { slotOf.length = 0; for (let i = 0; i < n; i++) slotOf.push(i); };
    const gen = () => CM.rint(n);
    const pk = () => Admin.peek('cs' + n, gen, v => 'The ball ends under the cup in position <b>' + (v + 1) + '</b> (left to right)' + (st ? '' : Tier.gateTxt('cupshuffle', tier)));
    const swap = async (a, b) => { const ca = slotOf.indexOf(a), cb = slotOf.indexOf(b); [slotOf[ca], slotOf[cb]] = [slotOf[cb], slotOf[ca]]; place(); await sleep(Settings.v.quick ? 30 : 330); };
    const run = async () => {
      if (st) return false; const bet = UI.val(root); if (!App.take(bet)) return false; UI.resClear(root); reset(); build();
      const w = Admin.take('cs' + n, gen), u = Tier.u('cupshuffle'); st = { bet, n, tier, w, u, picked: false }; UI.lock(root, true); go.disabled = true;
      const cups = $$('.cs-cup', tbl), c0 = CM.rint(n); const ball = $('.cs-ball', cups[c0]); ball.textContent = '🔴'; cups[c0].classList.add('lift'); await sleep(Settings.v.quick ? 80 : 900); cups[c0].classList.remove('lift'); ball.textContent = '';
      const K = Settings.v.quick ? 3 : 9 + CM.rint(4); for (let i = 0; i < K; i++) { let a = CM.rint(n), b = CM.rint(n); if (a === b) b = (a + 1) % n; await swap(a, b); }
      const bs = slotOf[c0]; if (bs !== w) await swap(bs, w);
      st.ballCup = c0; $('#cs-hint', root).textContent = 'Pick a cup!'; cups.forEach(e => e.disabled = false); pk();
    };
    tbl.addEventListener('click', e => {
      const el = e.target.closest('.cs-cup'); if (!el || el.disabled || !st || st.picked) return; st.picked = true; const c = +el.dataset.c, slot = slotOf[c], cups = $$('.cs-cup', tbl);
      cups.forEach(x => x.disabled = true); const win = slot === st.w; $('.cs-ball', cups[st.ballCup]).textContent = '🔴'; cups[st.ballCup].classList.add('lift'); el.classList.add(win ? 'good' : 'bad');
      const base = win ? rd(st.bet * pay()) : 0, s2 = Tier.settle(st.tier, st.bet, base, 0.99, st.u), p = s2.pay; App.pay('Cup Shuffle', st.bet, p);
      UI.res(root, p > st.bet ? 'win' : p > 0 ? 'push' : 'lose', win ? (p > 0 ? `Found it! ${fmt(p)} back${s2.note}` : `Right cup, but the gate held — lost ${fmt(st.bet)}`) : `Wrong cup — lost ${fmt(st.bet)}${st.tier === 0 && p > 0 ? ' (easy cushion: ' + fmt(p) + ' back)' : ''}`);
      st = null; UI.lock(root, false); go.disabled = false; pk(); if (win) snd('win');
    });
    go.onclick = run; UI.bindAuto(root, async () => { const ok = await run(); if (ok === false) return false; await new Promise(r => { const t = setInterval(() => { if (!st) { clearInterval(t); r(); } else { const c = $$('.cs-cup', tbl).find(x => !x.disabled); if (c) c.click(); } }, 120); }); return true; });
    UI.bindSeg(root, 'cs-n', v => { if (!st) { n = +v; build(); pk(); } });
    tier = Tier.bind(root, 'cupshuffle', 'gate', t => { if (!st) { tier = t; build(); pk(); } else $('#tier-sel', root).value = tier; });
    build(); ctx.peek(pk);
    ctx.onClose(() => { if (st) { const s = st; st = null; App.pay('Cup Shuffle', s.bet, 0); } });
  }
});

/* ------------------------------------------------------- ROCK PAPER SCISSORS */
Games.reg({
  id: 'rps', name: 'Rock Paper Scissors', cat: 'originals', sub: 'Cup Original', badge: 'NEW', icon: '✂️', grad: ['#0b3a8f', '#04080f'], rtp: '99%',
  rules: 'Beat the house hand: win pays 1.97×, a tie returns your stake, a loss pays nothing.',
  mount(root, ctx) {
    const H = ['🪨', '📄', '✂️'], NM = ['Rock', 'Paper', 'Scissors'], beats = (a, b) => (a - b + 3) % 3 === 1; // paper(1) beats rock(0)
    root.innerHTML = GM(UI.bet() + Tier.html('rps') + `<div class="lbl"><span>Your hand</span></div>` + UI.seg('rp-h', [[0, '🪨 Rock'], [1, '📄 Paper'], [2, '✂️ Scissors']], 0) + `<button class="act" id="rp-go">PLAY</button>` + UI.auto(),
      `<div class="rp-arena"><div class="rp-side"><div class="rp-hand" id="rp-me">🪨</div><div class="hint">You</div></div><div class="rp-vs">VS</div><div class="rp-side"><div class="rp-hand" id="rp-hs">❔</div><div class="hint">House</div></div></div>`);
    let tier = 1, busy = false; const go = $('#rp-go', root), me = () => +UI.segVal(root, 'rp-h');
    const gen = () => CM.rint(3), PAY = 3 * (1 - CM.EDGE) - 1; // win 1.97×, tie refunds: (1.97+1)/3 = 0.99 RTP
    const outcome = (a, b) => a === b ? 'tie' : beats(a, b) ? 'win' : 'lose';
    const pk = () => Admin.peek('rps', gen, v => 'House throws <b>' + NM[v] + '</b> → your ' + NM[me()] + ' <b>' + ({ win: 'WINS', lose: 'LOSES', tie: 'TIES' })[outcome(me(), v)] + '</b>' + Tier.gateTxt('rps', tier), v => beats(me(), v));
    UI.bindSeg(root, 'rp-h', v => { $('#rp-me', root).textContent = H[+v]; pk(); });
    const run = async () => {
      if (busy) return false; const bet = UI.val(root); if (!App.take(bet)) return false; busy = true; UI.resClear(root); UI.lock(root, true);
      const mine = me(), hs = Admin.take('rps', gen, v => beats(mine, v)), u = Tier.u('rps'), e = $('#rp-hs', root), m = $('#rp-me', root); m.textContent = H[mine]; e.classList.add('shake'); m.classList.add('shake');
      for (let i = 0; i < (Settings.v.quick ? 2 : 10); i++) { e.textContent = H[CM.rint(3)]; await sleep(Settings.v.quick ? 20 : 90); }
      e.classList.remove('shake'); m.classList.remove('shake'); e.textContent = H[hs]; const o = outcome(mine, hs); let p = 0, note = '';
      if (o === 'tie') p = bet; else if (o === 'win') { const s2 = Tier.settle(tier, bet, rd(bet * PAY), 0.99, u); p = s2.pay; note = s2.note; } else p = tier === 0 ? Tier.settle(0, bet, 0, 0.99, u).pay : 0;
      App.pay('Rock Paper Scissors', bet, p); busy = false; UI.lock(root, false);
      UI.res(root, p > bet ? 'win' : p === bet || (p > 0 && o !== 'win') ? 'push' : 'lose', o === 'tie' ? `Tie — stake returned (${fmt(bet)})` : o === 'win' ? (p > 0 ? `${NM[mine]} beats ${NM[hs]} — ${fmt(p)}${note}` : `You won the hand but the gate held — lost ${fmt(bet)}`) : `${NM[hs]} beats ${NM[mine]} — ${p > 0 ? fmt(p) + ' back (easy cushion)' : 'lost ' + fmt(bet)}`); pk(); return true;
    };
    go.onclick = run; UI.bindAuto(root, run);
    tier = Tier.bind(root, 'rps', 'gate', t => { tier = t; pk(); }); ctx.peek(pk);
  }
});

/* ------------------------------------------------------------------- DARTS */
Games.reg({
  id: 'darts', name: 'Cup Darts', cat: 'originals', sub: 'Cup Original', badge: 'NEW', icon: '🎯', grad: ['#7a1f1f', '#14080a'], rtp: '99%',
  rules: 'Throw a dart. Outer rings pay little or nothing, the bullseye pays 24×. 99% RTP.',
  mount(root, ctx) {
    const Z = [{ m: 0, p: .50, r0: 128, r1: 150, c: '#1a1f33' }, { m: .5, p: .26, r0: 100, r1: 128, c: '#1f6fb8' }, { m: 1.5, p: .16, r0: 72, r1: 100, c: '#2f8bff' }, { m: 4, p: .05, r0: 46, r1: 72, c: '#ffb36b' }, { m: 12, p: .025, r0: 22, r1: 46, c: '#ff7a1a' }, { m: 24, p: .005, r0: 0, r1: 22, c: '#ff3b30' }];
    const rtp = Z.reduce((a, z) => a + z.m * z.p, 0); // = 0.99
    root.innerHTML = GM(UI.bet() + Tier.html('darts') + `<button class="act" id="dt-go">THROW</button>` + UI.auto() + `<div class="hint">Rings: ${Z.slice(1).map(z => z.m + '×').join(' · ')}</div>`,
      `<div class="hist-pills" id="dt-hist"></div><svg id="dt-svg" viewBox="-160 -160 320 340" style="width:100%;max-width:380px;display:block;margin:6px auto"><circle r="156" fill="#0b1220" stroke="#2d4373" stroke-width="4"/>${Z.map(z => `<circle r="${z.r1}" fill="${z.c}" stroke="#0b1220" stroke-width="2"/>`).join('')}${Z.slice(1).map(z => `<text y="${-(z.r0 + z.r1) / 2 + 4}" text-anchor="middle" font-size="${z.m >= 12 ? 11 : 13}" font-weight="800" fill="#0a0f1e" font-family="Inter,sans-serif">${z.m}×</text>`).join('')}<g id="dt-dart" style="opacity:0"><polygon points="0,0 -4,-22 4,-22" fill="#e8eefc"/><rect x="-2" y="-52" width="4" height="30" fill="#ff7a1a"/><polygon points="0,-52 -9,-66 9,-66" fill="#2f8bff"/></g></svg>`);
    let tier = 1, busy = false; const go = $('#dt-go', root), dart = $('#dt-dart', root), hist = [];
    const gen = () => { let r = CM.rnd(), i = 0; for (; i < Z.length - 1; i++) { if (r < Z[i].p) break; r -= Z[i].p; } return i; };
    const pk = () => Admin.peek('dt', gen, v => 'Next dart lands in the <b>' + (Z[v].m ? Z[v].m + '×' : 'outer (miss)') + '</b> ring' + Tier.gateTxt('darts', tier), v => Z[v].m >= 1);
    const run = async () => {
      if (busy) return false; const bet = UI.val(root); if (!App.take(bet)) return false; busy = true; UI.resClear(root); UI.lock(root, true);
      const zi = Admin.take('dt', gen, v => Z[v].m >= 1), u = Tier.u('darts'), z = Z[zi], r = z.r0 + (z.r1 - z.r0) * Math.sqrt(CM.rnd()) * (zi === 0 ? .85 : .96), a = CM.rnd() * Math.PI * 2, x = Math.cos(a) * r, y = Math.sin(a) * r;
      dart.style.transition = 'none'; dart.style.opacity = '1'; dart.setAttribute('transform', `translate(${x * .2},${150}) rotate(${(x - 0) * .1}) scale(1.6)`); void dart.getBoundingClientRect();
      dart.style.transition = Settings.v.quick ? 'none' : 'transform .55s cubic-bezier(.2,.7,.2,1)'; dart.setAttribute('transform', `translate(${x},${y}) scale(1)`); await sleep(Settings.v.quick ? 20 : 650);
      const base = rd(bet * z.m), st = Tier.settle(tier, bet, base, 0.99, u), pay = st.pay; App.pay('Cup Darts', bet, pay); busy = false; UI.lock(root, false);
      hist.push({ c: pay >= bet ? 'w' : 'l', t: (z.m || 0) + '×' }); $('#dt-hist', root).innerHTML = UI.histPills(hist, 12);
      UI.res(root, pay > bet ? 'win' : pay > 0 ? 'push' : 'lose', pay > 0 ? `${z.m}× ring — ${pay >= bet ? 'won ' : 'back '}${fmt(pay)}${st.note}` : (z.m ? `${z.m}× ring but the gate held — lost ${fmt(bet)}` : `Miss — lost ${fmt(bet)}`)); pk(); return true;
    };
    go.onclick = run; UI.bindAuto(root, run); tier = Tier.bind(root, 'darts', 'gate', t => { tier = t; pk(); }); ctx.peek(pk);
  }
});

/* =====================================================================
   SLOTS UI — drives the engines in slots_math.js (CMS.GAMES)
   ===================================================================== */
const TXT_COL = { '10': '#7ad0ff', 'J': '#9ab8ff', 'Q': '#ffb27a', 'K': '#ffa24d', 'A': '#ff7a1a', '9': '#5b8cff' };
const slotInfo = (cfg, key) => {
  if (cfg.engine === 'tumble') return `<details class="hint" style="width:100%;max-width:720px;margin-top:10px"><summary style="cursor:pointer;color:var(--txt3);font-weight:700">Paytable &amp; rules</summary>
    <div style="margin:6px 0">Pays anywhere: 8+ matching symbols. Winning symbols vanish and new ones tumble in until no more wins. ${cfg.scatter.id} ×4+ = ${cfg.freeSpins} free spins (+${cfg.retrig} on 3+ scatters). ${cfg.bomb.id} multipliers (2×–100×) are added together and applied to the whole tumble win${cfg.persist ? '; in free spins they keep accumulating' : ' (free spins only)'}.</div>
    <div class="slot-info">${cfg.syms.slice().reverse().map(s => `<span class="pt"><div class="h">${s.id}</div><div class="m" style="font-size:10px">8+ ${fx(s.pay[0] * cfg.scale)}<br>10+ ${fx(s.pay[1] * cfg.scale)}<br>12+ ${fx(s.pay[2] * cfg.scale)}</div></span>`).join('')}</div></details>`;
  const f = (p) => fx(p * cfg.scale * 0.1);
  const feat = { expand: 'In free spins a random symbol is chosen to EXPAND over whole reels (3+ reels = pays on all lines).', multwild: 'Sun wilds on reels 2-4 carry 2×/3×/5× multipliers (up to 10× in free spins).', stack: 'Moon wilds can fill whole reels 2-4, much more often in free spins.', collect: 'In free spins the fisherman wild collects every fish value on screen; more catches raise the multiplier (up to 10×).' }[cfg.special];
  return `<details class="hint" style="width:100%;max-width:720px;margin-top:10px"><summary style="cursor:pointer;color:var(--txt3);font-weight:700">Paytable &amp; rules</summary>
    <div style="margin:6px 0">10 paylines, left to right. ${cfg.wild ? cfg.wild.id + ' is wild. ' : ''}${cfg.scatter.id} ×3+ = scatter pay and ${cfg.freeSpins} free spins. ${feat}</div>
    <div class="slot-info">${cfg.syms.slice().reverse().map(s => `<span class="pt"><div class="h">${/^[0-9AJQK]+$/.test(s.id) ? `<b style="color:${TXT_COL[s.id] || '#fff'}">${s.id}</b>` : s.id}</div><div class="m" style="font-size:10px">3× ${f(s.pay[2])}<br>4× ${f(s.pay[3])}<br>5× ${f(s.pay[4])}</div></span>`).join('')}</div></details>`;
};

function regSlot(key, o) {
  const cfg = CMS.GAMES[key];
  Games.reg(Object.assign({ id: key, name: cfg.name, cat: 'slots', sub: 'Cup Studio', rtp: '96%', rules: cfg.engine === 'tumble' ? '6×5 pays anywhere, tumbles & multipliers' : '5×3 · 10 lines · free spins' }, o, {
    mount(root, ctx) {
      const th = cfg.theme;
      const stage = cfg.engine === 'tumble'
        ? `<div class="slot-frame" style="background:${th.bg};border-color:${th.accent}55"><div class="slot-title" style="color:${th.accent}">${cfg.name.toUpperCase()}</div><div class="fs-banner" id="sl-fs" style="display:none;background:${th.accent}22;color:${th.accent}"></div><div class="tgrid" id="sl-grid" style="grid-template-columns:repeat(${cfg.cols},1fr);background:#0004">${Array.from({ length: cfg.cols * cfg.rows }, () => `<div class="tcell2" style="background:${th.cell}"></div>`).join('')}</div><div class="hint" id="sl-mult" style="text-align:center;font-family:var(--fd);font-size:14px;color:${th.accent};min-height:20px;margin-top:6px"></div></div>`
        : `<div class="slot-frame" style="background:${th.bg};border-color:${th.accent}55"><div class="slot-title" style="color:${th.accent}">${cfg.name.toUpperCase()}</div><div class="fs-banner" id="sl-fs" style="display:none;background:${th.accent}22;color:${th.accent}"></div><div class="lgrid" id="sl-grid" style="background:#0005">${Array.from({ length: 5 }, () => `<div class="lreel">${Array.from({ length: 3 }, () => `<div class="lcell" style="background:${th.accent}12"></div>`).join('')}</div>`).join('')}</div><div class="hint" id="sl-mult" style="text-align:center;font-size:12px;min-height:18px;margin-top:6px"></div></div>`;
      root.innerHTML = GM(UI.bet() + Tier.html('sl_' + key) + `<button class="act" id="sl-go" style="background:linear-gradient(135deg,${th.accent},${th.accent}99);color:#06080b">SPIN</button>` + UI.auto('Auto spin') + `${UI.stat('Last win', fmt(0), 'sl-last', 'g')}<div class="hint">RTP ≈ 96%. Win/loss messages show total return incl. free spins.</div>`, stage + slotInfo(cfg, key));
      const grid = $('#sl-grid', root), go = $('#sl-go', root), fsb = $('#sl-fs', root), multEl = $('#sl-mult', root); let busy = false, tier = 1;
      const W = (ms) => UI.wait(ms);
      const genS = () => cfg.engine === 'tumble' ? CMS.tumbleRound(cfg) : CMS.linesRound(cfg);
      const totalOf = r => r.total;
      const pk = () => Admin.peek('sl' + key, genS, r => { const t = totalOf(r), fs = r.free ? r.free.length : 0; return 'Next spin pays <b>' + (t > 0 ? t.toFixed(2) + '× your bet' : 'nothing') + '</b>' + (fs ? ' · <b>' + fs + ' free spins</b> triggered' : '') + (t >= 5 ? ' · big win' : '') + Tier.gateTxt('sl_' + key, tier); }, r => totalOf(r) > 0);
      /* ---- tumble rendering ---- */
      const tcells = cfg.engine === 'tumble' ? $$('.tcell2', grid) : [];
      const paintT = (g, dropCols) => g.forEach((c, i) => { const e = tcells[i]; e.className = 'tcell2' + (dropCols && dropCols.has(i % cfg.cols) ? ' drop' : ''); e.innerHTML = c.t === 'bomb' ? `${c.id}<span class="bv">${c.v}×</span>` : c.id; });
      const playTumble = async (sp, bet, running) => {
        let acc = 0; paintT(sp.steps[0].grid, new Set(Array.from({ length: cfg.cols }, (_, i) => i))); await W(420);
        for (let k = 0; k < sp.steps.length; k++) {
          const st = sp.steps[k]; if (!st.wins.length) break;
          const cells = new Set(); st.wins.forEach(w => w.cells.forEach(i => cells.add(i))); cells.forEach(i => tcells[i].classList.add('win'));
          acc += st.wins.reduce((a, w) => a + w.amount, 0); multEl.textContent = 'Win ' + fmt(rd((running + acc) * bet)); snd('tick'); await W(520);
          cells.forEach(i => { tcells[i].classList.remove('win'); tcells[i].classList.add('pop'); }); await W(280);
          const drop = new Set(); cells.forEach(i => drop.add(i % cfg.cols)); paintT(sp.steps[k + 1].grid, drop); await W(380);
        }
        if (sp.win > 0 && sp.mult > 0) {
          tcells.forEach((e, i) => { const c = sp.steps[sp.steps.length - 1].grid[i]; if (c.t === 'bomb') e.classList.add('win'); });
          multEl.textContent = `MULTIPLIERS +${sp.bombsum}${cfg.persist && sp.mult !== sp.bombsum ? ' (total ×' + sp.mult + ')' : ''}  →  ${fmt(rd((running + sp.total) * bet))}`; if (cfg.lightning) { grid.style.boxShadow = '0 0 60px ' + th.accent; setTimeout(() => grid.style.boxShadow = '', 500); } snd('win'); await W(900);
        }
        return sp.total;
      };
      /* ---- line rendering ---- */
      const lreels = cfg.engine === 'lines' ? $$('.lreel', grid) : [];
      const cellEl = (r, y) => $$('.lcell', lreels[r])[y];
      const fill = (e, c, spinning) => { e.className = 'lcell' + (spinning ? ' spin' : '') + (/^[0-9AJQK]+$/.test(c.id) ? ' txt' : ''); e.style.color = TXT_COL[c.id] || ''; e.innerHTML = c.id + (c.cash ? `<span class="cv">${c.v}</span>` : '') + (c.m ? `<span class="wm">×${c.m}</span>` : ''); };
      const allSyms = () => cfg.syms.map(s => ({ id: s.id })).concat(cfg.wild ? [{ id: cfg.wild.id }] : [], [{ id: cfg.scatter.id }]);
      const playLines = async (g, ev, bet) => {
        const rnd = allSyms();
        for (let r = 0; r < 5; r++) for (let y = 0; y < 3; y++) fill(cellEl(r, y), CM.pick(rnd), true);
        const spinI = setInterval(() => { for (let r = 0; r < 5; r++) if (!lreels[r].dataset.stop) for (let y = 0; y < 3; y++) fill(cellEl(r, y), CM.pick(rnd), true); }, 70);
        lreels.forEach(x => delete x.dataset.stop);
        for (let r = 0; r < 5; r++) { await W(300 + r * 170); lreels[r].dataset.stop = 1; for (let y = 0; y < 3; y++) fill(cellEl(r, y), g[r][y], false); snd('tick'); }
        clearInterval(spinI);
        if (ev.total > 0 || ev.collect) {
          const hl = new Set(); ev.wins.forEach(w => { for (let r = 0; r < w.n; r++) hl.add(r + ',' + CMS.LINES[w.line][r]); });
          g.forEach((col, r) => col.forEach((c, y) => { if (c.scatter && ev.scatters >= 3) hl.add(r + ',' + y); if (ev.collect && (c.cash || c.wild)) hl.add(r + ',' + y); }));
          if (ev.expanded) ev.expanded.reels.forEach(r => [0, 1, 2].forEach(y => { hl.add(r + ',' + y); fill(cellEl(r, y), { id: ev.expanded.id }, false); }));
          hl.forEach(k => { const [r, y] = k.split(',').map(Number); cellEl(r, y).classList.add('win'); }); snd('win'); await W(850); hl.forEach(k => { const [r, y] = k.split(',').map(Number); cellEl(r, y).classList.remove('win'); });
        }
      };
      /* ---- one round ---- */
      const run = async () => {
        if (busy) return false; const bet = UI.val(root); if (!App.take(bet)) return false; busy = true; UI.resClear(root); fsb.style.display = 'none'; multEl.textContent = ''; go.disabled = true;
        let res, total = 0; const u = Tier.u('sl_' + key), rt = tier;
        if (cfg.engine === 'tumble') {
          res = Admin.take('sl' + key, genS, r => totalOf(r) > 0); total += await playTumble(res.base, bet, 0);
          if (res.scatterPay) { multEl.textContent = `SCATTER PAYS ${fmt(rd(res.scatterPay * bet))}`; total += res.scatterPay; await W(900); }
          if (res.free.length) {
            fsb.style.display = 'block'; fsb.textContent = `⭐ ${res.free.length >= 1 ? 'FREE SPINS' : ''} — ${cfg.freeSpins} spins awarded ⭐`; snd('big'); await W(1400);
            for (let i = 0; i < res.free.length; i++) { fsb.textContent = `FREE SPIN ${i + 1} / ${res.free.length}   ·   TOTAL ${fmt(rd(total * bet))}` + (cfg.persist ? `   ·   MULT ×${res.free[i].carry}` : ''); total += await playTumble(res.free[i], bet, total); }
          }
        } else {
          res = Admin.take('sl' + key, genS, r => totalOf(r) > 0); await playLines(res.base, res.ev, bet); total += res.ev.total;
          if (res.ev.collectPay) { multEl.textContent = `Fisherman collects fish — ${fmt(rd(res.ev.collectPay * bet))}`; total += res.ev.collectPay; await W(700); }
          if (res.free.length) {
            fsb.style.display = 'block'; fsb.textContent = `⭐ FREE SPINS — ${cfg.freeSpins} spins awarded ⭐`; snd('big');
            if (res.special) fsb.textContent += `   ·   Expanding symbol: ${res.special}`; await W(1700);
            for (let i = 0; i < res.free.length; i++) { const f = res.free[i]; fsb.textContent = `FREE SPIN ${i + 1} / ${res.free.length}   ·   TOTAL ${fmt(rd(total * bet))}` + (res.special ? `   ·   ${res.special} expands` : ''); await playLines(f.grid, f.ev, bet); total += f.total; if (f.ev.collectPay) { multEl.textContent = `Collect ×${f.ev.tier}: ${fmt(rd(f.ev.collectPay * bet))}`; await W(500); } }
          }
        }
        const st = Tier.settle(rt, bet, rd(total * bet), 0.96, u), pay = st.pay; App.pay('Slots · ' + cfg.name, bet, pay); $('#sl-last', root).textContent = fmt(pay); busy = false; go.disabled = false;
        UI.res(root, pay > bet ? 'win' : pay > 0 ? 'push' : 'lose', pay > 0 ? `${pay > bet ? 'Won' : 'Returned'} ${fmt(pay)} (${(pay / bet).toFixed(2)}×)${st.note}` : `${total > 0 ? 'Gate held — ' : 'No win — '}lost ${fmt(bet)}`); if (res.free && res.free.length) fsb.style.display = 'none'; pk(); return true;
      };
      go.onclick = run; UI.bindAuto(root, run); tier = Tier.bind(root, 'sl_' + key, 'gate', t => { if (!busy) { tier = t; pk(); } else $('#tier-sel', root).value = tier; }); ctx.peek(pk);
      if (cfg.engine === 'tumble') paintT(Array.from({ length: cfg.cols * cfg.rows }, () => ({ t: 'sym', id: CM.pick(cfg.syms).id })), null);
      else { const rn = allSyms(); for (let r = 0; r < 5; r++) for (let y = 0; y < 3; y++) fill(cellEl(r, y), CM.pick(rn), false); }
    }
  }));
}
regSlot('slots_candy', { badge: 'HOT', icon: '🍭', grad: ['#7a1f8f', '#2a0a3f'] });
regSlot('slots_olympus', { icon: '⚡', grad: ['#1c2a8f', '#0a0a30'], badge: 'HOT' });
regSlot('slots_fish', { icon: '🎣', grad: ['#0d5a86', '#04182a'] });
regSlot('slots_egypt', { icon: '📖', grad: ['#7a5a10', '#201505'], badge: 'NEW' });
regSlot('slots_wolf', { icon: '🐺', grad: ['#1c6a2a', '#06180a'] });
regSlot('slots_aztec', { icon: '🗿', grad: ['#8a4a10', '#241005'], badge: 'NEW' });

/* =====================================================================
   TABLE GAMES 1 — Blackjack, Baccarat, Dragon Tiger, 3-Card Poker, Casino Hold'em
   ===================================================================== */
const fs = n => n >= 1e12 ? (n / 1e12).toFixed(1) + 'T' : n >= 1e9 ? (n / 1e9).toFixed(1) + 'B' : n >= 1e6 ? (n / 1e6).toFixed(1) + 'M' : n >= 1e4 ? (n / 1e3).toFixed(1) + 'K' : (n % 1 ? n.toFixed(2) : String(n));
// multi-bet helper: chips on named areas
function betMap(root, onChange) {
  const B = { m: {}, h: [], last: null };
  B.add = (k, a) => { B.m[k] = rd((B.m[k] || 0) + a); B.h.push([k, a]); B.paint(); };
  B.undo = () => { const x = B.h.pop(); if (!x) return; B.m[x[0]] = rd(B.m[x[0]] - x[1]); if (B.m[x[0]] <= 0) delete B.m[x[0]]; B.paint(); };
  B.clear = () => { B.m = {}; B.h = []; B.paint(); };
  B.total = () => rd(Object.values(B.m).reduce((a, b) => a + b, 0));
  B.restore = () => { if (!B.last) return; B.m = Object.assign({}, B.last); B.h = Object.entries(B.last); B.paint(); };
  B.paint = () => { $$('[data-bet]', root).forEach(e => { const v = B.m[e.dataset.bet]; let c = e.querySelector('.chipbadge'); if (v) { if (!c) { c = document.createElement('span'); c.className = 'chipbadge'; e.appendChild(c); } c.textContent = fs(v); } else if (c) c.remove(); }); if (onChange) onChange(); };
  return B;
}
const betTools = `<div class="row2"><button class="act ghost" data-t="undo" data-keep style="padding:9px;font-size:14px">UNDO</button><button class="act ghost" data-t="clear" data-keep style="padding:9px;font-size:14px">CLEAR</button></div><button class="act ghost" data-t="rebet" data-keep style="padding:9px;font-size:14px">REBET LAST</button>`;
function bindTools(root, B) { root.addEventListener('click', e => { const t = e.target.closest('[data-t]'); if (!t) return; if (t.dataset.t === 'undo') B.undo(); if (t.dataset.t === 'clear') B.clear(); if (t.dataset.t === 'rebet') B.restore(); }); }
const shoes = {};
const getShoe = (k, d) => shoes[k] || (shoes[k] = CM.Shoe(d, 0.3));

/* ------------------------------------------------------------ BLACKJACK */
Games.reg({
  id: 'blackjack', name: 'Blackjack', cat: 'tables', sub: '6 decks · 3:2', badge: 'LIVE', icon: '🂡', grad: ['#0f5a2c', '#06200f'], rtp: '99.4%*',
  rules: '6 decks, dealer stands on all 17s, BJ pays 3:2, double any 2 cards, split up to 4 hands, split aces get 1 card, insurance 2:1. *with basic strategy',
  mount(root, ctx) {
    root.innerHTML = GM(
      UI.bet('bet', 'Main bet') + `<div class="lbl"><span>Perfect Pairs</span><b>5/12/25 : 1</b></div><div class="inp-wrap"><span class="cur">${esc(Settings.v.cur)}</span><input id="bj-pp" type="number" min="0" value="0"></div>
      <div class="lbl"><span>21+3</span><b>5–100 : 1</b></div><div class="inp-wrap"><span class="cur">${esc(Settings.v.cur)}</span><input id="bj-213" type="number" min="0" value="0"></div>
      <button class="act" id="bj-deal">DEAL</button><div class="row2"><button class="act ghost" id="bj-hit" disabled data-keep>HIT</button><button class="act ghost" id="bj-stand" disabled data-keep>STAND</button></div><div class="row2"><button class="act ghost" id="bj-dbl" disabled data-keep>DOUBLE</button><button class="act ghost" id="bj-split" disabled data-keep>SPLIT</button></div>`,
      `<div class="felt" style="text-align:center"><div class="felt-lbl">Dealer</div><div class="cards" id="bj-d"></div><div id="bj-ds"></div><div style="height:14px"></div><div class="felt-lbl">Player</div><div id="bj-hands" style="min-height:110px"></div></div><div class="hint" id="bj-msg" style="margin-top:8px;text-align:center;min-height:18px"></div>
      <div id="bj-ins" style="display:none;gap:10px;margin-top:8px"><button class="act gold" id="bj-ins-y" style="width:auto;padding:8px 18px;font-size:14px">TAKE INSURANCE</button><button class="act ghost" id="bj-ins-n" style="width:auto;padding:8px 18px;font-size:14px">NO THANKS</button></div>`);
    const shoe = getShoe('bj', 6); let g = null; const $b = id => $('#' + id, root);
    const pk = () => {
      if (!Admin.active()) { Admin.clear(); return; }
      if (!g && shoe.needsShuffle()) shoe.shuffle();
      const nx = shoe.cards.slice(-8).reverse().map(cstr);
      if (g && !g.over) Admin.show('Dealer hole card <b>' + cstr(g.dealer[1]) + '</b> · next cards from the shoe: <b>' + nx.slice(0, 6).join(' ') + '</b>');
      else if (!g) Admin.show('Next deal → you: <b>' + nx[0] + ' ' + nx[1] + '</b> · dealer shows <b>' + nx[2] + '</b>, hole <b>' + nx[3] + '</b> · then hits: <b>' + nx.slice(4, 8).join(' ') + '</b>');
    };
    const btn = { hit: $b('bj-hit'), stand: $b('bj-stand'), dbl: $b('bj-dbl'), split: $b('bj-split'), deal: $b('bj-deal') };
    const render = (hideHole) => {
      $b('bj-d').innerHTML = g.dealer.map((c, i) => i === 1 && hideHole ? UI.card(c, { back: true }) : UI.card(c)).join('');
      $b('bj-ds').innerHTML = `<span class="score-tag">${hideHole ? CM.bjVal(g.dealer[0].r) === 11 ? 'A' : CM.bjVal(g.dealer[0].r) : CM.bjTotal(g.dealer).v}</span>`;
      $b('bj-hands').innerHTML = g.hands.map((h, i) => { const t = CM.bjTotal(h.cards); return `<div class="hand-box ${i === g.cur && !g.over ? 'act' : ''}"><div class="cards" style="min-height:84px;margin:0">${h.cards.map(c => UI.card(c)).join('')}</div><span class="score-tag">${t.v}${t.soft && t.v < 21 ? ' soft' : ''}</span> <span class="hint">bet ${fmt(h.bet)}${h.res ? ' · ' + h.res : ''}</span></div>`; }).join('');
    };
    const setBtns = () => { const h = g && !g.over ? g.hands[g.cur] : null; const can = !!h && !g.insPending; btn.hit.disabled = btn.stand.disabled = !can; btn.dbl.disabled = !(can && h.cards.length === 2 && !h.noMore && h.bet <= App.S.balance); btn.split.disabled = !(can && h.cards.length === 2 && !h.noMore && g.hands.length < 4 && CM.bjVal(h.cards[0].r) === CM.bjVal(h.cards[1].r) && h.bet <= App.S.balance); btn.deal.disabled = !!g && !g.over; };
    const finishRound = async () => {
      g.over = true; g.cur = -1; const live = g.hands.some(h => CM.bjTotal(h.cards).v <= 21 && !(h.bj && g.hands.length === 1));
      render(false); await UI.wait(400);
      if (live) while (CM.bjTotal(g.dealer).v < 17) { g.dealer.push(shoe.draw()); render(false); await UI.wait(500); }
      const dv = CM.bjTotal(g.dealer).v, dBJ = CM.bjIsBJ(g.dealer); let pay = g.sidePay + g.insPay; const parts = [];
      g.hands.forEach(h => { const pv = CM.bjTotal(h.cards).v; let r = 0, t;
        if (pv > 21) { t = 'bust'; } else if (h.bj && !dBJ) { r = h.bet * 2.5; t = 'blackjack 3:2'; } else if (dBJ && !h.bj) { t = 'lose'; } else if (h.bj && dBJ) { r = h.bet; t = 'push'; } else if (dv > 21 || pv > dv) { r = h.bet * 2; t = 'win'; } else if (pv === dv) { r = h.bet; t = 'push'; } else t = 'lose';
        h.res = t; pay += r; parts.push(t); });
      pay = rd(pay); render(false); App.pay('Blackjack', g.stake, pay);
      const net = pay - g.stake; UI.res(root, net > 0 ? 'win' : net === 0 ? 'push' : 'lose', net > 0 ? `Won ${fmt(net)} profit` : net === 0 ? 'Push — stake returned' : `Lost ${fmt(-net)}`); $b('bj-msg').textContent = (g.sideMsg || ''); g.over = true; setBtns(); UI.lock(root, false); setBtns(); g = null; btn.deal.disabled = false; pk();
    };
    const nextHand = async () => { while (g.cur < g.hands.length && (g.hands[g.cur].done)) g.cur++; if (g.cur >= g.hands.length) return finishRound(); const h = g.hands[g.cur]; if (h.cards.length === 1) { h.cards.push(shoe.draw()); if (h.aceSplit) { h.done = true; render(true); await UI.wait(300); return nextHand(); } } if (CM.bjTotal(h.cards).v >= 21) { h.done = true; render(true); await UI.wait(250); return nextHand(); } render(true); setBtns(); };
    btn.hit.onclick = () => { const h = g.hands[g.cur]; h.cards.push(shoe.draw()); h.noMore = true; snd('tick'); if (CM.bjTotal(h.cards).v >= 21) h.done = true; render(true); setBtns(); if (h.done) nextHand(); };
    btn.stand.onclick = () => { g.hands[g.cur].done = true; nextHand(); };
    btn.dbl.onclick = () => { const h = g.hands[g.cur]; if (!App.take(h.bet)) return; g.stake += h.bet; h.bet *= 2; h.cards.push(shoe.draw()); h.done = true; render(true); setBtns(); nextHand(); };
    btn.split.onclick = () => { const h = g.hands[g.cur]; if (!App.take(h.bet)) return; g.stake += h.bet; const aces = h.cards[0].r === 14; const c2 = h.cards.pop(); const nh = { cards: [c2], bet: h.bet, aceSplit: aces, split: true }; h.aceSplit = aces; h.split = true; g.hands.splice(g.cur + 1, 0, nh); h.cards.push(shoe.draw()); if (aces) { h.done = true; } render(true); setBtns(); if (aces) nextHand(); else if (CM.bjTotal(h.cards).v >= 21) { h.done = true; nextHand(); } };
    const peekAndPlay = async () => {
      const up = g.dealer[0], dBJ = CM.bjIsBJ(g.dealer), pBJ = g.hands[0].bj;
      if (CM.bjVal(up.r) >= 10 && dBJ) { g.insPay = g.insBet ? g.insBet * 3 : 0; render(false); g.hands[0].done = true; $b('bj-msg').textContent = 'Dealer has Blackjack'; return finishRound(); }
      if (g.insBet) $b('bj-msg').textContent = 'Dealer does not have Blackjack — insurance lost';
      if (pBJ) { g.hands[0].done = true; return finishRound(); }
      g.cur = 0; render(true); setBtns();
    };
    btn.deal.onclick = async () => {
      const bet = UI.val(root), pp = UI.val(root, 'bj-pp'), t3 = UI.val(root, 'bj-213'); const total = rd(bet + pp + t3); if (!(bet > 0)) return toast('Enter a bet', true); if (!App.take(total)) return;
      if (shoe.needsShuffle()) { shoe.shuffle(); toast('Shoe shuffled'); } UI.resClear(root); $b('bj-msg').textContent = ''; UI.lock(root, true); btn.deal.disabled = true;
      const P = [shoe.draw(), shoe.draw()], D = [shoe.draw(), shoe.draw()]; g = { dealer: D, hands: [{ cards: P, bet, bj: CM.bjIsBJ(P) }], cur: -1, stake: total, sidePay: 0, insPay: 0, insBet: 0, over: false, sideMsg: '' };
      if (pp > 0) { const r = CM.perfectPairs(P[0], P[1]); if (r) { g.sidePay += pp * (r[1] + 1); g.sideMsg += `${r[0]} ${r[1]}:1! `; } }
      if (t3 > 0) { const r = CM.t213([P[0], P[1], D[0]]); if (r) { g.sidePay += t3 * (r[1] + 1); g.sideMsg += `21+3 ${r[0]} ${r[1]}:1! `; } }
      render(true); if (g.sideMsg) { $b('bj-msg').textContent = g.sideMsg; toast(g.sideMsg); }
      if (D[0].r === 14 && !g.hands[0].bj) { g.insPending = true; $b('bj-ins').style.display = 'flex'; setBtns(); return; }
      if (D[0].r === 14) { g.insPending = true; $b('bj-ins').style.display = 'flex'; setBtns(); return; }
      await peekAndPlay();
    };
    const insDone = async take => { $b('bj-ins').style.display = 'none'; if (take) { const ib = rd(g.hands[0].bet / 2); if (App.take(ib)) { g.insBet = ib; g.stake += ib; } } g.insPending = false; await peekAndPlay(); };
    $b('bj-ins-y').onclick = () => insDone(true); $b('bj-ins-n').onclick = () => insDone(false);
    ctx.peek(pk);
    ctx.onClose(() => { if (g && !g.over) { const s = g; g = null; App.pay('Blackjack', s.stake, 0); } });
  }
});

/* ------------------------------------------------------------- BACCARAT */
Games.reg({
  id: 'baccarat', name: 'Baccarat', cat: 'tables', sub: '8 decks · punto banco', badge: 'LIVE', icon: '🎴', grad: ['#4a1c7a', '#12082a'], rtp: '98.8%',
  rules: 'Player 1:1 · Banker 0.95:1 (5% commission) · Tie 8:1 · Pairs 11:1. Full third-card rules.',
  mount(root, ctx) {
    root.innerHTML = GM(UI.bet('bet', 'Chip value') + `<div class="hint">Click areas to place chips. Total: <b id="bc-tot" style="color:var(--acc)">${fmt(0)}</b></div><button class="act" id="bc-go">DEAL</button>` + betTools,
      `<div class="felt purple" style="text-align:center"><div style="display:flex;justify-content:space-around"><div><div class="felt-lbl">Player</div><div class="cards" id="bc-p" style="min-height:90px"></div><span class="score-tag" id="bc-ps">–</span></div><div><div class="felt-lbl">Banker</div><div class="cards" id="bc-b" style="min-height:90px"></div><span class="score-tag" id="bc-bs">–</span></div></div></div>
       <div class="areas" style="grid-template-columns:repeat(3,1fr);margin-top:12px"><div class="area p" data-bet="player">PLAYER<div class="o">1 : 1</div></div><div class="area t" data-bet="tie">TIE<div class="o">8 : 1</div></div><div class="area b" data-bet="banker">BANKER<div class="o">0.95 : 1</div></div></div>
       <div class="areas" style="grid-template-columns:repeat(2,1fr);margin-top:8px"><div class="area sm" data-bet="pairP">PLAYER PAIR<div class="o">11 : 1</div></div><div class="area sm" data-bet="pairB">BANKER PAIR<div class="o">11 : 1</div></div></div><div class="road" id="bc-road"></div>`);
    const shoe = getShoe('bac', 8), road = []; let busy = false;
    const clone = () => ({ cards: shoe.cards.slice(), draw() { return this.cards.pop(); } });
    const pk = () => { if (!Admin.active()) { Admin.clear(); return; } if (!busy && shoe.needsShuffle()) shoe.shuffle(); const r = CM.bacRound(clone()); Admin.show('<b>' + r.winner.toUpperCase() + '</b> wins · Player ' + r.pt + ' – Banker ' + r.bt + ' · P: ' + r.P.map(cstr).join(' ') + ' · B: ' + r.B.map(cstr).join(' ') + (r.pairP ? ' · player pair' : '') + (r.pairB ? ' · banker pair' : '')); }; const B = betMap(root, () => { $('#bc-tot', root).textContent = fmt(B.total()); }); bindTools(root, B);
    $$('[data-bet]', root).forEach(a => a.addEventListener('click', () => { if (busy) return; const v = UI.val(root); if (v > 0) { B.add(a.dataset.bet, v); snd('tick'); } }));
    $('#bc-go', root).onclick = async () => {
      if (busy) return; const tot = B.total(); if (!tot) return toast('Place a bet first', true); if (!App.take(tot)) return; busy = true; UI.resClear(root); UI.lock(root, true); $$('[data-bet]', root).forEach(a => a.classList.remove('win'));
      if (shoe.needsShuffle()) shoe.shuffle(); const r = CM.bacRound(shoe), bets = Object.assign({}, B.m); B.last = bets;
      const showP = n => $('#bc-p', root).innerHTML = r.P.slice(0, n).map(c => UI.card(c)).join(''), showB = n => $('#bc-b', root).innerHTML = r.B.slice(0, n).map(c => UI.card(c)).join('');
      $('#bc-ps', root).textContent = '–'; $('#bc-bs', root).textContent = '–';
      showP(1); await UI.wait(380); showB(1); await UI.wait(380); showP(2); await UI.wait(380); showB(2); await UI.wait(450);
      $('#bc-ps', root).textContent = CM.bacTotal(r.P.slice(0, 2)); $('#bc-bs', root).textContent = CM.bacTotal(r.B.slice(0, 2));
      if (r.P.length === 3) { await UI.wait(500); showP(3); $('#bc-ps', root).textContent = CM.bacTotal(r.P); }
      if (r.B.length === 3) { await UI.wait(500); showB(3); $('#bc-bs', root).textContent = CM.bacTotal(r.B); }
      let pay = 0; const won = [];
      for (const [k, a] of Object.entries(bets)) {
        let ret = 0;
        if (k === 'player') ret = r.winner === 'player' ? a * 2 : r.winner === 'tie' ? a : 0; else if (k === 'banker') ret = r.winner === 'banker' ? a * 1.95 : r.winner === 'tie' ? a : 0;
        else if (k === 'tie') ret = r.winner === 'tie' ? a * 9 : 0; else if (k === 'pairP') ret = r.pairP ? a * 12 : 0; else if (k === 'pairB') ret = r.pairB ? a * 12 : 0;
        if (ret > a) { won.push(k); } pay += ret;
      }
      pay = rd(pay); won.forEach(k => $(`[data-bet="${k}"]`, root).classList.add('win')); if (r.winner) $(`[data-bet="${r.winner}"]`, root).classList.add('win');
      App.pay('Baccarat', tot, pay); road.push(r.winner[0].toUpperCase()); $('#bc-road', root).innerHTML = road.slice(-30).map(x => `<i class="${x}">${x}</i>`).join('');
      const net = pay - tot; UI.res(root, net > 0 ? 'win' : net === 0 ? 'push' : 'lose', `${r.winner.toUpperCase()} wins ${r.pt}–${r.bt} · ${net > 0 ? 'won ' + fmt(net) : net === 0 ? 'push' : 'lost ' + fmt(-net)}`);
      busy = false; UI.lock(root, false); B.clear(); pk();
    };
    ctx.peek(pk);
    ctx.onClose(() => { });
  }
});

/* --------------------------------------------------------- DRAGON TIGER */
Games.reg({
  id: 'dragontigger', name: 'Dragon Tiger', cat: 'tables', sub: 'One card each', badge: 'LIVE', icon: '🐉', grad: ['#7a1020', '#20080c'], rtp: '96.3%',
  rules: 'Higher card wins (Ace low). Tie: Dragon/Tiger lose half the bet. Tie pays 11:1.',
  mount(root, ctx) {
    root.innerHTML = GM(UI.bet('bet', 'Chip value') + `<div class="hint">Total: <b id="dt-tot" style="color:var(--acc)">${fmt(0)}</b></div><button class="act" id="dt-go">DEAL</button>` + betTools,
      `<div class="felt red" style="text-align:center"><div style="display:flex;justify-content:space-around;align-items:center"><div><div class="felt-lbl">Dragon</div><div class="cards" id="dt-d" style="min-height:100px"></div></div><div style="font-family:var(--fh);font-size:40px;color:#fff8">VS</div><div><div class="felt-lbl">Tiger</div><div class="cards" id="dt-t" style="min-height:100px"></div></div></div></div>
      <div class="areas" style="grid-template-columns:repeat(3,1fr);margin-top:12px"><div class="area b" data-bet="dragon">DRAGON<div class="o">1 : 1</div></div><div class="area t" data-bet="tie">TIE<div class="o">11 : 1</div></div><div class="area p" data-bet="tiger">TIGER<div class="o">1 : 1</div></div></div><div class="road" id="dt-road"></div>`);
    const shoe = getShoe('dt', 8), road = []; let busy = false;
    const clone = () => ({ cards: shoe.cards.slice(), draw() { return this.cards.pop(); } });
    const pk = () => { if (!Admin.active()) { Admin.clear(); return; } if (!busy && shoe.needsShuffle()) shoe.shuffle(); const r = CM.dtRound(clone()); Admin.show('Dragon <b>' + cstr(r.d) + '</b> vs Tiger <b>' + cstr(r.t) + '</b> → <b>' + r.winner.toUpperCase() + '</b>' + (r.winner === 'tie' ? ' (Dragon/Tiger lose half)' : '')); }; const B = betMap(root, () => { $('#dt-tot', root).textContent = fmt(B.total()); }); bindTools(root, B);
    $$('[data-bet]', root).forEach(a => a.addEventListener('click', () => { if (busy) return; const v = UI.val(root); if (v > 0) { B.add(a.dataset.bet, v); snd('tick'); } }));
    $('#dt-go', root).onclick = async () => {
      if (busy) return; const tot = B.total(); if (!tot) return toast('Place a bet first', true); if (!App.take(tot)) return; busy = true; UI.lock(root, true); UI.resClear(root); $$('[data-bet]', root).forEach(a => a.classList.remove('win'));
      if (shoe.needsShuffle()) shoe.shuffle(); const r = CM.dtRound(shoe), bets = Object.assign({}, B.m); B.last = bets;
      $('#dt-d', root).innerHTML = ''; $('#dt-t', root).innerHTML = ''; await UI.wait(250); $('#dt-d', root).innerHTML = UI.card(r.d); await UI.wait(550); $('#dt-t', root).innerHTML = UI.card(r.t); await UI.wait(450);
      let pay = 0; for (const [k, a] of Object.entries(bets)) { if (k === 'tie') pay += r.winner === 'tie' ? a * 12 : 0; else if (r.winner === 'tie') pay += a * 0.5; else pay += r.winner === k ? a * 2 : 0; }
      pay = rd(pay); $(`[data-bet="${r.winner}"]`, root).classList.add('win'); App.pay('Dragon Tiger', tot, pay); road.push(r.winner === 'dragon' ? 'B' : r.winner === 'tiger' ? 'P' : 'T'); $('#dt-road', root).innerHTML = road.slice(-30).map(x => `<i class="${x}">${x === 'B' ? 'D' : x === 'P' ? 'T' : 'T'}</i>`).join('');
      const net = pay - tot; UI.res(root, net > 0 ? 'win' : net === 0 ? 'push' : 'lose', `${r.winner.toUpperCase()} · ${net > 0 ? 'won ' + fmt(net) : net === 0 ? 'push' : 'lost ' + fmt(-net)}`); busy = false; UI.lock(root, false); B.clear(); pk();
    };
    ctx.peek(pk);
  }
});

/* ------------------------------------------------------ THREE CARD POKER */
Games.reg({
  id: 'threecard', name: 'Three Card Poker', cat: 'tables', sub: 'Ante / Play / Pair Plus', badge: 'NEW', icon: '♠️', grad: ['#0f4a5a', '#06161f'], rtp: '96.6%',
  rules: 'Dealer qualifies with Q-high. Ante bonus: straight 1:1, trips 4:1, SF 5:1. Pair Plus: pair 1, flush 4, straight 6, trips 30, SF 40.',
  mount(root, ctx) {
    root.innerHTML = GM(UI.bet('bet', 'Ante') + `<div class="lbl"><span>Pair Plus</span></div><div class="inp-wrap"><span class="cur">${esc(Settings.v.cur)}</span><input id="tc-pp" type="number" min="0" value="0"></div>
      <button class="act" id="tc-deal">DEAL</button><div class="row2"><button class="act gold" id="tc-play" disabled data-keep>PLAY (1× ante)</button><button class="act red" id="tc-fold" disabled data-keep>FOLD</button></div>`,
      `<div class="felt blue" style="text-align:center"><div class="felt-lbl">Dealer</div><div class="cards" id="tc-d"></div><div id="tc-dr"></div><div style="height:12px"></div><div class="felt-lbl">Player</div><div class="cards" id="tc-p"></div><div id="tc-pr"></div></div>`);
    let g = null; const deal = $('#tc-deal', root), play = $('#tc-play', root), fold = $('#tc-fold', root);
    const dk = () => CM.shuffle(CM.newDeck(1));
    const pk = () => Admin.peek('tc', dk, d => { const P = g ? g.P : d.slice(0, 3), D = g ? g.D : d.slice(3, 6), ph = CM.eval3(P), dh = CM.eval3(D), q = CM.tcQualifies(dh), c = CM.cmpHand(ph, dh); const v = !q ? 'dealer does not qualify → <b>PLAY</b> (ante pays)' : c > 0 ? 'you beat the dealer → <b>PLAY</b>' : c === 0 ? 'tie → play pushes' : 'dealer wins → <b>FOLD</b>'; return (g ? 'This hand: ' : 'Next hand: ') + 'you ' + P.map(cstr).join(' ') + ' (' + CM.TC_NAMES[ph[0]] + ') · dealer <b>' + D.map(cstr).join(' ') + '</b> (' + CM.TC_NAMES[dh[0]] + ') → ' + v; });
    const settle = async (didPlay) => {
