      else {
        if (!App.take(g.ante)) { /* cannot cover play bet: force */ } g.stake += g.ante; $('#tc-d', root).innerHTML = g.D.map(c => UI.card(c)).join(''); await UI.wait(500);
        const ph = CM.eval3(g.P), dh = CM.eval3(g.D), q = CM.tcQualifies(dh), bonus = CM.TC_ANTEBONUS[ph[0]] || 0; $('#tc-dr', root).innerHTML = `<span class="score-tag">${CM.TC_NAMES[dh[0]]}${q ? '' : ' · does not qualify'}</span>`;
        pay += bonus ? g.ante * bonus : 0;
        if (!q) { pay += g.ante * 2 + g.ante; msg = 'Dealer does not qualify — ante pays 1:1, play pushes'; }
        else { const c = CM.cmpHand(ph, dh); if (c > 0) { pay += g.ante * 2 + g.ante * 2; msg = 'You beat the dealer!'; } else if (c === 0) { pay += g.ante * 2; msg = 'Tie — ante and play push'; } else msg = 'Dealer wins'; }
        if (bonus) msg += ` · ante bonus ${bonus}:1`;
