      g = null; deal.disabled = false; UI.lock(root, false); pk();
    };
    deal.onclick = () => {
      const ante = UI.val(root), pp = UI.val(root, 'tc-pp'); if (!(ante > 0)) return toast('Enter an ante', true); if (ante * 2 + pp > App.S.balance + 1e-9) return toast('Keep enough balance for the play bet', true); if (!App.take(rd(ante + pp))) return;
      UI.resClear(root); UI.lock(root, true); const d = Admin.take('tc', dk); const P = d.slice(0, 3), D = d.slice(3, 6); g = { ante, pp, P, D, stake: rd(ante + pp), ppPay: 0, ppMsg: '' };
      const ph = CM.eval3(P); $('#tc-p', root).innerHTML = P.map(c => UI.card(c)).join(''); $('#tc-pr', root).innerHTML = `<span class="score-tag">${CM.TC_NAMES[ph[0]]}</span>`; $('#tc-d', root).innerHTML = D.map(() => UI.card(null, { back: true })).join(''); $('#tc-dr', root).innerHTML = '';
