/* ------------------------------------------------------ CASINO HOLD'EM */
Games.reg({
  id: 'poker', name: "Casino Hold'em", cat: 'tables', sub: 'Texas Hold\'em vs dealer', badge: 'LIVE', icon: '🂱', grad: ['#143a6b', '#070f1f'], rtp: '97.8%',
