    let g = null; const deal = $('#ph-deal', root), call = $('#ph-call', root), fold = $('#ph-fold', root);
    const name = h => CM.HAND_NAMES[h[0]];
    const genH = () => CM.shuffle(CM.newDeck(1));
    const pk = () => Admin.peek('ph', genH, d => { const P = g ? g.P : d.slice(0, 2), D = g ? g.D : d.slice(2, 4), B = g ? g.board.slice(0, 3).concat(g.deck.slice(0, 2)) : d.slice(4, 9); const ph = CM.best7([...P, ...B]), dh = CM.best7([...D, ...B]), dq = ph && (dh[0] >= 2 || (dh[0] === 1 && dh[1] >= 4)), c = CM.cmpHand(ph, dh); const v = !dq ? 'dealer does not qualify → <b>CALL</b>' : c > 0 ? 'you win → <b>CALL</b>' : c === 0 ? 'tie → push' : 'dealer wins → <b>FOLD</b>'; return (g ? 'This hand: ' : 'Next hand: ') + 'dealer <b>' + D.map(cstr).join(' ') + '</b> (' + name(dh) + ') · board ' + B.map(cstr).join(' ') + ' · you ' + name(ph) + ' → ' + v; });
    const qual = h => h[0] >= 2 || (h[0] === 1 && h[1] >= 4);
    const finish = async (called) => {
      call.disabled = fold.disabled = true; $('#ph-d', root).innerHTML = g.D.map(c => UI.card(c)).join('');
      if (!called) { App.pay("Casino Hold'em", g.stake, 0); UI.res(root, 'lose', `Folded — lost ${fmt(g.stake)}`); }
      else {
        const callBet = g.ante * 2; if (!App.take(callBet)) { fold.disabled = false; call.disabled = false; return toast('Not enough for the call bet', true); } g.stake += callBet;
        await UI.wait(450); g.board.push(g.deck[0], g.deck[1]); $('#ph-b', root).innerHTML = g.board.map(c => UI.card(c)).join(''); await UI.wait(500);
        const ph = CM.best7([...g.P, ...g.board]), dh = CM.best7([...g.D, ...g.board]), dq = qual(dh); $('#ph-pr', root).innerHTML = `<span class="score-tag">${name(ph)}</span>`; $('#ph-dr', root).innerHTML = `<span class="score-tag">${name(dh)}${dq ? '' : ' · does not qualify'}</span>`;
        let pay = 0, msg; if (!dq) { pay = g.ante * 2 + callBet; msg = 'Dealer does not qualify — ante pays, call pushes'; } else { const c = CM.cmpHand(ph, dh); if (c > 0) { pay = g.ante * 2 + callBet * 2; msg = 'You win!'; } else if (c === 0) { pay = g.ante + callBet; msg = 'Tie — push'; } else msg = 'Dealer wins'; }
        pay = rd(pay); App.pay("Casino Hold'em", g.stake, pay); const net = pay - g.stake; UI.res(root, net > 0 ? 'win' : net === 0 ? 'push' : 'lose', `${msg} · ${net > 0 ? 'won ' + fmt(net) : net === 0 ? 'even' : 'lost ' + fmt(-net)}`);
      }
      g = null; deal.disabled = false; UI.lock(root, false); pk();
    };
    deal.onclick = () => {
      const ante = UI.val(root); if (!(ante > 0)) return toast('Enter an ante', true); if (ante * 3 > App.S.balance + 1e-9) return toast('Keep balance for the 2× call bet', true); if (!App.take(ante)) return;
      UI.resClear(root); UI.lock(root, true); const d = Admin.take('ph', genH); g = { ante, stake: ante, P: d.slice(0, 2), D: d.slice(2, 4), board: d.slice(4, 7), deck: d.slice(7) };
      $('#ph-p', root).innerHTML = g.P.map(c => UI.card(c)).join(''); $('#ph-b', root).innerHTML = g.board.map(c => UI.card(c)).join(''); $('#ph-d', root).innerHTML = g.D.map(() => UI.card(null, { back: true })).join(''); $('#ph-dr', root).innerHTML = ''; $('#ph-pr', root).innerHTML = `<span class="score-tag">${name(CM.best7([...g.P, ...g.board]))}</span>`;
      deal.disabled = true; call.disabled = fold.disabled = false; pk();
    };
    call.onclick = () => finish(true); fold.onclick = () => finish(false);
    ctx.peek(pk);
    ctx.onClose(() => { if (g) { const s = g; g = null; App.pay("Casino Hold'em", s.stake, 0); } });
  }
