      CM.ROU_ORDER.forEach((n, i) => { const a0 = wA + i * A - Math.PI / 2 - A / 2, a1 = a0 + A; c.beginPath(); c.moveTo(0, 0); c.arc(0, 0, R - 14, a0, a1); c.closePath(); c.fillStyle = n === 0 ? '#0e8a45' : CM.RED.has(n) ? '#b01626' : '#15181f'; c.fill(); c.strokeStyle = '#d9b45a'; c.lineWidth = 1; c.stroke();
