    $$('[data-bet]', root).forEach(a => a.addEventListener('click', () => { if (busy) return; const v = UI.val(root); if (v > 0) { B.add(a.dataset.bet, v); snd('tick'); } }));
    $('#sb-go', root).onclick = async () => {
      if (busy) return; const tot = B.total(); if (!tot) return toast('Place a chip first', true); if (!App.take(tot)) return; busy = true; UI.lock(root, true); UI.resClear(root); $$('[data-bet]', root).forEach(a => a.classList.remove('win'));
      const bets = Object.assign({}, B.m); B.last = bets; const d = Admin.take('sicbo', genD); const el = $('#sb-dice', root);
      for (let i = 0; i < (Settings.v.quick ? 2 : 9); i++) { el.textContent = [0, 0, 0].map(() => FACE[CM.rint(6)]).join(' '); await sleep(Settings.v.quick ? 20 : 90); }
      el.textContent = d.map(x => FACE[x - 1]).join(' '); let pay = 0; for (const [k, a] of Object.entries(bets)) { const m = CM.sicboPays(k, d); if (m) { pay += a * m; $(`[data-bet="${k}"]`, root).classList.add('win'); } } pay = rd(pay);
      App.pay('Sic Bo', tot, pay); const net = pay - tot; UI.res(root, net > 0 ? 'win' : net === 0 ? 'push' : 'lose', `${d.join(' · ')} (total ${d[0] + d[1] + d[2]}) · ${net > 0 ? 'won ' + fmt(net) : net === 0 ? 'even' : 'lost ' + fmt(-net)}`); busy = false; UI.lock(root, false); B.clear(); pk();
    };
    ctx.peek(pk);
  }
});

/* =====================================================================
   SPORTSBOOK — singles & accumulators. Odds carry a bookmaker margin;
   outcomes are drawn from the margin-free probabilities, so the house
   edge is exactly the overround (no flat win-rate rigging).
   ===================================================================== */
const Sports = {
  data: {
    soccer: [{ t: ['Man United', 'Arsenal'], l: 'Premier League', live: true, sc: [2, 1], o: [2.1, 3.4, 3.8], time: "78'" }, { t: ['Man City', 'Liverpool'], l: 'Premier League', o: [1.9, 3.5, 4.0], time: 'Tomorrow 3PM' }, { t: ['Real Madrid', 'Barcelona'], l: 'La Liga', live: true, sc: [0, 0], o: [2.5, 3.2, 2.9], time: "45'" }, { t: ['Dortmund', 'Bayern Munich'], l: 'Bundesliga', o: [3.1, 3.0, 2.4], time: 'Sat 5PM' }, { t: ['PSG', 'Lyon'], l: 'Ligue 1', live: true, sc: [3, 0], o: [1.4, 4.2, 7.5], time: "67'" }, { t: ['Inter', 'Juventus'], l: 'Serie A', o: [2.3, 3.1, 3.3], time: 'Sun 2PM' }],
    basketball: [{ t: ['Lakers', 'Celtics'], l: 'NBA', live: true, sc: [88, 92], o: [2.1, 1.75], time: 'Q3 8:42' }, { t: ['Warriors', 'Heat'], l: 'NBA', o: [1.8, 2.0], time: 'Tonight 8PM' }, { t: ['Bucks', 'Bulls'], l: 'NBA', live: true, sc: [102, 99], o: [1.6, 2.3], time: 'Q4 3:21' }, { t: ['Mavericks', 'Suns'], l: 'NBA', o: [2.4, 1.6], time: 'Tomorrow 7PM' }],
    football: [{ t: ['Chiefs', 'Raiders'], l: 'NFL', o: [1.5, 2.6], time: 'Sun 4:25PM' }, { t: ['Packers', 'Cowboys'], l: 'NFL', live: true, sc: [17, 14], o: [2.0, 1.9], time: 'Q2 5:31' }, { t: ['49ers', 'Rams'], l: 'NFL', o: [1.7, 2.2], time: 'Mon 8:20PM' }],
    tennis: [{ t: ['Djokovic', 'Alcaraz'], l: 'Wimbledon', live: true, sc: [2, 1], o: [1.85, 1.95], time: 'Set 4' }, { t: ['Sinner', 'Medvedev'], l: 'US Open', o: [1.9, 1.9], time: 'Court 1 2PM' }, { t: ['Swiatek', 'Gauff'], l: "Women's Final", o: [1.5, 2.6], time: 'Saturday' }],
    esports: [{ t: ['Team Liquid', 'NaVi'], l: 'CS2 Major', live: true, sc: [13, 9], o: [1.6, 2.3], time: 'Map 2 Live' }, { t: ['T1', 'Gen.G'], l: 'LoL Worlds', live: true, sc: [1, 0], o: [1.7, 2.1], time: 'Game 2' }, { t: ['EG', 'Vitality'], l: 'Valorant Champions', live: true, sc: [7, 5], o: [2.0, 1.8], time: 'Round 14' }, { t: ['Cloud9', 'FaZe'], l: 'PUBG Invitational', o: [2.2, 1.7], time: 'Sat 11AM' }],
    mma: [{ t: ['Jones', 'Aspinall'], l: 'UFC 310', o: [1.5, 2.6], time: 'Sat 10PM' }, { t: ['Pereira', 'Rountree'], l: 'UFC Fight Night', live: true, sc: ['R2', 'R2'], o: [1.9, 1.9], time: 'R2 2:14' }, { t: ['Oliveira', 'Gaethje'], l: 'Bellator', o: [2.0, 1.85], time: 'Fri 8PM' }]
  },
  names: { soccer: ['⚽', 'Soccer'], basketball: ['🏀', 'Basketball'], football: ['🏈', 'Football'], tennis: ['🎾', 'Tennis'], esports: ['🎮', 'Esports'], mma: ['🥊', 'MMA'] },
  cur: 'soccer', slip: [], mode: 'single', bets: [], bid: 0,
  init() { $('#sport-tabs').innerHTML = Object.entries(this.names).map(([k, [i, n]]) => `<div class="sport-tab" data-s="${k}" onclick="Nav.go('sports','${k}')">${i} ${n}</div>`).join(''); this.setSport('soccer'); },
  setSport(s) { if (!this.data[s]) s = 'soccer'; this.cur = s; $$('.sport-tab').forEach(t => t.classList.toggle('active', t.dataset.s === s)); this.render(); },
  labels(sport, m) { return m.o.length === 3 ? ['Home', 'Draw', 'Away'] : [m.t[0], m.t[1]]; },
  hue: s => { let h = 0; for (const c of s) h = (h * 31 + c.charCodeAt(0)) % 360; return h; },
  render() {
    const s = this.cur; $('#sports-main').innerHTML = this.data[s].map((m, mi) => {
      const lab = this.labels(s, m), key = s + '-' + mi, picked = this.slip.find(p => p.match === key), win = Admin.active() ? Admin.pend('sp-' + key, () => CM.sportsOutcome(m.o)) : -1;
      return `<div class="match-card"><div class="match-league">${esc(m.l)}${m.live ? '<span class="match-live-pill">LIVE</span>' : ''}</div><div class="match-teams">${[0, 1].map(i => `<div class="match-team"><div class="team-badge" style="background:hsl(${this.hue(m.t[i])},55%,38%)">${esc(m.t[i][0])}</div><div class="team-name">${esc(m.t[i])}</div>${m.live ? `<div class="team-score">${m.sc[i]}</div>` : ''}</div>`).join('').replace('</div></div><div class="match-team">', `</div></div><div class="match-mid"><div class="match-vs">VS</div><div class="match-time">${esc(m.time)}</div></div><div class="match-team">`)}</div>
      <div class="match-odds">${m.o.map((o, oi) => `<div class="odd-btn ${picked && picked.oi === oi ? 'sel' : ''}${win === oi ? ' adm' : ''}" onclick="Sports.pick('${s}',${mi},${oi})"><div class="odd-label">${esc(lab[oi])}</div><div class="odd-val">${o.toFixed(2)}</div></div>`).join('')}</div></div>`;
    }).join('');
  },
  pick(s, mi, oi) {
    const key = s + '-' + mi, m = this.data[s][mi], ex = this.slip.findIndex(p => p.match === key);
    if (ex >= 0) { if (this.slip[ex].oi === oi) this.slip.splice(ex, 1); else this.slip[ex] = this.make(s, mi, oi); } else this.slip.push(this.make(s, mi, oi));
    this.render(); this.renderSlip();
  },
  make(s, mi, oi) { const m = this.data[s][mi]; return { match: s + '-' + mi, sport: s, mi, oi, odd: m.o[oi], teams: m.t.join(' v '), pick: this.labels(s, m)[oi] }; },
  setMode(m) { this.mode = m; $$('#slip-mode button').forEach(b => b.classList.toggle('on', b.dataset.m === m)); this.renderSlip(); },
  renderSlip() {
    const it = $('#slip-items'), ft = $('#slip-footer');
    if (!this.slip.length) { it.innerHTML = '<div class="slip-empty">Select odds to add picks</div>'; ft.style.display = 'none'; return; }
    it.innerHTML = this.slip.map((p, i) => `<div class="bsi"><div class="bsi-odd">${p.odd.toFixed(2)}</div><div class="bsi-teams">${esc(p.teams)}</div><div class="bsi-pick">${esc(p.pick)}</div><button class="bsi-rm" onclick="Sports.rm(${i})">✕</button></div>`).join('');
    ft.style.display = 'flex'; this.updateSlip();
  },
  rm(i) { this.slip.splice(i, 1); this.render(); this.renderSlip(); },
  odds() { return this.mode === 'acca' ? this.slip.reduce((a, p) => a * p.odd, 1) : null; },
  updateSlip() {
    const st = parseFloat($('#slip-stake').value) || 0, n = this.slip.length; let total, ret;
    if (this.mode === 'acca') { total = st; ret = st * this.odds(); $('#slip-odds').textContent = this.odds().toFixed(2); }
    else { total = st * n; ret = this.slip.reduce((a, p) => a + st * p.odd, 0); $('#slip-odds').textContent = n > 1 ? n + ' singles' : (this.slip[0] ? this.slip[0].odd.toFixed(2) : '1.00'); }
    $('#slip-total').textContent = fmt(total); $('#slip-pwin').textContent = fmt(ret);
  },
  async place() {
    if (!this.slip.length) return; const st = parseFloat($('#slip-stake').value) || 0; if (!(st > 0)) return toast('Enter a stake', true);
    const legs = this.slip.slice(); const acca = this.mode === 'acca' && legs.length > 1; const total = acca ? st : st * legs.length; if (!App.take(total)) return;
    const bet = { id: ++this.bid, acca, st, legs, total, state: 'pending' }; this.bets.unshift(bet); this.slip = []; this.render(); this.renderSlip(); this.renderBets(); toast('Bet placed — settling…');
    await sleep(Settings.v.quick ? 300 : 1800);
    legs.forEach(l => { const m = this.data[l.sport][l.mi]; l.res = Admin.take('sp-' + l.match, () => CM.sportsOutcome(m.o)); l.won = l.res === l.oi; });
    let pay = 0; if (acca) pay = legs.every(l => l.won) ? rd(st * legs.reduce((a, l) => a * l.odd, 1)) : 0; else pay = rd(legs.reduce((a, l) => a + (l.won ? st * l.odd : 0), 0));
    bet.state = 'done'; bet.pay = pay; App.pay('Sports', total, pay); this.render(); this.renderBets(); toast(pay > 0 ? 'Bet won! +' + fmt(pay) : 'Bet lost', pay <= 0);
  },
  renderBets() {
    const e = $('#my-bets'); if (!this.bets.length) { e.innerHTML = '<div class="hint">No open bets.</div>'; return; }
    e.innerHTML = this.bets.slice(0, 8).map(b => `<div class="b"><div style="display:flex;justify-content:space-between"><b>${b.acca ? 'Accumulator ×' + b.legs.length : b.legs.length > 1 ? b.legs.length + ' singles' : 'Single'}</b><span style="color:${b.state === 'pending' ? 'var(--gold)' : b.pay > 0 ? 'var(--g)' : 'var(--red)'}">${b.state === 'pending' ? 'settling…' : b.pay > 0 ? '+' + fmt(b.pay) : 'lost'}</span></div>${b.legs.map(l => `<div class="hint" style="font-size:10px">${l.won === undefined ? '•' : l.won ? '✅' : '❌'} ${esc(l.teams)} — ${esc(l.pick)} @ ${l.odd.toFixed(2)}</div>`).join('')}<div class="hint">stake ${fmt(b.total)}</div></div>`).join('');
  }
};

/* =====================================================================
   BOOT
   ===================================================================== */
(function boot() {
  Settings.apply(); App.load(); Settings.syncUI(); Auth.ui(); Admin.ui();
  const order = ['crash', 'aviator', 'dice', 'limbo', 'mines', 'plinko', 'keno', 'wof', 'hilo', 'towers', 'coinflip', 'diamonds', 'slots_candy', 'slots_olympus', 'slots_fish', 'slots_egypt', 'slots_wolf', 'slots_aztec', 'blackjack', 'roulette', 'baccarat', 'dragontigger', 'threecard', 'poker', 'videopoker', 'sic_bo', 'scratchcard', 'hotcold'];
  Games.list.sort((a, b) => order.indexOf(a.id) - order.indexOf(b.id));
  Games.render(); Sports.init(); Banner.init(); Settings.startSession();
  $$('.stake-btn').forEach(b => b.classList.toggle('active', b.dataset.s === App.stake));
  App.updateBal(); App.renderProfile(); Nav.go('home', 'all');
  for (let i = 0; i < 8; i++) Live.tick(); setInterval(() => Live.tick(), 2600);
  let jp = 1284930; setInterval(() => { jp += Math.floor(CM.rnd() * 40); $('#jackpot').textContent = Settings.v.cur + jp.toLocaleString('en-US'); }, 1500);
  window.addEventListener('beforeunload', () => { try { App.save(); } catch (e) {} });
})();

/* keyboard: Space = main action of the open game */
document.addEventListener('keydown', e => {
  if (!Settings.v.keys || e.repeat) return; const t = e.target; if (e.code !== 'Space') { if (t && /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName)) return; if (e.key === 'm' || e.key === 'M') { Settings.set('sound', !Settings.v.sound); Settings.syncUI(); toast(Settings.v.sound ? '🔊 Sound on' : '🔇 Muted'); } else if (e.key === '/') { e.preventDefault(); Games.close(); Nav.go('home'); $('#search').focus(); } return; } if (t && /^(INPUT|TEXTAREA|SELECT|BUTTON)$/.test(t.tagName)) return;
  let b = null; if (typeof Aviator !== 'undefined' && Aviator.el) b = Aviator.el.querySelector('#avx-go');
  else if (Games.active) b = document.querySelector('#modal-wrap .gm-ctrl .act:not([disabled]):not(.ghost)');
  if (b) { e.preventDefault(); b.click(); }
});

</script>
</body>
</html>
";

  const $ = (id) => document.getElementById(id);
  const setStatus = (msg) => { $("statusText").textContent = msg; };

  // ---------- IndexedDB ----------
  function openDB() {
    return new Promise((resolve, reject) => {
      const req = indexedDB.open(DB_NAME);
      req.onupgradeneeded = (e) => {
        const db = e.target.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) db.createObjectStore(STORE_NAME);
      };
      req.onsuccess = () => {
        const db = req.result;
        if (db.objectStoreNames.contains(STORE_NAME)) return resolve(db);
        const next = (db.version || 1) + 1;
        db.close();
        const up = indexedDB.open(DB_NAME, next);
        up.onupgradeneeded = (e) => {
          const d = e.target.result;
          if (!d.objectStoreNames.contains(STORE_NAME)) d.createObjectStore(STORE_NAME);
        };
        up.onsuccess = () => resolve(up.result);
        up.onerror = () => reject(up.error);
      };
      req.onerror = () => reject(req.error);
    });
  }
  const idb = (db, mode, fn) => new Promise((resolve, reject) => {
    const req = fn(db.transaction(STORE_NAME, mode).objectStore(STORE_NAME));
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });

  async function refreshCache() {
    const badge = $("cacheBadge"), text = $("cacheText");
    try {
      const db = await openDB();
      const n = await idb(db, "readonly", (s) => s.count(GAME_KEY));
      badge.setAttribute("class", "badge" + (n ? " ok" : ""));
      text.textContent = n ? "Cached in this browser. Launches instantly." : "Not downloaded yet.";
    } catch (e) {
      badge.setAttribute("class", "badge");
      text.textContent = "Cache unavailable in this browser.";
    }
  }

  // ---------- about:blank ----------
  function openBlank(loadingMsg) {
    const win = window.open("about:blank", "_blank");
    if (!win) { setStatus("Pop-up blocked! Allow pop-ups for this page and try again."); return null; }
    if (loadingMsg) {
      try {
        win.document.write('<body style="margin:0;background:#05060d;color:#b7b3c7;font:15px system-ui,sans-serif;display:grid;place-items:center;height:100vh">' + loadingMsg + '</body>');
      } catch (e) {}
    }
    return win;
  }
  function render(win, html, base) {
    let out = html;
    if (base && !/<base\s/i.test(out)) out = '<base href="' + base + '">' + out;
    win.document.open();
    win.document.write(out);
    win.document.close();
  }

  // ---------- recently launched ----------
  const RKEY = "launcherHub.recent";
  function getRecent() {
    try { return JSON.parse(localStorage.getItem(RKEY) || "[]").filter((k) => LABELS[k]); } catch (e) { return []; }
  }
  function remember(id) {
    try { localStorage.setItem(RKEY, JSON.stringify([id].concat(getRecent().filter((x) => x !== id)).slice(0, 4))); } catch (e) {}
    renderRecent();
  }
  function renderRecent() {
    const box = $("recentList");
    while (box.firstChild) box.removeChild(box.firstChild);
    const r = getRecent();
    if (!r.length) {
      const h = document.createElementNS(XHTML, "span");
      h.setAttribute("class", "hint");
      h.textContent = "Nothing launched yet.";
      box.appendChild(h);
      return;
    }
    r.forEach((id) => {
      const b = document.createElementNS(XHTML, "button");
      b.setAttribute("type", "button");
      b.setAttribute("class", "chip-btn");
      b.setAttribute("data-action", id === "mc" ? "mc-launch" : id);
      b.textContent = LABELS[id];
      box.appendChild(b);
    });
  }

  // ---------- Eaglercraft ----------
  function showProgress(on) { $("prog").setAttribute("class", "prog" + (on ? " on" : "")); }
  function progress(got, total) {
    const mb = (n) => (n / 1048576).toFixed(1);
    const fill = $("fill");
    if (total) {
      fill.setAttribute("class", "fill");
      fill.style.width = Math.min(100, (got / total) * 100).toFixed(1) + "%";
      $("ptxt").textContent = Math.round((got / total) * 100) + "%  ·  " + mb(got) + " / " + mb(total) + " MB";
    } else {
      fill.setAttribute("class", "fill ind");
      $("ptxt").textContent = mb(got) + " MB downloaded";
    }
  }
  async function download() {
    const resp = await fetch(RAW_URL);
    if (!resp.ok) throw new Error("HTTP " + resp.status);
    if (!resp.body || !resp.body.getReader) return await resp.text();
    const total = parseInt(resp.headers.get("content-length") || "0", 10);
    const reader = resp.body.getReader(), chunks = [];
    let got = 0;
    showProgress(true); progress(0, total);
    for (;;) {
      const r = await reader.read();
      if (r.done) break;
      chunks.push(r.value); got += r.value.length; progress(got, total);
    }
    return await new Blob(chunks).text();
  }
  async function launchMc() {
    const win = openBlank("Loading Eaglercraft…");
    if (!win) return;
    try {
      setStatus("Opening IndexedDB…");
      const db = await openDB();
      setStatus("Checking cached version…");
      let html = await idb(db, "readonly", (s) => s.get(GAME_KEY));
      if (html && html.slice(0, 100).trim().startsWith(LFS)) html = null;
      if (html) {
        setStatus("Loaded from cache. Launching…");
      } else {
        setStatus("Downloading game file (~89 MB)…");
        html = await download();
        if (html.slice(0, 100).trim().startsWith(LFS)) throw new Error("Received LFS pointer instead of file.");
        setStatus("Saving to cache…");
        await idb(db, "readwrite", (s) => s.put(html, GAME_KEY));
        showProgress(false);
      }
      render(win, html, BASE_URL);
      remember("mc");
      refreshCache();
      setStatus("Eaglercraft launched!");
    } catch (err) {
      console.error(err);
      showProgress(false);
      try { win.close(); } catch (e) {}
      setStatus("Error: " + err.message);
    }
  }
  async function clearMc() {
    try {
      setStatus("Clearing stored cache…");
      const db = await openDB();
      await idb(db, "readwrite", (s) => s.delete(GAME_KEY));
      await refreshCache();
      setStatus("Cache cleared successfully!");
    } catch (err) {
      console.error(err);
      setStatus("Error clearing cache: " + err.message);
    }
  }

  // ---------- simple embedded pages ----------
  function openPage(id, html) {
    const win = openBlank();
    if (!win) return;
    render(win, html);
    remember(id);
    setStatus(LABELS[id] + " launched!");
  }

  const ACTIONS = {
    "mc-launch": launchMc,
    "mc-clear": clearMc,
    vault: () => openPage("vault", VAULT_HTML),
    noct: () => openPage("noct", NOCTURNE_HTML),
    casino: () => openPage("casino", CASINO_HTML)
  };
  document.addEventListener("click", (e) => {
    const t = e.target && e.target.closest ? e.target.closest("[data-action]") : null;
    const fn = t && ACTIONS[t.getAttribute("data-action")];
    if (fn) fn();
  });

  function fit() {
    const root = document.querySelector(".root");
    const k = window.innerWidth / (screen.width || window.innerWidth);
    if (navigator.maxTouchPoints > 0 && screen.width < 700 && k > 1.25) {
      root.style.width = (100 / k) + "%";
      root.style.height = (100 / k) + "%";
      root.style.transformOrigin = "0 0";
      root.style.transform = "scale(" + k + ")";
    } else {
      root.style.width = "100%"; root.style.height = "100%"; root.style.transform = "";
    }
    root.setAttribute("class", "root" + (root.clientWidth < 640 ? " narrow" : ""));
  }
  window.addEventListener("resize", fit);
  window.addEventListener("orientationchange", fit);
  fit();

  renderRecent();
  refreshCache();
})();
